_LOCALE_FALLBACK = "en"


def _load_locales():
    raw = (_LOCALES_JSON or "").strip()
    if raw and not raw.startswith("@@"):
        try:
            return json.loads(raw)
        except Exception:
            pass
    # Unresolved marker = running the template straight from the repository (tests, tooling).
    # Read the source locales so those paths see real text too.
    try:
        here = os.path.dirname(os.path.abspath(globals().get("__file__", "") or "."))
        folder = os.path.join(os.path.dirname(here), "elyx_plugin", "chimeranft", "locales")
        tables = {}
        for name in sorted(os.listdir(folder)):
            if name.startswith("strings_") and name.endswith(".json"):
                with open(os.path.join(folder, name), "r", encoding="utf-8") as handle:
                    tables[name[len("strings_"):-len(".json")]] = json.load(handle)
        return tables
    except Exception:
        return {}


_LOCALES = _load_locales()
_LOCALE_CACHE = []


def _device_language():
    """Cached: this is read once per string lookup and must never touch a locale API per row."""
    if _LOCALE_CACHE:
        return _LOCALE_CACHE[0]
    lang = _LOCALE_FALLBACK
    try:
        from org.telegram.messenger import LocaleController
        value = str(LocaleController.getInstance().getCurrentLocale().getLanguage() or "")
        if value:
            lang = value.lower()
    except Exception:
        try:
            from java.util import Locale
            value = str(Locale.getDefault().getLanguage() or "")
            if value:
                lang = value.lower()
        except Exception:
            pass
    if lang not in _LOCALES and _LOCALE_FALLBACK in _LOCALES:
        lang = _LOCALE_FALLBACK
    _LOCALE_CACHE.append(lang)
    return lang


def S(key, *args, **kwargs):
    """One localized string. Extra arguments are applied with str.format, exactly like the
    callable form of Elyx's `strings`."""
    key = str(key)
    value = None
    if _elyx_strings is not None:
        try:
            candidate = _elyx_strings[key]
            # A missing key echoes itself back on some cores — that is a miss, not a translation.
            if candidate and str(candidate) != key:
                value = str(candidate)
        except Exception:
            value = None
    if value is None:
        table = _LOCALES.get(_device_language()) or {}
        value = table.get(key)
        if value is None:
            value = (_LOCALES.get(_LOCALE_FALLBACK) or {}).get(key)
    if value is None:
        return key
    if args or kwargs:
        try:
            return str(value).format(*args, **kwargs)
        except Exception:
            return str(value)
    return str(value)


