_PAYLOAD_SHA256 = "9ed28c84815fa65ca2d67881fadc6e4d3ed02b76ee35a9b278d9a0bcf77ab0fe"
_RT_PKG = "chimeranft_runtime"
_RT_ALIAS = "_chimeranft_rt_cat"
_PACKAGED_HELPERS = {}


def _packaged_helper(name):
    """Load a helper stored beside loader.py without relying on sys.path/package state."""
    key = str(name or "").strip()
    if key in _PACKAGED_HELPERS:
        return _PACKAGED_HELPERS[key]
    loader_file = os.path.abspath(str(globals().get("__file__", "") or ""))
    if not loader_file:
        return None
    # .py first, .pyc second: a COMPILED build (elyb -c) ships these helpers as bytecode. Only the
    # entry point is kept as source there (.elyxbuilder/config.yml → compilationIgnore), so looking
    # for "<name>.py" alone left the payload extractor and the native loader silently absent.
    # spec_from_file_location picks the right loader from the extension.
    path = ""
    for candidate in (key + ".py", key + ".pyc"):
        probe = os.path.join(os.path.dirname(loader_file), candidate)
        if os.path.isfile(probe):
            path = probe
            break
    if not path:
        return None
    module_name = "_chimeranft_" + key
    spec = _ilu.spec_from_file_location(module_name, path)
    module = _ilu.module_from_spec(spec)
    _sys.modules[module_name] = module
    spec.loader.exec_module(module)
    _PACKAGED_HELPERS[key] = module
    return module

_STR_CLS = None
_INT_T = None
_LONG_T = None

# Native Telegram SettingsActivity entry (same mechanism as PackIt).
_MAIN_SETTINGS_ID = 880174
_PACKIT_SETTINGS_ID = 880099
_MAIN_SETTINGS_ICON_TAG = "chimeranft_settings_icon"
_MAIN_SETTINGS_ICON_BG = 0xFFE6D9F5 - 0x100000000
_MAIN_SETTINGS_ICON_FG = 0xFF615EA4 - 0x100000000
_ACCESS_CACHE_TTL_SEC = 300


def _cause(e):
    msg = repr(e)
    try:
        c = e.getCause()
        d = 0
        while c is not None and d < 6:
            msg += " <- " + str(c)
            c = c.getCause(); d += 1
    except Exception:
        pass
    return msg


def _selected_account():
    try:
        return int(UserConfig.selectedAccount or 0)
    except Exception:
        return 0


def _cache_uid():
    # MUST match production: keyed by account SLOT, not clientUserId.
    return 10000000000 + _selected_account()


def _real_uid():
    try:
        cfg = UserConfig.getInstance(_selected_account())
        return _config_user_id(cfg)
    except Exception:
        return 0


def _config_user_id(cfg):
    """Resolve a Telegram account id across exteraGram/AyuGram UserConfig shapes."""
    if cfg is None:
        return 0
    try:
        uid = int(getattr(cfg, "clientUserId", 0) or 0)
    except Exception:
        uid = 0
    if uid <= 0:
        try:
            uid = int(cfg.getClientUserId() or 0)
        except Exception:
            uid = 0
    if uid <= 0:
        try:
            uid = int(getattr(cfg.getCurrentUser(), "id", 0) or 0)
        except Exception:
            uid = 0
    return uid if uid > 0 else 0


def _real_username():
    try:
        cfg = UserConfig.getInstance(_selected_account())
        user = cfg.getCurrentUser()
        return str(getattr(user, "username", "") or "").strip().lstrip("@")
    except Exception:
        return ""


def _all_account_ids():
    """Every account signed in to THIS client, not just the selected one.

    A ban belongs to the install, so the gate has to know all of them: otherwise switching profiles
    is enough to walk around it. Mirrors Main.localAccountIds() on the Java side."""
    ids = []
    try:
        try:
            limit = int(getattr(UserConfig, "MAX_ACCOUNT_COUNT", 16) or 16)
        except Exception:
            limit = 16
        if limit <= 0 or limit > 64:
            limit = 16
        for slot in range(limit):
            try:
                cfg = UserConfig.getInstance(slot)
                if cfg is None:
                    continue
                try:
                    if not cfg.isClientActivated():
                        continue
                except Exception:
                    pass
                uid = _config_user_id(cfg)
                if uid > 0 and uid not in ids:
                    ids.append(uid)
            except Exception:
                continue
    except Exception:
        pass
    return ids


def _access_cache_path():
    return os.path.join(_resolve_data_dir(), "plugin_access.json")


def _access_client_id():
    """Opaque per-install id shared with Main.java; never derived from device hardware."""
    try:
        import uuid
        path = os.path.join(_resolve_data_dir(), "plugin_client_id")
        try:
            with open(path, "r", encoding="ascii") as fh:
                value = fh.read().strip().lower()
            if 16 <= len(value) <= 96 and all(c.isalnum() or c in "-_" for c in value):
                return value
        except Exception:
            pass
        value = str(uuid.uuid4())
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".py.tmp"
        with open(tmp, "w", encoding="ascii") as fh:
            fh.write(value)
            fh.flush()
            try:
                os.fsync(fh.fileno())
            except Exception:
                pass
        try:
            os.replace(tmp, path)
        except Exception:
            try:
                os.remove(tmp)
            except Exception:
                pass
        return value
    except Exception:
        return ""


def _account_usernames():
    """Compact account-id -> username snapshot for username-only moderation decisions."""
    values = []
    try:
        limit = int(getattr(UserConfig, "MAX_ACCOUNT_COUNT", 16) or 16)
    except Exception:
        limit = 16
    for slot in range(max(0, min(64, limit))):
        try:
            cfg = UserConfig.getInstance(slot)
            if cfg is None or not cfg.isClientActivated():
                continue
            uid = _config_user_id(cfg)
            user = cfg.getCurrentUser()
            username = str(getattr(user, "username", "") or "").strip().lstrip("@")
            if uid > 0 and username:
                values.append(str(uid) + ":" + username)
        except Exception:
            continue
    return ",".join(values)


def _load_access_cache():
    return {}  # [noban] persisted access state is never read
    try:
        path = _access_cache_path()
        if not path or not os.path.exists(path):
            return {}
        with open(path, "r", encoding="utf-8") as fh:
            value = json.load(fh)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _save_access_cache(value):
    return  # [noban] bans are never persisted
    try:
        path = _access_cache_path()
        if not path:
            return
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(value, fh, ensure_ascii=False, separators=(",", ":"))
        os.replace(tmp, path)
    except Exception:
        pass


def _stored_ban_ids(cached):
    """Deserialize the ban set stored in a cache/decision dict. Pure format-reading —
    the gating POLICY lives in the compiled Gate core class; this only unpacks what was
    persisted so it can be fed back to the decision or shown in the gate."""
    out = set()
    try:
        for value in (cached.get("banned_ids") or []):
            try:
                value = int(value)
            except Exception:
                continue
            if value > 0:
                out.add(value)
    except Exception:
        pass
    # Legacy decisions did not have banned_ids. Use their single id only as a fallback: adding
    # user_id unconditionally re-inserts an account which Gate.post has just explicitly unbanned.
    if not out:
        try:
            value = int(cached.get("denied_account") or cached.get("user_id") or 0)
            if value > 0:
                out.add(value)
        except Exception:
            pass
    return out


# ---- access-gate policy (compiled into the DEX core: com.chimeranft.core.Gate) ---------------
# The DECISION is not in this file. It is reached over the String→String bridge on the Gate
# class, which the loader binds into _GATE_CALL before the check runs (see on_plugin_load). A
# native libcompat.so was tried first, but Android blocks dlopen of a runtime-written .so from
# the plugin sandbox, so the logic lives in the byte-code core the whole plugin already runs on.
# Actions mirror Gate.java.
_GATE_RETURN_CACHED = 0
_GATE_ALLOW_UID0 = 2
_GATE_DEFERRED = 3
_GATE_DO_NETWORK = 4
# A callable (json_in) -> dict set by _bind_gate(gate_cls) once the core class is loaded.
_GATE_CALL = None
_GATE_ERR = ""


def _bind_gate(gate_cls):
    """Wire _GATE_CALL to the compiled Gate class. Idempotent; safe to call again with the
    Main-era class loader. Returns True on success."""
    global _GATE_CALL, _GATE_ERR
    if gate_cls is None:
        _GATE_ERR = "gate class not loaded"
        _GATE_CALL = None
        return False
    try:
        str_cls = _STR_CLS or JavaClass.forName("java.lang.String")
        pre = gate_cls.getMethod("pre", str_cls)
        post = gate_cls.getMethod("post", str_cls)

        def _call(which, payload):
            method = pre if which == "pre" else post
            raw = method.invoke(None, json.dumps(payload))
            return json.loads(str(raw))

        _GATE_CALL = _call
        _GATE_ERR = ""
        return True
    except Exception as bind_error:
        _GATE_ERR = "bind: " + _cause(bind_error)
        _GATE_CALL = None
        return False


def _blocked_decision(now, uid, cached, reason=None):
    """The fail-closed verdict, shaped like a server deny so the gate renders normally."""
    return {
        "allowed": False,
        "reason": str(reason or "Доступ к плагину запрещён администрацией."),
        "report_id": str((cached or {}).get("report_id") or ""),
        "checked_at": int(now),
        "user_id": int(uid),
        "gate_shown": bool((cached or {}).get("gate_shown")),
        "banned_client": True,
    }


def _check_plugin_access(network=True):
    """Fail open on a temporary outage, but never forget a cached deny decision.

    `network=False` is the PLUGIN-LOAD path and must not touch the socket. Everything after the
    call site — the DEX class loader, `Main.init`, the Store load, every hot-path hook — used to
    wait on a DNS + TCP + HTTP round trip that only short-circuits inside `_ACCESS_CACHE_TTL_SEC`,
    i.e. on essentially every real cold start. On a captive or dead network that is the full 3 s
    timeout with the plugin contributing nothing to the first frames, and an ANR window if Elyx
    calls us on the main thread — precisely the "не ждать сервер перед первым кадром" rule (§16).
    A client that is ALREADY marked banned locally is the one exception: it is going to be gated
    regardless, so it pays for the request and keeps instant unban (§12 «отзыв бана работает»).

    The ban is per CLIENT, not per account: once any account of this install is denied, the gate
    records every account it held (`banned_client` + `banned_ids`), and from then on ANY of them is
    gated — including offline, and including a profile switch, which used to be the way around it.
    Revocation still works: the server is asked about the selected account on every launch, and an
    explicit «allowed» drops exactly that id from the local list."""
    import time
    # [noserver] access gate disabled: no uid/username/account data ever leaves the device
    return {"allowed": True, "checked_at": int(time.time()), "offline": True}
    cached = _load_access_cache()
    now = int(time.time())
    local_ids = _all_account_ids()
    uid = _real_uid()
    if uid > 0 and uid not in local_ids:
        local_ids.append(uid)

    if _GATE_CALL is None:
        # The compiled Gate is not bound. It normally is (the whole plugin runs on this same DEX
        # core), so this only happens if the core itself failed to load — in which case the plugin
        # is non-functional anyway. Fail OPEN rather than lock out a legitimate user over a core
        # load hiccup. Never erase an already-persisted deny here: a missing/broken Gate must not
        # become a one-launch tool for deleting the device-ban marker. Unknown clients still fail
        # open so a bad build cannot lock every legitimate user out.
        if cached.get("allowed") is False:
            return cached
        return {"allowed": True, "checked_at": now, "gate_unavailable": True,
                "gate_error": _GATE_ERR}

    # ---- pre-network gate: hand the cached state to the compiled Gate, act on its verdict ----
    banned_list = sorted(_stored_ban_ids(cached)) if cached.get("allowed") is False else []
    cached_allowed = 1 if cached.get("allowed") is True else (0 if cached.get("allowed") is False else -1)
    try:
        pre = _GATE_CALL("pre", {
            "network": 1 if network else 0, "now": now, "ttl": int(_ACCESS_CACHE_TTL_SEC),
            "uid": uid, "has_cache": 1 if cached else 0, "cached_allowed": cached_allowed,
            "checked_at": int(cached.get("checked_at", 0) or 0),
            "banned_client": 1 if cached.get("banned_client") else 0, "banned": banned_list,
        })
        action = int(pre.get("action"))
        client_banned = bool(pre.get("client_banned"))
    except Exception as gate_error:
        # A bridge call that throws is a broken core, not a new ban. Preserve an existing deny,
        # but fail open for a client which was never marked.
        if cached.get("allowed") is False:
            return cached
        return {"allowed": True, "checked_at": now, "gate_unavailable": True,
                "gate_error": "pre: " + _cause(gate_error)}

    if action == _GATE_RETURN_CACHED:
        return cached
    if action == _GATE_ALLOW_UID0:
        return {"allowed": True, "checked_at": now}
    if action == _GATE_DEFERRED:
        # Load path, no local ban → allow now, revalidate off-thread. The server is still asked on
        # every start (§12), just not before the first frame; a deny that arrives later is delivered
        # live by SyncClient.accessLoop → setAccessDeniedCallback → _handle_live_access_denied.
        return {"allowed": True, "checked_at": int(cached.get("checked_at", 0) or 0),
                "deferred": True, "gate_shown": bool(cached.get("gate_shown"))}
    # action == _GATE_DO_NETWORK
    try:
        from urllib.parse import quote
        from urllib.request import Request, urlopen
        username = _real_username()
        url = CHIMERANFT_API_BASE.rstrip("/") + "/api/v1/access/" + str(uid)
        query = []
        if username:
            query.append("username=" + quote(username))
        siblings = ",".join(str(value) for value in local_ids if value != uid)
        if siblings:
            # The server needs the whole client to blacklist it; sending it here means a server that
            # learns to read the parameter starts propagating without a plugin update.
            query.append("siblings=" + quote(siblings))
        client_id = _access_client_id()
        if client_id:
            query.append("client_id=" + quote(client_id))
        account_usernames = _account_usernames()
        if account_usernames:
            query.append("account_usernames=" + quote(account_usernames))
        if query:
            url += "?" + "&".join(query)
        req = Request(url, headers={"User-Agent": "eblanNFT-access/1"})
        with urlopen(req, timeout=3) as response:
            data = json.loads(response.read().decode("utf-8"))
        allowed = bool(data.get("allowed", True))

        # ---- fold the verdict into the ban marker: the compiled Gate owns this too ----
        post = _GATE_CALL("post", {
            "server_allowed": 1 if allowed else 0,
            "client_banned": 1 if client_banned else 0,
            "clear_client": 1 if data.get("client_allowed") else 0,
            "banned": banned_list, "local": [int(v) for v in local_ids], "uid": uid,
        })
        new_banned = [int(v) for v in (post.get("banned_ids") or [])]
        effective_allowed = bool(post.get("allowed"))

        decision = {
            # Gate.post returns the installation-wide verdict. A raw `allowed:true` for the
            # selected sibling is not enough while any account from this client remains banned.
            "allowed": effective_allowed,
            "reason": str(data.get("reason") or cached.get("reason")
                          or "Доступ к плагину запрещён администрацией."),
            "report_id": str(data.get("report_id") or cached.get("report_id") or ""),
            "checked_at": now,
            "user_id": uid,
            # Sticky across refreshes: it records that the gate was already presented
            # once, which is what turns the NEXT launch into an automatic uninstall.
            "gate_shown": bool(cached.get("gate_shown")),
        }
        if post.get("banned_client"):
            decision["banned_client"] = True
            decision["banned_ids"] = new_banned
        _save_access_cache(decision)
        if not allowed:
            _report_banned_client(uid, decision, local_ids)
        return decision
    except Exception:
        if client_banned:
            return cached
        return cached if cached else {"allowed": True, "checked_at": now, "offline": True}


def _report_banned_client(banned_id, decision, local_ids):
    """Hand the server every account of this client so it can blacklist them too.

    Fire-and-forget on a daemon thread: the gate is about to be shown and the plugin may uninstall
    itself, so this can neither block nor raise. A server without the endpoint answers 404 and only
    the local marker applies (which still covers this install)."""
    return  # [noserver] never report accounts to the server
    try:
        import threading

        def _send():
            try:
                from urllib.request import Request, urlopen
                payload = {
                    "banned_id": int(banned_id),
                    "accounts": [{"id": int(value)} for value in local_ids if int(value) > 0],
                    "reason": str(decision.get("reason") or ""),
                    "report_id": str(decision.get("report_id") or ""),
                    "client": "chimeranft-loader/" + str(_LOADER_VERSION),
                    "client_id": _access_client_id(),
                    "ts": int(decision.get("checked_at") or 0),
                }
                body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
                req = Request(CHIMERANFT_API_BASE.rstrip("/") + "/api/v1/access/report", data=body,
                              headers={"Content-Type": "application/json",
                                       "User-Agent": "eblanNFT-access/1"})
                urlopen(req, timeout=4).read()
            except Exception:
                pass

        worker = threading.Thread(target=_send, name="chimeranft-access-report")
        worker.daemon = True
        worker.start()
    except Exception:
        pass


def _gv(obj, name, default=None):
    """Read a Java field by name: public attr → public field → declared field."""
    if obj is None:
        return default
    try:
        return getattr(obj, name)
    except Exception:
        pass
    try:
        c = obj.getClass()
        while c is not None:
            try:
                f = c.getDeclaredField(name)
                f.setAccessible(True)
                return f.get(obj)
            except Exception:
                c = c.getSuperclass()
    except Exception:
        pass
    return default


# ---- native catalog hooks (cold path: only fire while ResaleGiftsFragment is open) ----
if MethodHook is not None:
    class _GiftToastGuard(MethodHook):
        """Suppress exteraGram's own «Подарок не доставлен получателю …» bulletin.

        The visual send/purchase is local-only in the no-server build: the core fakes
        the API response, but exteraGram (Telegram 12+) ALSO tries to deliver the
        gift as a REAL message; the server rejects the fake gift and Telegram shows
        its own failure bulletin even though the visual message is already in the
        chat. That text lives in Telegram's own resources (it is not in the plugin's
        dex or locales), so the guard matches the bulletin by its rendered text and
        skips show() entirely — every other bulletin keeps working.
        """
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        @staticmethod
        def _collect_text(v, out):
            try:
                gt = getattr(v, "getText", None)
                if gt is not None:
                    s = str(gt() or "")
                    if s.strip():
                        out.append(s)
            except Exception:
                pass
            try:
                gv = getattr(v, "getView", None)
                if gv is not None:
                    _child = gv()
                    if _child is not None and _child is not v:
                        _GiftToastGuard._collect_text(_child, out)
            except Exception:
                pass
            try:
                gc = getattr(v, "getChildCount", None)
                if gc is not None:
                    for i in range(int(gc())):
                        _GiftToastGuard._collect_text(v.getChildAt(i), out)
            except Exception:
                pass

        def before_hooked_method(self, param):
            try:
                v = param.thisObject
                if v is None:
                    return
                out = []
                self._collect_text(v, out)
                joined = " ".join(out)
                _bad = ("Подарок не доставлен" in joined
                        or "не доставлен получателю" in joined
                        or "MESSAGE_ID_INVALID" in joined.upper())
                # log EVERY distinct bulletin text once (capped) — full visibility
                # into what the client tries to show, for exact diagnosis.
                try:
                    _seen = getattr(self, "_seen_texts", None)
                    if _seen is None:
                        _seen = set()
                        self._seen_texts = _seen
                    if len(_seen) > 64:
                        _seen.clear()
                    _key = "B:" + joined[:80]
                    if _key not in _seen:
                        _seen.add(_key)
                        _diag("[gift-toast] bulletin: " + (joined[:120] or "(no text)"))
                except Exception:
                    pass
                if _bad:
                    try:
                        _diag("[gift-toast] suppressed bulletin: " + joined[:140])
                    except Exception:
                        pass
                    param.setResult(None)
            except Exception:
                pass

    class _GiftNotifGuard(MethodHook):
        """Layer 2: the same failure banner posted as a REAL Android notification.

        When the bulletin goes out through showAsNotification() or any other path
        that lands in NotificationManager, the phone itself paints it as a system
        heads-up — the user sees it as «системное уведомление». Match the posted
        notification's extras text and drop the post; every other notification
        (messages, downloads) is untouched.
        """
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                n = param.args[-1] if param.args else None
                if n is None:
                    return
                ex = getattr(n, "extras", None)
                if ex is None:
                    return
                title = text = ""
                try: title = str(ex.getCharSequence("android.title") or "")
                except Exception: pass
                try: text = str(ex.getCharSequence("android.text") or "")
                except Exception: pass
                joined = (title + " " + text).strip()
                if not joined:
                    return
                if "Подарок не доставлен" in joined or "не доставлен получателю" in joined:
                    try:
                        _diag("[gift-toast] suppressed notification: " + joined[:140])
                    except Exception:
                        pass
                    param.setResult(None)
            except Exception:
                pass

    class _GiftToastToastGuard(MethodHook):
        """Layer 3: the core's own purchase-failure TOAST — the actual culprit.

        GiftHook.showPurchaseMessage posts a plain android.widget.Toast via postUi
        with the text «Подарок не доставлен получателю — нет связи с сервером».
        In a no-server build the sync hop is dead BY DESIGN, so this failure toast
        fires on every visual buy and looks like a system banner at the bottom of
        the screen. Two hooks cooperate: makeText() captures the text BEFORE the
        view exists and marks the Toast object (identity hash); show() then drops
        marked toasts. Text probes at show() time are kept as a fallback.
        """
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin
            self._seen = set()
            self._marks = {}
            self._keep = []
            self._pending = None

        def _idh(self, obj):
            try:
                return hash(str(obj))
            except Exception:
                return None

        def mark(self, obj):
            h = self._idh(obj)
            if h is None:
                return
            if len(self._keep) > 32:
                self._keep = []
                self._marks = {}
            self._marks[h] = True
            self._keep.append(obj)

        def _marked(self, obj):
            h = self._idh(obj)
            return h is not None and bool(self._marks.get(h))

        def _is_bad(self, text):
            return ("Подарок не доставлен" in text
                    or "не доставлен получателю" in text
                    or "MESSAGE_ID_INVALID" in text.upper())

        def _log_once(self, prefix, text):
            try:
                if len(self._seen) > 96:
                    self._seen.clear()
                _key = prefix + text[:80]
                if _key not in self._seen:
                    self._seen.add(_key)
                    _diag(prefix + (text[:120] or "(no text)"))
            except Exception:
                pass

        def note_bad(self):
            try:
                import time as _time
                self._last_bad_ms = _time.time()
            except Exception:
                pass

        def _bad_recent(self):
            ms = getattr(self, "_last_bad_ms", 0)
            if not ms:
                return False
            try:
                import time as _time
                return (_time.time() - ms) < 5000
            except Exception:
                return False

        def make_dummy(self, param):
            """A neutral empty Toast to swap in instead of the failure toast."""
            if getattr(self, "_reentr", False):
                return None
            self._reentr = True
            try:
                ctx = None
                try: ctx = param.args[0] if param.args else None
                except Exception: ctx = None
                if ctx is None:
                    return None
                _T = JavaClass.forName("android.widget.Toast")
                return _T.makeText(ctx, "", 0)
            except Exception:
                return None
            finally:
                self._reentr = False

        def before_hooked_method(self, param):
            try:
                v = param.thisObject
                if v is None:
                    return
                out = []
                _GiftToastGuard._collect_text(v, out)
                joined = " ".join(out).strip()
                self._log_once("[gift-toast] toast: ", joined)
                _ctx_hit = False
                _pend = getattr(self, "_pending", None)
                if _pend is not None and _bad_recent(self):
                    try:
                        _ctx_hit = str(getattr(v, "getContext", lambda: None)()) == _pend
                    except Exception:
                        _ctx_hit = False
                _kill = (self._marked(v) or self._is_bad(joined)
                         or _ctx_hit
                         or (joined == "" and self._bad_recent()))
                if _kill:
                    self._log_once("[gift-toast] suppressed toast: ", joined or "(marked at makeText)")
                    h = self._idh(v)
                    if h is not None:
                        try: del self._marks[h]
                        except Exception: pass
                    param.setResult(None)
                    self._pending = None
            except Exception:
                pass

    class _ToastMakeTextHook(MethodHook):
        """Captures the toast text at makeText() time — before any view exists.
        Three independent kills: (1) mutate the text arg to empty before the
        original runs, (2) swap the returned Toast for a neutral empty one via
        setResult, (3) mark the dummy so show() drops it outright. param.result is
        NOT relied on — the elyx bridge may not expose it in after-hooks."""
        def __init__(self, plugin, guard):
            super().__init__()
            self.plugin = plugin
            self.guard = guard

        def before_hooked_method(self, param):
            try:
                if getattr(self.guard, "_reentr", False):
                    return
                if param.args and len(param.args) >= 2:
                    txt = str(param.args[1] or "")
                    if self.guard._is_bad(txt):
                        self.guard.note_bad()
                        try: param.args[1] = ""
                        except Exception: pass
            except Exception:
                pass

        def after_hooked_method(self, param):
            try:
                if getattr(self.guard, "_reentr", False):
                    return
                txt = ""
                try:
                    if param.args and len(param.args) >= 2:
                        txt = str(param.args[1] or "")
                except Exception:
                    txt = ""
                self.guard._log_once("[gift-toast] makeText: ", txt)
                if not self.guard._is_bad(txt):
                    return
                self.guard.note_bad()
                # Remember which context the bad toast was built on; the show()
                # guard will drop the NEXT toast shown on this context within 5s.
                try:
                    self.guard._pending = str(param.args[0]) if param.args else None
                except Exception:
                    self.guard._pending = None
                try:
                    d = self.guard.make_dummy(param)
                    if d is not None:
                        self.guard.mark(d)
                        try:
                            param.setResult(d)
                            self.guard._log_once("[gift-toast] makeText swapped: ", txt)
                        except Exception:
                            # setResult unavailable in after-hooks: text is already
                            # emptied by the before-hook, so the real Toast shows
                            # an empty bubble; the pending-context kill in show()
                            # removes it anyway.
                            self.guard._log_once("[gift-toast] setResult n/a; killed by show-guard: ", txt)
                except Exception:
                    pass
            except Exception:
                pass

    class _CraftDiagHook(MethodHook):
        """Passive observer of Main$Companion.craftGifts — logs the result string
        (the core reports its own failure reason there) without touching anything."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def after_hooked_method(self, param):
            try:
                res = None
                try: res = param.result
                except Exception: pass
                if res is None:
                    try:
                        _g = getattr(param, "getResult", None)
                        if _g: res = _g()
                    except Exception: pass
                _diag("[craft-diag] craftGifts -> " + str(res)[:220])
            except Exception as e:
                try: _diag("[craft-diag] err: " + repr(e))
                except Exception: pass

    class _CatUpdateHook(MethodHook):
        """Block the native server-driven list refresh for our hijacked fragment."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                ctrl = getattr(self.plugin, "_cat_ctrl", None)
                if ctrl and ctrl.fragment and ctrl.fragment.equals(param.thisObject):
                    param.setResult(None)
            except Exception:
                pass

        def after_hooked_method(self, param):
            try:
                ctrl = getattr(self.plugin, "_cat_ctrl", None)
                if ctrl and ctrl.fragment and ctrl.fragment.equals(param.thisObject):
                    return
            except Exception:
                pass

    class _CatFillHook(MethodHook):
        """Replace the adapter's item list with our catalog gift cells."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                ctrl = getattr(self.plugin, "_cat_ctrl", None)
                if ctrl and ctrl.fragment and ctrl.fragment.equals(param.thisObject):
                    param.setResult(None)
                    ctrl._fill(param.args[0], param.args[1])
            except Exception:
                pass

        def after_hooked_method(self, param):
            try:
                ctrl = getattr(self.plugin, "_cat_ctrl", None)
                if ctrl and ctrl.fragment and ctrl.fragment.equals(param.thisObject):
                    return
            except Exception:
                pass

    class _CatClickHook(MethodHook):
        """Route a cell tap to our constructor instead of the native resale flow."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                ctrl = getattr(self.plugin, "_cat_ctrl", None)
                if ctrl and ctrl.fragment and ctrl.fragment.equals(param.thisObject):
                    param.setResult(None)
                    item = param.args[0]
                    ctrl._click_item(item)
            except Exception:
                pass

    class _NoAnimSelectHook(MethodHook):
        """Kill the animated select/deselect of attribute cells in the gift
        constructor. Switching model used to fade the PREVIOUS model's selection
        ring out over ~280ms («обводка моргает … с задержкой») — forcing the
        `animated` arg of GiftAttributeCell.setSelected(boolean,boolean) to false
        makes the ring snap instantly with no flicker."""
        def __init__(self):
            super().__init__()

        def before_hooked_method(self, param):
            try:
                args = param.args
                if args is not None and len(args) >= 2:
                    args[1] = False
            except Exception:
                pass

    class _CtorManualHook(MethodHook):
        """Record real attribute-cell taps; random preview values do not unlock batching."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                sheet = getattr(param, "thisObject", None)
                if getattr(self.plugin, "_nat_sheet", None) is not sheet:
                    return
                tabs = _gv(sheet, "tabsSelectorView", None)
                selected_tab = int(tabs.getSelectedTab()) if tabs is not None else -1
                if selected_tab == 0:
                    self.plugin._ctor_manual_model = True
                elif selected_tab == 1:
                    self.plugin._ctor_manual_backdrop = True
            except Exception:
                pass

    class _DoUpgradeHook(MethodHook):
        """Intercept StarGiftSheet.doUpgrade() for OUR upgradable gift: block the real
        network upgrade and play TG's native reveal with a random local NFT instead.
        The preview/roll state is already set up by the native openUpgrade() that ran
        when the user tapped «Улучшить», so the roller animation plays for real."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                if self.plugin._on_do_upgrade(getattr(param, "thisObject", None)):
                    param.setResult(None)   # consume → no real RPC / star charge
            except Exception as e:
                # surface a swallowed error → otherwise the native RPC fires and we never know why
                try: self.plugin._toast("upg hook EXC: " + repr(e)[:120])
                except Exception: pass

    class _CraftGateHook(MethodHook):
        """Expose Telegram's own forge shortcut for our locally owned NFT gifts."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def after_hooked_method(self, param):
            try:
                sheet = getattr(param, "thisObject", None)
                entry = self.plugin._match_craft_entry(sheet)
                if entry is not None and self.plugin._craft_entry_eligible(entry, sheet, resolve=True):
                    param.setResult(True)
            except Exception:
                pass

    class _OpenCraftHook(MethodHook):
        """Route the native forge button to local crafting instead of Telegram RPC."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                sheet = getattr(param, "thisObject", None)
                entry = self.plugin._match_craft_entry(sheet)
                if entry is None:
                    return
                if not self.plugin._craft_entry_eligible(entry, sheet, resolve=True):
                    param.setResult(None)
                    self.plugin._toast("Этот подарок сейчас нельзя использовать для крафта")
                    return
                param.setResult(None)
                plugin = self.plugin
                run_on_ui_thread(lambda: plugin._open_local_crafting(entry, sheet))
            except Exception as e:
                try: self.plugin.log("[craft] native click: " + _cause(e))
                except Exception: pass

    class _CraftSetHook(MethodHook):
        """Make the existing TopView.craftView visible immediately after set()."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def after_hooked_method(self, param):
            try:
                sheet = getattr(param, "thisObject", None)
                self.plugin._show_native_craft_button(sheet)
                # StarGiftSheet performs deferred page/layout updates after set().
                # Some builds hide craftView again there, so re-assert visibility
                # after the sheet has settled (eligibility is cached by base id).
                plugin = self.plugin
                if run_on_ui_thread is not None:
                    run_on_ui_thread(lambda: plugin._show_native_craft_button(sheet), 120)
                    run_on_ui_thread(lambda: plugin._show_native_craft_button(sheet), 420)
            except Exception:
                pass

    class _SettingsHeaderHook(MethodHook):
        """Inject the PackIt-style OpenChimeraNFT hero and ElyxCore footer."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            # fillItems reads every Switch row straight out of the host's preferences. Align them
            # with the core here and a screen re-entered after a change made anywhere else (a
            # gift's «Носить», a restored backup, another account) can no longer show a stale
            # toggle — including the very first time, before anything has been flipped by hand.
            try:
                activity = getattr(param, "thisObject", None)
                if activity is not None and self.plugin._is_our_settings(activity):
                    self.plugin._sync_settings_switches()
            except Exception:
                pass

        def after_hooked_method(self, param):
            try:
                activity = getattr(param, "thisObject", None)
                args = getattr(param, "args", None)
                items = args[0] if args and len(args) > 0 else None
                if activity is not None and items is not None:
                    self.plugin._inject_settings_header(activity, items)
            except Exception:
                pass

    class _ProfileOpenHook(MethodHook):
        """Tapping a .profile document in a chat → run OUR import sheet instead of the
        native file viewer (port of the regular plugin's ProfileConfigOpenHook)."""
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def before_hooked_method(self, param):
            try:
                args = list(getattr(param, "args", None) or [])
                if not self.plugin._handle_profile_open_args(args):
                    return
                try:
                    mname = str(param.method.getName() or "")
                except Exception:
                    mname = ""
                try:
                    param.setResult(True if mname == "openForView" else None)
                except Exception:
                    pass
            except Exception as e:
                try: self.plugin.log("[profile] open dispatch: " + _cause(e))
                except Exception: pass

    class _ProfileCopyMenuHook(MethodHook):
        """Add the copy action to ProfileActivity's real first-level popup.

        The production runtime is intentionally loaded without on_plugin_load,
        therefore its PROFILE_ACTION_MENU hook never runs in an Elyx build.
        This bootstrap hook is the authoritative menu integration.
        """
        def __init__(self, plugin):
            super().__init__()
            self.plugin = plugin

        def after_hooked_method(self, param):
            try:
                self.plugin._inject_profile_copy_menu_item(getattr(param, "thisObject", None))
            except Exception as e:
                try: self.plugin.log("[copy-menu] inject: " + _cause(e))
                except Exception: pass

    _ProfileCopyClickListener = None
    if dynamic_proxy is not None and View is not None:
        class _ProfileCopyClickListener(dynamic_proxy(View.OnClickListener)):
            """Precompiled proxy class; instances are cached by user id.

            Defining a fresh dynamic_proxy class inside every profile-menu
            build stalls the UI thread on Chaquopy/Elyx.
            """
            def __init__(self, plugin, uid, activity, menu):
                super().__init__()
                self.plugin = plugin
                self.bind(uid, activity, menu)

            def bind(self, uid, activity, menu):
                self.uid = int(uid or 0)
                self.activity = activity
                self.menu = menu

            def onClick(self, view):
                try:
                    self.plugin._tap_feedback(view)
                except Exception:
                    pass
                try:
                    self.menu.toggleSubMenu()
                except Exception:
                    pass
                self.plugin._open_profile_copy_picker(self.uid, self.activity)
else:
    _CatUpdateHook = _CatFillHook = _CatClickHook = _NoAnimSelectHook = _CtorManualHook = _DoUpgradeHook = None
    _CraftGateHook = _OpenCraftHook = _CraftSetHook = None
    _SettingsHeaderHook = None
    _ProfileOpenHook = None
    _ProfileCopyMenuHook = _ProfileCopyClickListener = None


class _NativeCatalog:
    """Hijacks the native ResaleGiftsFragment to render the 114-gift NFT catalog
    with real Telegram gift cells. Tapping a gift opens the native constructor."""
    def __init__(self, plugin, nft_only=True):
        self.plugin = plugin
        self.nft_only = bool(nft_only)
        self.fragment = None
        self.adapter = None
        self.items = []
        self._retry = 0
        self.qty = 1            # regular-gifts catalog: how many copies a tap adds
        self._qty_pill = None

    def _load_items(self):
        return self.plugin._catalog_items(self.nft_only)

    def show(self):
        plugin = self.plugin
        uid = _real_uid()
        Frag = jclass("org.telegram.ui.Gifts.ResaleGiftsFragment")
        title = "Каталог NFT" if self.nft_only else "Каталог подарков"
        attempts = [
            lambda: Frag(uid, title, 0, None),
            lambda: Frag(int(uid), title, 0, None),
            lambda: Frag(uid, title, None),
            lambda: Frag(uid, title),
            lambda: Frag(uid),
            lambda: Frag(),
        ]
        last = None
        matched = -1
        for i, f in enumerate(attempts):
            try:
                fr = f()
                if fr is not None:
                    self.fragment = fr
                    matched = i
                    break
            except Exception as e:
                last = e
        if self.fragment is None:
            raise last or Exception("ResaleGiftsFragment ctor unavailable")
        try:
            plugin.log("[cat] fragment ctor variant=%d uid=%s" % (matched, uid))
        except Exception:
            pass
        plugin._cat_ctrl = self
        get_last_fragment().presentFragment(self.fragment)
        run_on_ui_thread(self._init, 150)

    def _init(self):
        try:
            lv = _gv(self.fragment, "listView")
            ev = _gv(self.fragment, "emptyView")
            if ev is not None:
                try:
                    ev.setVisibility(8)
                    ev.setAlpha(0.0)
                except Exception:
                    pass
            self.adapter = _gv(lv, "adapter") if lv is not None else None
            self.items = self._load_items()
            try:
                self.plugin.log("[cat] init: listView=%s adapter=%s items=%d nft=%s" % (
                    lv is not None, self.adapter is not None, len(self.items or []), self.nft_only))
            except Exception:
                pass
            self._refresh()
            if not self.nft_only:
                self._inject_qty_pill()
            if not self.items:
                self.plugin._toast("загружаю каталог…")
                try:
                    c = self.plugin._stars_ctrl()
                    if c is not None:
                        c.loadStarGifts()
                except Exception:
                    pass
                run_on_ui_thread(self._retry_load, 1000)
        except Exception as e:
            try:
                self.plugin.log("[cat] init: " + _cause(e))
            except Exception:
                pass

    def _retry_load(self):
        if self.fragment is None:
            return
        if not self.items:
            self.items = self._load_items()
            self._refresh()
            if not self.items:
                self._retry += 1
                if self._retry < 8:
                    run_on_ui_thread(self._retry_load, 1000)
                else:
                    self.plugin._toast("каталог пуст")

    def _refresh(self):
        try:
            sub = len(self.items or [])
            unit = "NFT" if self.nft_only else "подарков"
            ab = _gv(self.fragment, "actionBar")
            if ab is not None:
                try:
                    ab.setSubtitle(("%d %s" % (sub, unit)) if sub else "Пусто")
                except Exception:
                    pass
            if self.adapter is not None:
                self.adapter.update(True)
                lv = _gv(self.fragment, "listView")
                if lv is not None:
                    try:
                        lv.scrollToPosition(0)
                    except Exception:
                        pass
        except Exception:
            pass

    def _make_cell(self, Factory, g):
        """asStarGift signature drifts between TG builds — try known arities."""
        variants = (
            lambda: Factory.asStarGift(0, g, False, False, False, False, False),
            lambda: Factory.asStarGift(0, g, False, False, False, False),
            lambda: Factory.asStarGift(0, g, False, False, False),
            lambda: Factory.asStarGift(0, g, False, False),
            lambda: Factory.asStarGift(0, g, False),
            lambda: Factory.asStarGift(0, g),
        )
        for i, v in enumerate(variants):
            try:
                it = v()
                if it is not None:
                    if getattr(self, "_cell_variant", -1) != i:
                        self._cell_variant = i
                        try:
                            self.plugin.log("[cat] asStarGift variant=%d argc=%d" % (i, 7 - i))
                        except Exception:
                            pass
                    return it
            except Exception:
                continue
        return None

    def _fill(self, items, adapter):
        try:
            Factory = jclass("org.telegram.ui.Gifts.GiftSheet$GiftCell$Factory")
        except Exception as e:
            Factory = None
            try:
                self.plugin.log("[cat] no GiftCell.Factory: " + _cause(e))
            except Exception:
                pass
        added = 0
        for g in list(self.items or []):
            if self.nft_only:
                try:
                    self.plugin._unsell(g)   # drop the «продан» ribbon on NFT cells
                except Exception:
                    pass
            it = self._make_cell(Factory, g) if Factory is not None else None
            if it is not None:
                try:
                    it.object = g
                except Exception:
                    pass
                items.add(it)
                added += 1
        try:
            self.plugin.log("[cat] fill: items=%d cells=%d" % (len(self.items or []), added))
        except Exception:
            pass
        if added == 0 and UItem is not None:
            try:
                items.add(UItem.asShadow("Каталог недоступен"))
            except Exception:
                pass

    def _qty_label(self):
        try:
            return str(int(self.qty or 1)) + "×"
        except Exception:
            return "1×"

    def _inject_qty_pill(self):
        """Floating «N×» pill (regular-gifts catalog only): choose how many identical
        copies a gift tap adds. Default 1×; tap → numpad → any number."""
        if self.nft_only or PopupWindow is None or TextView is None:
            return
        if self._qty_pill is not None:
            return
        try:
            root = _gv(self.fragment, "fragmentView")
            if root is None:
                try:
                    root = self.fragment.getFragmentView()
                except Exception:
                    root = None
            if root is None:
                self.plugin.log("[cat] qty pill: no fragmentView")
                return
            ctx = root.getContext()
            pill = self.plugin._qty_pill_view(ctx, self._qty_label())
            self._qty_pill = pill
            pill.setOnClickListener(self.plugin._click(lambda v: self._open_qty_pad()))
            lp = FrameLayout.LayoutParams(-2, -2, Gravity.BOTTOM | Gravity.RIGHT)
            lp.rightMargin = AndroidUtilities.dp(16)
            lp.bottomMargin = AndroidUtilities.dp(24)
            root.addView(pill, lp)
            self.plugin.log("[cat] qty pill injected")
        except Exception as e:
            try:
                self.plugin.log("[cat] qty pill: " + _cause(e))
            except Exception:
                pass

    def _open_qty_pad(self):
        ctrl = self

        def _submit(text):
            try:
                n = int(str(text or "1").strip() or "1")
            except Exception:
                n = 1
            ctrl.qty = max(1, min(n, 99))
            try:
                if ctrl._qty_pill is not None:
                    ctrl._qty_pill.setText(ctrl._qty_label())
            except Exception:
                pass
        self.plugin._input("Сколько одинаковых подарков добавить? (1–99)",
                           str(int(self.qty or 1)), _submit, numeric=True)

    def _click_item(self, uitem):
        try:
            gift = None
            try:
                gift = getattr(uitem, "object", None)
            except Exception:
                gift = None
            if gift is None:
                gift = _gv(uitem, "object")
            if gift is None:
                return
            gid = 0
            try:
                gid = int(_gv(gift, "id", 0) or 0)
            except Exception:
                gid = 0
            try:
                self.plugin.log("[cat] click gid=%d" % gid)
            except Exception:
                pass
            if gid <= 0:
                self.plugin._toast("не удалось определить gift_id")
                return
            title = ""
            try:
                title = str(_gv(gift, "title", "") or "")
            except Exception:
                title = ""
            base = gift
            if not self.nft_only:
                # regular gift → add `qty` identical copies to the library (no constructor)
                self.plugin._add_regular_gifts(base, title, self.qty)
                try:
                    self.fragment.finishFragment()
                except Exception:
                    pass
                self.plugin._cat_ctrl = None
                return
            try:
                self.fragment.finishFragment()
            except Exception:
                pass
            self.plugin._cat_ctrl = None
            run_on_ui_thread(lambda: self.plugin._catalog_pick(gid, base, title), 120)
        except Exception as e:
            try:
                self.plugin.log("[cat] click: " + _cause(e))
            except Exception:
                pass


def _resolve_data_dir():
    if get_plugins_dir is None:
        return ""
    base = get_plugins_dir()
    import os
    # NOT renamed with the rest of the plugin: this directory holds every user's gifts
    # and Store, and a new name would read as "all my data is gone".
    new_dir = os.path.join(base, "eblannft_data")
    return new_dir


_DIAG_LOCK = None


def _diag(msg):
    """Append a timestamped line to <data>/diag.log — on-device save diagnostics."""
    global _DIAG_LOCK
    try:
        import threading as _th
        if _DIAG_LOCK is None:
            _DIAG_LOCK = _th.Lock()
        import datetime as _dt
        line = _dt.datetime.now().strftime("%m-%d %H:%M:%S") + " " + str(msg) + "\n"
        with _DIAG_LOCK:
            with open(os.path.join(_resolve_data_dir(), "diag.log"), "a", encoding="utf-8") as _fh:
                _fh.write(line)
    except Exception:
        pass


def _runtime_dir_candidates():
    """{plugins}/<plugin id> — where the lazily extracted Python runtime is unpacked,
    named after the host plugin id. Newest first, then the pre-rename names: an install
    that predates the rename already has one of those, and a build under the OLD plugin
    id may still be installed alongside this one (a new id means the host treats them as
    two plugins), so its directory is read but never written or removed behind its back.
    """
    if get_plugins_dir is None:
        return []
    import os
    base = get_plugins_dir()
    return [os.path.join(base, name) for name in (_HOST_PLUGIN_ID,) + _LEGACY_HOST_PLUGIN_IDS]


def _extract_runtime(root):
    raw = None
    try:
        helper = _packaged_helper("payload_helper")
        if helper is not None:
            raw = helper.load_payload(_PAYLOAD_SHA256, _PAYLOAD_B64)
    except Exception:
        raw = None
    # Compatibility with pre-1.4.63 archives that exposed the payload as an Elyx asset.
    if _elyx_assets is not None:
        if raw is None:
            try:
                raw = _elyx_assets.runtime_payload.content_bytes()
            except Exception:
                raw = None
    if raw is None:
        raw = base64.b64decode(_PAYLOAD_B64)
    if _hashlib.sha256(raw).hexdigest() != _PAYLOAD_SHA256:
        raise RuntimeError("runtime payload hash mismatch")
    os.makedirs(root, exist_ok=True)
    with _zipfile.ZipFile(_io.BytesIO(raw), "r") as zf:
        for info in zf.infolist():
            name = str(info.filename or "").replace("\\", "/")
            if not name.startswith(_RT_PKG + "/") or name.endswith("/"):
                continue
            dest = os.path.abspath(os.path.join(root, name.replace("/", os.sep)))
            with zf.open(info, "r") as src:
                data = src.read()
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest, "wb") as out:
                out.write(data)


def _import_runtime(root):
    pkg_dir = os.path.join(root, _RT_PKG)
    init_py = os.path.join(pkg_dir, "__init__.py")
    plugin_py = os.path.join(pkg_dir, "plugin.py")
    spec = _ilu.spec_from_file_location(_RT_ALIAS, init_py, submodule_search_locations=[pkg_dir])
    pkg_mod = _ilu.module_from_spec(spec)
    _sys.modules[_RT_ALIAS] = pkg_mod
    spec.loader.exec_module(pkg_mod)
    mspec = _ilu.spec_from_file_location(_RT_ALIAS + ".plugin", plugin_py)
    pmod = _ilu.module_from_spec(mspec)
    _sys.modules[_RT_ALIAS + ".plugin"] = pmod
    mspec.loader.exec_module(pmod)
    for attr in ("NftClonerPlugin", "EblanNftPlugin"):
        cls = getattr(pmod, attr, None)
        if isinstance(cls, type):
            return cls, pmod
    raise ImportError("runtime plugin class not found")


class Plugin(BasePlugin):
    # ---------------- lifecycle ----------------
    def on_plugin_load(self):
        # [diag] mirror every framework log line into <data>/diag.log
        try:
            _base_log = self.log

            def _file_log(msg, _bl=_base_log):
                try:
                    _diag(msg)
                except Exception:
                    pass
                _bl(msg)

            self.log = _file_log
        except Exception:
            pass
        try:
            _diag("=== on_plugin_load v" + __version__)
        except Exception:
            pass

        # [gift-toast] install the bulletin guard: Telegram's own gift-send failure
        # bulletin («Подарок не доставлен получателю …») is meaningless here — the
        # visual delivery is local and already done. Hook EVERY show* entry point
        # (show / show(boolean) / showAsNotification / showPopSafe …): newer clients
        # push the bulletin as a REAL Android notification via showAsNotification(),
        # which is why a 0-arg show() hook alone never fired.
        try:
            if MethodHook is not None:
                _Bul = JavaClass.forName("org.telegram.ui.Components.Bulletin")
                _guard = _GiftToastGuard(self)
                _hooked = 0
                for _m in _Bul.getDeclaredMethods():
                    try:
                        if _m.getName().startswith("show"):
                            try: _m.setAccessible(True)
                            except Exception: pass
                            self.hook_method(_m, _guard)
                            _hooked += 1
                    except Exception:
                        continue
                self._bulletin_guard_ref = _guard
                _diag("[gift-toast] bulletin guard installed: " + str(_hooked) + " show* methods")
        except Exception as guard_error:
            try: _diag("[gift-toast] install err: " + _cause(guard_error))
            except Exception: pass
        # [gift-toast] layer 2: catch the banner if it still lands as a real Android
        # notification (posted by Telegram through NotificationManager.notify).
        try:
            if MethodHook is not None:
                _NM = JavaClass.forName("android.app.NotificationManager")
                _guard2 = _GiftNotifGuard(self)
                _hooked2 = 0
                for _m in _NM.getDeclaredMethods():
                    try:
                        if _m.getName() == "notify":
                            try: _m.setAccessible(True)
                            except Exception: pass
                            self.hook_method(_m, _guard2)
                            _hooked2 += 1
                    except Exception:
                        continue
                self._notif_guard_ref = _guard2
                _diag("[gift-toast] notification guard installed: " + str(_hooked2) + " notify() overloads")
        except Exception as guard_error2:
            try: _diag("[gift-toast] notify install err: " + _cause(guard_error2))
            except Exception: pass
        # [gift-toast] layer 3 (THE fix): the core's own purchase-failure toast.
        # GiftHook.showPurchaseMessage posts android.widget.Toast.makeText(...).show()
        # with «Подарок не доставлен получателю — нет связи с сервером» — that is the
        # bottom banner the user sees. Hook Toast.show() and drop it by text.
        try:
            if MethodHook is not None:
                _Toast = JavaClass.forName("android.widget.Toast")
                _guard3 = _GiftToastToastGuard(self)
                _hooked3 = 0
                for _m in _Toast.getDeclaredMethods():
                    try:
                        if _m.getName() == "show" and len(_m.getParameterTypes()) == 0:
                            try: _m.setAccessible(True)
                            except Exception: pass
                            self.hook_method(_m, _guard3)
                            _hooked3 += 1
                    except Exception:
                        continue
                self._toast_guard_ref = _guard3
                _diag("[gift-toast] toast guard installed: " + str(_hooked3) + " show()")
                _hooked4 = 0
                for _m in _Toast.getDeclaredMethods():
                    try:
                        if _m.getName() == "makeText":
                            try: _m.setAccessible(True)
                            except Exception: pass
                            self.hook_method(_m, _ToastMakeTextHook(self, _guard3))
                            _hooked4 += 1
                    except Exception:
                        continue
                _diag("[gift-toast] toast makeText hooks: " + str(_hooked4))
        except Exception as guard_error3:
            try: _diag("[gift-toast] toast install err: " + _cause(guard_error3))
            except Exception: pass
        # [craft-diag] passive observation of the core's craft result — the core
        # reports its own failure reason in the returned string. No modification.
        try:
            if MethodHook is not None:
                _MainC = JavaClass.forName("com.chimeranft.core.Main$Companion")
                for _m in _MainC.getDeclaredMethods():
                    try:
                        if _m.getName() == "craftGifts":
                            try: _m.setAccessible(True)
                            except Exception: pass
                            self.hook_method(_m, _CraftDiagHook(self))
                            _diag("[craft-diag] hook installed on Companion.craftGifts")
                            break
                    except Exception:
                        continue
        except Exception as craft_e:
            try: _diag("[craft-diag] install err: " + _cause(craft_e))
            except Exception: pass

        # Load the compiled core class loader up front: the access-gate DECISION lives in the DEX
        # (com.chimeranft.core.Gate), so it has to be bound before the gate runs. Main reuses this
        # same loader below — the DEX is decoded once. This is only classloading; nothing in the
        # plugin actually runs until Main.init() is invoked further down.
        self._dex_loader = None
        self._core_src = ""
        try:
            try:
                iv = self._installed_version()
                if iv:
                    __version__ = iv
            except Exception:
                pass
            dex, self._core_src = self._load_core_dex()
            buf = ByteBuffer.wrap(dex)
            parent = ApplicationLoader.applicationContext.getClassLoader()
            self._dex_loader = InMemoryDexClassLoader(buf, parent)
            _STR_CLS = JavaClass.forName("java.lang.String")
            _INT_T = JInteger.TYPE
            _LONG_T = JLong.TYPE
            _bind_gate(self._dex_loader.loadClass("com.chimeranft.core.Gate"))
        except Exception as core_error:
            _bind_gate(None)
            self.log("OpenChimeraNFT core preload failed: " + _cause(core_error))

        # Local decision only — see _check_plugin_access(network=False). The network revalidation
        # is started from _start_deferred_access_check() once the core is up.
        # [noban] purge stale ban markers so old denies can never resurface
        try:
            for _nm in ("plugin_access.json", "plugin_access.json.core.bak", "plugin_access.json.core.tmp"):
                try: os.remove(os.path.join(_resolve_data_dir(), _nm))
                except OSError: pass
        except Exception:
            pass
        access = _check_plugin_access(network=False)
        if access.get("allowed") is False:
            self._access_denied = True
            self._unloaded = True
            self.log("OpenChimeraNFT access denied for uid=" + str(_real_uid()))
            # Restarting the app used to be a way around the gate: the plugin stayed in
            # the list (dead, but installed) because the uninstall only ran from the
            # button. If the gate was already shown once, uninstall on THIS launch
            # WITHOUT waiting for a tap. No kill here — the files + registry entry go,
            # and the sheet still explains why.
            if access.get("gate_shown"):
                self._access_auto_deleted = True  # sheet text reflects the removal
                import threading as _threading
                # Show the sheet first; run the (possibly self-unloading) uninstall a beat
                # later so the popup is already on screen and can't be raced away.
                def _auto_uninstall():
                    try:
                        removed = self._access_delete_plugin(kill=False, silent=True)
                        self.log("OpenChimeraNFT auto-uninstalled on restart, paths=" + str(removed))
                    except Exception as auto_error:
                        try: self.log("[access] auto uninstall: " + _cause(auto_error))
                        except Exception: pass
                _t = _threading.Timer(0.6, _auto_uninstall)
                _t.daemon = True
                _t.start()
            self._show_access_denied(access, 0)
            return
        # Diagnostic: the compiled gate could not be bound and the check therefore failed open.
        # Surface WHY, once, so a broken core load is visible (see _GATE_ERR).
        if access.get("gate_unavailable"):
            reason = str(access.get("gate_error") or "unknown")
            self.log("OpenChimeraNFT access gate unavailable -> " + reason)
            try:
                import os as _os
                with open(_os.path.join(_resolve_data_dir(), "gate_diag.txt"), "w",
                          encoding="utf-8") as _fh:
                    _fh.write(reason + "\n")
            except Exception:
                pass
            try:
                run_on_ui_thread(lambda: self._toast("gate: " + reason), 1500)
            except Exception:
                pass
        self._clazz = None
        try:
            # Reuse the class loader built for the gate above; only rebuild it if the preload
            # failed (in which case the gate failed open and we still try to bring the core up).
            if self._dex_loader is None:
                dex, self._core_src = self._load_core_dex()
                buf = ByteBuffer.wrap(dex)
                parent = ApplicationLoader.applicationContext.getClassLoader()
                self._dex_loader = InMemoryDexClassLoader(buf, parent)
                _STR_CLS = JavaClass.forName("java.lang.String")
                _INT_T = JInteger.TYPE
                _LONG_T = JLong.TYPE
            src = self._core_src
            self._clazz = self._dex_loader.loadClass(_CLASS_NAME)
            self._install_access_denied_callback()
            # The live gate is wired now, so the network half of the access check is safe to run.
            self._start_deferred_access_check()
            try:
                pass  # [noban] username never handed to the ban machinery
            except Exception as access_username_error:
                self.log("[access] username bridge: " + _cause(access_username_error))

            # Elyx archives ship ABI-specific C++ helpers as real assets. Load the matching
            # library through native_helper; unsupported devices keep the Java fallback.
            try:
                helper = _packaged_helper("native_helper")
                nm = self._clazz.getMethod("setNativeLibraryPath", _STR_CLS)
                if helper is not None:
                    native_path, native_result = helper.load_library(
                        "libchimeranft_fast.so",
                        lambda path: nm.invoke(None, path),
                    )
                    self.log("OpenChimeraNFT native[" + str(native_path) + "]: " + str(native_result))
                else:
                    native_path = self._native_fast_path()
                    if native_path:
                        self.log("OpenChimeraNFT native: " + str(nm.invoke(None, native_path)))
            except Exception as native_error:
                self.log("OpenChimeraNFT native fallback: " + _cause(native_error))

            try:
                gram_icon_path = self._gram_icon_path()
                if gram_icon_path:
                    gm = self._clazz.getMethod("setGramIconPath", _STR_CLS)
                    gm.invoke(None, gram_icon_path)
            except Exception as gram_icon_error:
                self.log("OpenChimeraNFT GRAM icon fallback: " + _cause(gram_icon_error))

            data_dir = _resolve_data_dir()
            m = self._clazz.getMethod("init", _STR_CLS, _STR_CLS, _STR_CLS)
            status = m.invoke(None, data_dir, str(_cache_uid()), str(_real_uid()))
            self.log("OpenChimeraNFT core[" + src + " v" + __version__ + "]: " + str(status))
            try:
                self._install_support_popup_bridge()
            except Exception as support_popup_error:
                self.log("[support-popup] bridge: " + _cause(support_popup_error))
            # Install the main Telegram-settings entry synchronously. SettingsActivity can be
            # opened immediately after startup; a delayed Timer made the row randomly miss its
            # first fillItems pass on some AyuGram/exteraGram builds.
            try:
                self._install_main_settings_button()
            except Exception as settings_error:
                self.log("[main-settings] early install: " + _cause(settings_error))
            # The PackIt-style hero/footer must be hooked before the user can
            # open PluginSettingsActivity. Installing this only from the
            # deferred pass made the first render randomly miss both custom rows.
            try:
                self._install_settings_header_hook()
            except Exception as header_error:
                self.log("[hdr] early install: " + _cause(header_error))
            try:
                self._install_profile_copy_menu_hook()
            except Exception as copy_menu_error:
                self.log("[copy-menu] early install: " + _cause(copy_menu_error))
            # A document may be tapped immediately after enabling the plugin.
            # Installing this only from the deferred timer made the first tap race
            # startup and silently fall through to Android's generic file viewer.
            try:
                self._install_profile_open_hook()
            except Exception as profile_open_error:
                self.log("[profile] early open hook: " + _cause(profile_open_error))
        except Exception as e:
            self.log("OpenChimeraNFT load error: " + _cause(e))
            try:
                run_on_ui_thread(lambda: self._toast("OpenChimeraNFT: ядро не загрузилось — " + _cause(e)))
            except Exception:
                pass
        # auto-update: start the periodic background poll → the popup can appear ANYWHERE
        # in the client (not only on the settings screen), and re-offers if dismissed.
        try:
            self._start_update_loop()
        except Exception:
            pass
        # The hook installs are pure reflection (Class.forName + getDeclaredMethods over
        # StarGiftSheet / PluginSettingsActivity / AndroidUtilities — hundreds of Method
        # objects each) and all guard COLD screens nobody can reach within the first
        # second of a cold start — so run them off the load path entirely.
        self._unloaded = False
        # Install the doUpgrade hook SYNCHRONOUSLY here (like the known-good v1.1.2) — the deferred
        # timer below apparently didn't fire on some builds, so the fake-upgrade interception was
        # never installed and «Улучшить» hit the real server (STARGIFT_ALREADY_CONVERTED). Idempotent
        # (_gs_hooks_done), so the deferred pass becomes a no-op.
        try:
            self._install_gift_sheet_hooks()
        except Exception:
            pass
        try:
            import threading
            t = threading.Timer(0.8, self._install_deferred_hooks)
            t.daemon = True
            t.start()
        except Exception:
            self._install_deferred_hooks()

        # Prime the compact upgrade lookup away from the UI thread. The first tap on
        # «Улучшить» no longer bridges and parses the complete gift library.
        try:
            import threading
            t = threading.Timer(1.5, self._prewarm_gift_snapshot)
            t.daemon = True
            t.start()
        except Exception:
            pass
        # PackIt-style channel sheet: a new plugin version offers the developer
        # channel once after the foreground UI becomes available. Opening our
        # settings is the reliable fallback if Telegram had no fragment yet.
        try:
            self._schedule_developer_channel_prompt_after_update()
            self._schedule_update_notice_after_load()
        except Exception:
            pass

    def _install_access_denied_callback(self):
        return  # [noban] DEX can never register a ban callback
        if self._clazz is None or dynamic_proxy is None or jclass is None:
            return
        Runnable = jclass("java.lang.Runnable")
        plugin = self

        class _AccessDeniedCallback(dynamic_proxy(Runnable)):
            def run(self):
                try:
                    plugin._handle_live_access_denied()
                except Exception as error:
                    try: plugin.log("[access] callback: " + _cause(error))
                    except Exception: pass

        callback = _AccessDeniedCallback()
        self._access_denied_callback = callback
        method = self._clazz.getMethod("setAccessDeniedCallback", Runnable)
        self.log("[access] " + str(method.invoke(None, callback)))

    def _start_deferred_access_check(self):
        return  # [noban]
        """Run the access revalidation that on_plugin_load no longer does inline.

        Deliberately has NO teardown of its own: on a deny it only persists the enriched decision
        (so the marker survives a restart and works offline) and reports the client's accounts for
        blacklisting. Tearing the plugin down stays the sole job of SyncClient.accessLoop →
        onAccessDenied → setAccessDeniedCallback → _handle_live_access_denied, so there is exactly
        one gate path rather than two racing ones."""
        try:
            import threading as _threading

            def _work():
                try:
                    decision = _check_plugin_access(network=True)
                    if decision.get("allowed") is False:
                        self.log("[access] deferred check: denied (live gate will follow)")
                except Exception as error:
                    try: self.log("[access] deferred check: " + _cause(error))
                    except Exception: pass

            worker = _threading.Thread(target=_work, name="chimeranft-access-revalidate")
            worker.daemon = True
            worker.start()
        except Exception as error:
            try: self.log("[access] deferred check spawn: " + _cause(error))
            except Exception: pass

    def _handle_live_access_denied(self):
        return  # [noban] live ban handler removed
        self._access_denied = True
        self._unloaded = True
        self._upd_stop = True
        decision = {"allowed": False}
        try:
            raw = self._clazz.getMethod("getAccessDeniedDecision").invoke(None)
            parsed = json.loads(str(raw or "{}"))
            if isinstance(parsed, dict):
                decision.update(parsed)
        except Exception as error:
            self.log("[access] decision: " + _cause(error))
        # Merge, do not replace: `gate_shown` is what turns the NEXT launch into an automatic
        # uninstall, and a live decision does not carry it.
        stored = _load_access_cache()
        stored.update(decision)
        stored["allowed"] = False
        stored["checked_at"] = int(__import__("time").time())
        _save_access_cache(stored)
        self._disable_python_features()
        self._show_access_denied(decision, 0)
        # Start the re-presenter HERE, not only after the sheet has been shown once. If the ban
        # arrives while the app is backgrounded, _show_access_denied never finds an Activity and
        # gives up after its retry budget; starting the watchdog on the DECISION instead of on a
        # successful show is what makes the gate survive that and appear when the user comes back.
        self._start_access_denied_watchdog()

    def _disable_python_features(self):
        """Unhook every Python cold-path feature; Java hot-path hooks are already shut down."""
        fields = (
            "_profile_open_refs", "_profile_copy_menu_refs", "_hdr_hook_refs",
            "_main_settings_hook_refs", "_gs_hook_refs", "_cat_hook_refs",
            "_ctor_hook_refs", "_account_switch_refs",
        )
        for field in fields:
            refs = getattr(self, field, None) or []
            for ref in list(refs):
                try: ref.unhook()
                except Exception:
                    try: self.unhook_method(ref)
                    except Exception: pass
            try: setattr(self, field, [])
            except Exception: pass
        try:
            ref = getattr(self, "_native_help_hook_ref", None)
            if ref is not None: ref.unhook()
        except Exception:
            pass
        prod = getattr(self, "_prod", None)
        if prod is not None:
            try: prod.on_plugin_unload()
            except Exception: pass
        self._prod = None
        # Close any feature surface that was already open when the server decision
        # arrived. The access sheet below becomes the only remaining plugin UI.
        for field in (
            "_catalog_sheet", "_craft_sheet", "_ctor_sheet", "_gifts_sheet",
            # NOTE: every name here must be a FIELD that holds a sheet. "_profile_section_sheet"
            # used to be in this list and it was a METHOD — the loop set the instance attribute
            # to None, so after one access-denied unload the section picker was gone.
            "_help_sheet", "_native_help_sheet", "_backup_picker_sheet",
            "_backup_manager_sheet", "_changelog_sheet",
            "_support_popup_sheet", "_nat_sheet", "_seed_sheet",
            "_developer_channel_sheet",
        ):
            sheet = getattr(self, field, None)
            if sheet is not None:
                try: sheet.dismiss()
                except Exception: pass
            try: setattr(self, field, None)
            except Exception: pass

    def _access_denied_asset_path(self):
        if _elyx_assets is not None:
            try:
                path = str(_elyx_assets.access_denied.path_str)
                if path and os.path.exists(path):
                    return path
            except Exception:
                pass
        try:
            roots = (_resolve_data_dir(), get_plugins_dir() if get_plugins_dir else "")
            for root in roots:
                if not root:
                    continue
                for candidate in (
                    os.path.join(root, "access_denied.tgs"),
                    os.path.join(root, "res", "access_denied.tgs"),
                ):
                    if os.path.exists(candidate):
                        return candidate
        except Exception:
            pass
        return ""

    def _show_access_denied(self, decision, attempt=0):
        return  # [noban] ban sheet removed
        """Full-height native Telegram sheet; retries until a foreground Activity exists."""
        self._access_denied_decision = dict(decision or {})

        def _retry():
            import threading
            # Only ONE retry chain may run: the watchdog re-enters with attempt=0
            # whenever the sheet is gone, and without this guard every tick while
            # the app sits in the background would start another timer chain.
            if attempt == 0 and getattr(self, "_access_retry_active", False):
                return
            self._access_retry_active = True

            def _fire():
                self._access_retry_active = False
                self._show_access_denied(decision, attempt + 1)

            timer = threading.Timer(0.35 if attempt < 12 else 1.0, _fire)
            timer.daemon = True
            timer.start()

        def _show():
            try:
                old = getattr(self, "_access_denied_sheet", None)
                if old is not None:
                    try:
                        if old.isShowing():
                            return
                    except Exception:
                        pass
                fragment = get_last_fragment() if get_last_fragment is not None else None
                ctx = fragment.getParentActivity() if fragment is not None else None
                if ctx is None or BottomSheet is None or LinearLayout is None:
                    _retry()
                    return
                try: rp = fragment.getResourceProvider()
                except Exception: rp = None
                try: sheet = BottomSheet(ctx, False, rp)
                except Exception: sheet = BottomSheet(ctx, False)
                # PackIt-style hard gate: the sheet must be impossible to close.
                # Swipe, touch-outside, the system Back button and the internal
                # dismiss path are all shut down; the ONLY way out is the delete
                # button below (which wipes the plugin and kills the process).
                for method_name, args in (
                    ("setCanDismissWithSwipe", (False,)),
                    ("setCanDismissWithTouchOutside", (False,)),
                    ("setCanceledOnTouchOutside", (False,)),
                    ("setCancelable", (False,)),
                    ("setApplyTopPadding", (False,)),
                    ("setApplyBottomPadding", (False,)),
                    ("fixNavigationBar", ()),
                ):
                    try: getattr(sheet, method_name)(*args)
                    except Exception: pass
                try:
                    if fragment is not None:
                        sheet.makeAttached(fragment)
                except Exception: pass
                try:
                    class _NoDismissDelegate(dynamic_proxy(BottomSheet.BottomSheetDelegateInterface)):
                        def canDismiss(self2):
                            return False
                        def onOpenAnimationStart(self2):
                            pass
                        def onOpenAnimationEnd(self2):
                            pass
                    self._access_denied_delegate = _NoDismissDelegate()
                    sheet.setDelegate(self._access_denied_delegate)
                except Exception as delegate_error:
                    self.log("[access] delegate: " + _cause(delegate_error))

                # Compact PackIt-shaped card: rounded top corners, dialog background,
                # bold title, centered body, one filled action button. No hero, no
                # scroll container, no full-height stretch.
                root = LinearLayout(ctx)
                root.setOrientation(LinearLayout.VERTICAL)
                root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(20),
                                AndroidUtilities.dp(20), AndroidUtilities.dp(8))
                try:
                    card_bg = GradientDrawable()
                    card_bg.setShape(GradientDrawable.RECTANGLE)
                    card_bg.setCornerRadii([
                        float(AndroidUtilities.dp(20)), float(AndroidUtilities.dp(20)),
                        float(AndroidUtilities.dp(20)), float(AndroidUtilities.dp(20)),
                        0.0, 0.0, 0.0, 0.0,
                    ])
                    card_bg.setColor(Theme.getColor(Theme.key_dialogBackground))
                    root.setBackground(card_bg)
                except Exception:
                    try: root.setBackgroundColor(Theme.getColor(Theme.key_dialogBackground))
                    except Exception: pass

                # PackIt shows a single big custom emoji above the title on its gate; the same
                # document id, drawn by Telegram's own animated-emoji drawable.
                try:
                    emoji = self._custom_emoji_view(ctx, self.ACCESS_DENIED_EMOJI_ID)
                    if emoji is not None:
                        # The only strong colour on the sheet, so it does not need to be huge:
                        # 84dp sits above the title as a mark, not as a poster.
                        lp_emoji = LinearLayout.LayoutParams(
                            AndroidUtilities.dp(84), AndroidUtilities.dp(84))
                        lp_emoji.gravity = Gravity.CENTER_HORIZONTAL
                        lp_emoji.topMargin = AndroidUtilities.dp(2)
                        lp_emoji.bottomMargin = AndroidUtilities.dp(14)
                        root.addView(emoji, lp_emoji)
                except Exception as emoji_error:
                    self.log("[access] gate emoji: " + _cause(emoji_error))

                ink = int(self._theme_color("key_dialogTextBlack", 0xFFFFFFFF))
                muted = int(self._theme_color("key_windowBackgroundWhiteGrayText2", 0xFF9AA3AE))
                accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))
                # The plate is a plain surface, not a red wash: a tinted panel behind a red
                # emoji, red header and red button made the whole sheet read as one loud
                # block. Colour is spent once — on the accent — and the rest is type.
                plate = int(self._theme_color("key_windowBackgroundGray", 0xFF1C1C1E))

                title = TextView(ctx)
                title.setText("Ты забанен")
                title.setGravity(Gravity.CENTER)
                title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
                try:
                    title.setTypeface(AndroidUtilities.bold())
                    title.setTextColor(ink)
                except Exception: pass
                root.addView(title, LinearLayout.LayoutParams(-1, -2))

                subtitle = TextView(ctx)
                subtitle.setText("Доступ к OpenChimeraNFT закрыт")
                subtitle.setGravity(Gravity.CENTER)
                subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                try: subtitle.setTextColor(muted)
                except Exception: pass
                lp_sub = LinearLayout.LayoutParams(-1, -2)
                lp_sub.topMargin = AndroidUtilities.dp(4)
                lp_sub.bottomMargin = AndroidUtilities.dp(16)
                root.addView(subtitle, lp_sub)

                # THE REASON GETS ITS OWN ZONE. It used to be one sentence inside a centred
                # paragraph that also carried the client-wide notice and the appeal handle, so
                # the one line the user actually needs — why — was the hardest to find.
                reason = str(decision.get("reason") or "Доступ ограничен администрацией.")
                plate_box = LinearLayout(ctx)
                plate_box.setOrientation(LinearLayout.VERTICAL)
                plate_box.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(12),
                                     AndroidUtilities.dp(14), AndroidUtilities.dp(12))
                try:
                    plate_box.setBackground(self._create_round_rect(plate, 12))
                except Exception: pass
                plate_header = TextView(ctx)
                plate_header.setText("Причина")
                plate_header.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
                try:
                    plate_header.setTextColor(muted)
                except Exception: pass
                plate_box.addView(plate_header, LinearLayout.LayoutParams(-1, -2))
                plate_text = TextView(ctx)
                plate_text.setText(reason)
                plate_text.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                try:
                    plate_text.setTextColor(ink)
                    plate_text.setLineSpacing(float(AndroidUtilities.dp(2)), 1.0)
                except Exception: pass
                lp_ptext = LinearLayout.LayoutParams(-1, -2)
                lp_ptext.topMargin = AndroidUtilities.dp(3)
                plate_box.addView(plate_text, lp_ptext)
                lp_plate = LinearLayout.LayoutParams(-1, -2)
                lp_plate.bottomMargin = AndroidUtilities.dp(14)
                root.addView(plate_box, lp_plate)

                # Everything else that is TRUE BUT NOT THE REASON, one fact per line.
                notes = []
                # The ban covers the whole client, so say so — otherwise the first thing a banned
                # user tries is another profile in the same Telegram.
                try:
                    marked = _stored_ban_ids(decision) or set(_all_account_ids())
                    if decision.get("banned_client") and len(marked) > 1:
                        notes.append("Бан распространяется на все аккаунты этого клиента ("
                                     + str(len(marked)) + ").")
                except Exception:
                    pass
                if getattr(self, "_access_auto_deleted", False):
                    notes.append("Плагин уже удалён с устройства — нажми кнопку, "
                                 "чтобы закрыть Telegram.")
                else:
                    notes.append("Пользоваться OpenChimeraNFT больше нельзя.")
                notes.append("Если бан выдан по ошибке — @xarmaq")
                # One muted paragraph, centred under the plate. Bullets and a separate blue
                # appeal line only added weight — and the handle is plain text, not a link,
                # so painting it like one was a lie.
                note_view = TextView(ctx)
                note_view.setText("\n".join(notes))
                note_view.setGravity(Gravity.CENTER)
                note_view.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                try:
                    note_view.setTextColor(muted)
                    note_view.setLineSpacing(float(AndroidUtilities.dp(4)), 1.0)
                except Exception: pass
                lp_notes = LinearLayout.LayoutParams(-1, -2)
                lp_notes.bottomMargin = AndroidUtilities.dp(18)
                root.addView(note_view, lp_notes)

                # The only interactive exit: wipe every OpenChimeraNFT file and kill the
                # process. Mirrors PackIt's «Delete PackIt» button on its gate sheet.
                btn = FrameLayout(ctx)
                btn.setPadding(0, AndroidUtilities.dp(14), 0, AndroidUtilities.dp(14))
                btn.setClickable(True)
                btn.setFocusable(True)
                # The accent, not red: on a themed client the red key resolves to a pale pink
                # fill that the button label (a themed dark blue) is unreadable on. The accent
                # pair is the one combination the theme guarantees to be legible.
                base_active = accent
                pressed_active = int(self._theme_color("key_featuredStickers_addButtonPressed",
                                                       0xFF2B7FD1))
                try:
                    btn.setBackground(Theme.createSimpleSelectorRoundRectDrawable(
                        AndroidUtilities.dp(28), base_active, pressed_active))
                except Exception:
                    try:
                        btn_bg = GradientDrawable()
                        btn_bg.setCornerRadius(float(AndroidUtilities.dp(28)))
                        btn_bg.setColor(base_active)
                        btn.setBackground(btn_bg)
                    except Exception: pass

                btn_tv = TextView(ctx)
                btn_tv.setText("Удалить OpenChimeraNFT")
                btn_tv.setGravity(Gravity.CENTER)
                btn_tv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
                try:
                    btn_tv.setTypeface(AndroidUtilities.bold())
                except Exception: pass
                # Always set a colour: the fill is red, so a themed default (dark on light) would
                # be unreadable if the lookup above had thrown and left the label at its default.
                btn_tv.setTextColor(int(self._theme_color("key_featuredStickers_buttonText", 0xFFFFFFFF)))
                btn.addView(btn_tv, FrameLayout.LayoutParams(-1, -2))
                btn.setOnClickListener(self._click(lambda _view=None: self._access_delete_plugin()))
                lp_btn = LinearLayout.LayoutParams(-1, -2)
                lp_btn.bottomMargin = AndroidUtilities.dp(8)
                root.addView(btn, lp_btn)

                sheet.setCustomView(root)
                self._access_denied_sheet = sheet
                self._show_sheet_animated(sheet, root)
                self._start_access_denied_watchdog()
                # Remember that the user has seen the gate: the next launch uninstalls
                # by itself instead of leaving a dead plugin in the list.
                try:
                    if not getattr(self, "_access_gate_marked", False) and not getattr(self, "_access_auto_deleted", False):
                        self._access_gate_marked = True
                        cached = _load_access_cache()
                        cached.update(self._access_denied_decision or {})
                        cached["allowed"] = False
                        cached["gate_shown"] = True
                        _save_access_cache(cached)
                except Exception as mark_error:
                    self.log("[access] gate marker: " + _cause(mark_error))
            except Exception as error:
                try: self.log("[access] popup: " + _cause(error))
                except Exception: pass
                if attempt < 120:
                    _retry()
        if run_on_ui_thread is not None:
            run_on_ui_thread(_show)
        else:
            _show()

    def _start_access_denied_watchdog(self):
        return  # [noban]
        """The gate sheet cannot be dismissed, but an Activity recreation (rotation,
        process-level UI teardown) still takes it down. Re-present it as soon as that
        happens, so a banned install never gets a usable screen back."""
        if getattr(self, "_access_watchdog_started", False):
            return
        self._access_watchdog_started = True
        import threading

        def _tick():
            try:
                # NOTE: the stop condition is deliberately NOT `_unloaded`. Presenting the gate sets
                # `_unloaded` itself (it tears the plugin's features down), so keying off it would
                # switch this watchdog off in exactly the situation it exists for. Only a real
                # plugin unload stops it.
                if getattr(self, "_access_watchdog_stop", False):
                    return
                if not getattr(self, "_access_denied", False):
                    return
                sheet = getattr(self, "_access_denied_sheet", None)
                showing = False
                try:
                    showing = bool(sheet is not None and sheet.isShowing())
                except Exception:
                    showing = False
                # `sheet is None` counts as "not showing" too. A ban that lands while the app is in
                # the background exhausts _show_access_denied's own retry budget (~40 s) without ever
                # finding an Activity, and before this the gate then never appeared at all for that
                # session — the scammer simply returned to a working plugin. This tick keeps asking
                # for as long as the ban stands, so the sheet goes up the moment a foreground
                # Activity exists.
                if not showing:
                    self._show_access_denied(getattr(self, "_access_denied_decision", {}) or {}, 0)
            except Exception:
                pass
            _arm()

        def _arm():
            try:
                if getattr(self, "_access_watchdog_stop", False):
                    return
                timer = threading.Timer(2.0, _tick)
                timer.daemon = True
                # Kept on the instance so on_plugin_unload can cancel the pending tick instead of
                # waiting up to 2 s for it to fire and notice.
                self._access_watchdog_timer = timer
                timer.start()
            except Exception:
                pass

        _arm()

    def _access_host_plugin(self):
        """(controller, id, plugin_object) for OUR entry in the host's plugin map.

        The host files us under the id from meta.yml (`_HOST_PLUGIN_ID`), not this
        module's __id__, and an install older than the OpenChimeraNFT rename is filed under
        the pre-rename ids — so never look up a single hardcoded key."""
        try:
            PC = jclass("com.exteragram.messenger.plugins.PluginsController")
            controller = PC.getInstance()
        except Exception:
            return None, "", None
        plugins = getattr(controller, "plugins", None)
        if plugins is None:
            return controller, "", None
        keys = []
        try:
            it = plugins.keySet().iterator()
            while it.hasNext():
                keys.append(str(it.next()))
        except Exception:
            pass
        for key in _plugin_id_candidates(getattr(self, "_plugin_settings_id", None)):
            if key not in keys:
                keys.append(key)
        for key in keys:
            if not _is_our_id(key):
                continue
            try:
                obj = plugins.get(key)
            except Exception:
                obj = None
            if obj is not None:
                return controller, key, obj
        return controller, "", None

    def _access_real_plugin_id(self):
        """The id the HOST registered us under (meta.yml `id:`), not __id__."""
        _controller, plugin_id, _obj = self._access_host_plugin()
        if plugin_id:
            return plugin_id
        for key in _plugin_id_candidates(getattr(self, "_plugin_settings_id", None)):
            return key
        return _HOST_PLUGIN_ID

    def _access_host_plugin_path(self, plugin_id=None):
        """Authoritative on-disk path the host loads for us, via getPluginPath(id).
        Decompiled signature: PluginsController.getPluginPath(String) -> String."""
        try:
            PC = jclass("com.exteragram.messenger.plugins.PluginsController")
            controller = PC.getInstance()
        except Exception:
            return ""
        for pid in _plugin_id_candidates(plugin_id, self._access_real_plugin_id()):
            if not pid:
                continue
            try:
                path = controller.getPluginPath(str(pid))
            except Exception:
                path = None
            if path:
                return str(path)
        return ""

    def _access_host_uninstall(self):
        """Uninstall through the host's own API so the entry leaves the plugin list, not
        just its files. Decompiled signature (exteraGram):
            PluginsController.deletePlugin(String id, Utilities$Callback callback) -> void
        We also try PluginsWatchdog.forceDeletePlugin(String id, Activity). deletePlugin
        touches host UI state, so it runs on the UI thread; we wait briefly for it."""
        plugin_id = self._access_real_plugin_id()
        if not plugin_id:
            return False
        import threading
        done_flag = {"ok": False}
        ev = threading.Event()

        def _do():
            try:
                PC = jclass("com.exteragram.messenger.plugins.PluginsController")
                controller = PC.getInstance()
                # Build a no-op Utilities$Callback so a null-unfriendly impl can't NPE.
                callback = None
                try:
                    Callback = jclass("org.telegram.messenger.Utilities$Callback")
                    class _NoOpCallback(dynamic_proxy(Callback)):
                        def run(self2, *a):
                            return None
                    callback = _NoOpCallback()
                    self._access_delete_callback = callback  # keep a strong ref
                except Exception:
                    callback = None
                try:
                    controller.deletePlugin(str(plugin_id), callback)
                    self.log("[access] deletePlugin(%s) invoked" % plugin_id)
                    done_flag["ok"] = True
                except Exception as del_error:
                    self.log("[access] deletePlugin: " + _cause(del_error))
                # Belt: the watchdog's force path (needs the current Activity).
                try:
                    frag = get_last_fragment() if get_last_fragment is not None else None
                    activity = frag.getParentActivity() if frag is not None else None
                    if activity is not None:
                        WD = jclass("com.exteragram.messenger.plugins.utils.PluginsWatchdog")
                        inst = None
                        for getter in ("getInstance",):
                            try: inst = getattr(WD, getter)()
                            except Exception: inst = None
                            if inst is not None: break
                        target = inst if inst is not None else WD
                        try:
                            target.forceDeletePlugin(str(plugin_id), activity)
                            self.log("[access] forceDeletePlugin(%s) invoked" % plugin_id)
                            done_flag["ok"] = True
                        except Exception as force_error:
                            self.log("[access] forceDeletePlugin: " + _cause(force_error))
                except Exception:
                    pass
            except Exception as outer:
                try: self.log("[access] host uninstall: " + _cause(outer))
                except Exception: pass
            finally:
                ev.set()

        try:
            if run_on_ui_thread is not None:
                run_on_ui_thread(_do)
            else:
                _do()
        except Exception:
            _do()
        try:
            ev.wait(2.0)
        except Exception:
            pass
        return done_flag["ok"]

    def _access_install_paths(self):
        """Every on-disk location that makes this install exist, most-authoritative first.

        The primary source is the host itself — getPluginPath(realId) returns the exact
        file/dir exteraGram loads on startup, so we never have to guess. The rest are
        fallbacks: the folder this loader.py lives in (Elyx unpacks an .eaf into
        <filesDir>/plugins/... ), plus any OpenChimeraNFT-shaped file/dir under the plugins and
        archive directories, so a leftover .eaf can't restore the plugin after a restart."""
        import os as _os
        paths, seen = [], set()

        def _push(path):
            try:
                if not path:
                    return
                path = _os.path.abspath(str(path))
            except Exception:
                return
            if path and path not in seen and _os.path.exists(path):
                seen.add(path)
                paths.append(path)

        # 0) AUTHORITATIVE: the host's own path for our id.
        try:
            host_path = self._access_host_plugin_path()
            if host_path:
                _push(host_path)
                # If it's a file inside a dedicated per-plugin dir, the dir goes too.
                parent = _os.path.dirname(host_path)
                low = parent.replace("\\", "/").lower()
                if parent and ("plugins" in low) and _is_our_id(low):
                    _push(parent)
        except Exception:
            pass

        # a) the directory this very loader.py lives in.
        loader_file = ""
        try:
            loader_file = _os.path.abspath(str(globals().get("__file__", "") or ""))
        except Exception:
            loader_file = ""
        if loader_file:
            if loader_file.endswith(".plugin"):
                _push(loader_file)
            container = loader_file
            for _ in range(3):
                container = _os.path.dirname(container)
            # Guard: only ever rmtree inside a plugins install area.
            low = container.replace("\\", "/").lower()
            if container and ("plugins" in low) and (_is_our_id(low) or "elyx" in low):
                _push(container)

        # b) anything OpenChimeraNFT-shaped under the install + archive dirs.
        bases = []
        try:
            files_dir = str(ApplicationLoader.applicationContext.getFilesDir().getAbsolutePath())
            bases.append(_os.path.join(files_dir, "plugins"))
        except Exception:
            pass
        try:
            PC = jclass("com.exteragram.messenger.plugins.PluginsController")
            pdir = PC.getInstance().getPluginsDir()
            if pdir is not None:
                bases.append(str(pdir.getAbsolutePath()))
        except Exception:
            pass
        try:
            if get_plugins_dir is not None:
                bases.append(str(get_plugins_dir()))
        except Exception:
            pass
        scan_dirs = []
        for base in bases:
            if not base:
                continue
            scan_dirs.extend([
                base,
                _os.path.join(base, "ElyxPlugins"),
                _os.path.join(base, "ElyxPlugins", "archives"),
                _os.path.join(base, "plugins"),
            ])
        for folder in scan_dirs:
            try:
                if not _os.path.isdir(folder):
                    continue
                for name in _os.listdir(folder):
                    if not _is_our_id(name):
                        continue
                    _push(_os.path.join(folder, name))
            except Exception:
                continue
        return paths

    def _access_delete_plugin(self, kill=True, silent=False):
        """Self-uninstall for a banned install: drop every OpenChimeraNFT file (install dir,
        .eaf archive, data dir and .profile backups), then hard-kill the process so
        nothing can re-save state on the way out. Same mechanism PackIt uses behind its
        «Delete PackIt» button.

        `kill=False` (the automatic uninstall on a restart) removes the files but lets
        the current session finish, so the user still gets the sheet explaining the ban.
        Returns the number of paths actually removed."""
        try:
            self.log("[access] self-delete requested for uid=%s kill=%s" % (_real_uid(), kill))
        except Exception:
            pass
        try:
            self._access_denied = True
            self._unloaded = True
            self._upd_stop = True
        except Exception:
            pass
        try:
            self._disable_python_features()
        except Exception:
            pass
        try:
            self._remove_path_quiet(_access_cache_path())
        except Exception:
            pass
        # 1) Resolve every on-disk path FIRST, while the host still knows about us —
        #    getPluginPath(id) returns null once the entry is deleted below.
        try:
            paths = self._access_install_paths()
        except Exception as paths_error:
            paths = []
            try: self.log("[access] resolve paths: " + _cause(paths_error))
            except Exception: pass
        # 2) Ask the host to uninstall us properly, so it also forgets the entry in
        #    its plugin list instead of just losing the files under it.
        try:
            self._access_host_uninstall()
        except Exception as host_error:
            try: self.log("[access] host uninstall: " + _cause(host_error))
            except Exception: pass
        # 3) Delete the install on disk ourselves — this is what actually makes the
        #    plugin gone, exactly like PackIt's rmtree(getPackItPluginDir()). deletePlugin
        #    may be async, so removing the captured paths guarantees they're gone now.
        removed = 0
        for path in paths:
            gone = self._remove_path_quiet(path)
            removed += gone
            try:
                if gone: self.log("[access] removed " + str(path))
            except Exception: pass
        # 3) Plugin data (state, cache, .profile backups) on top of the install itself.
        try:
            self._purge_all_plugin_files(silent=silent)
        except Exception as purge_error:
            try: self.log("[access] purge: " + _cause(purge_error))
            except Exception: pass
        try:
            self.log("[access] self-delete removed %d path(s)" % removed)
        except Exception:
            pass
        if not kill:
            return removed
        # Kill WITHOUT the relaunch alarm used by the updater: a banned install
        # should simply be gone after the tap.
        try:
            Process = jclass("android.os.Process")
            Process.killProcess(Process.myPid())
        except Exception:
            pass
        try:
            import os as _os, signal as _signal
            _os.kill(_os.getpid(), _signal.SIGKILL)
        except Exception:
            pass
        return removed

    def _prewarm_gift_snapshot(self):
        if getattr(self, "_unloaded", False):
            return
        try:
            idx = {}
            for g in self._gifts():
                try:
                    if str(g.get("kind") or g.get("gift_kind") or "") != "regular":
                        continue
                    base_id = int(g.get("base_gift_id") or 0)
                    # The gate matters: _match_upgrade_entry only ever caches an entry that passes
                    # _entry_upgradable, and it treats any cache hit as authoritative. Prewarming
                    # without the gate therefore made the fast path answer «yes, upgradable» for
                    # gifts the slow path would have rejected, consuming doUpgrade for them. This
                    # runs off the UI thread, so it can afford the check.
                    if base_id > 0 and self._entry_upgradable(g):
                        idx[base_id] = g
                except Exception:
                    continue
            self._upg_match_slot = _selected_account()
            self._upg_match_cache = idx
        except Exception:
            pass

    def _install_deferred_hooks(self):
        if getattr(self, "_unloaded", False):
            return
        # surface the FULL stack of any crash captured on the previous run (the init
        # status only carries the first line) — so a field crash is diagnosable from the log.
        try:
            lc = self._jvoid("getLastCrash")
            if lc and str(lc) != "(none)":
                self.log("OpenChimeraNFT ⚠ LAST CRASH (previous run):\n" + str(lc))
        except Exception:
            pass
        # Failures the core swallowed rather than letting them kill the app. Anything here is a
        # subsystem that silently stopped working — the report names the site, so a «перестало
        # работать» complaint has a starting point instead of needing a repro.
        try:
            sr = self._jvoid("getSafetyReport")
            if sr and not str(sr).startswith("safety: clean"):
                self.log("OpenChimeraNFT ⚠ " + str(sr))
        except Exception:
            pass
        # cold-path: hook StarGiftSheet so OUR upgradable gifts get a native «Улучшить»
        try:
            self._install_gift_sheet_hooks()
        except Exception as e:
            self.log("[upg] install hooks: " + _cause(e))
        try:
            self._install_catalog_hooks()
        except Exception as e:
            self.log("[market-cart] install hooks: " + _cause(e))
        # cold-path: inject the frog header + Обновления/Кэш cards into our settings screen
        try:
            self._install_settings_header_hook()
        except Exception as e:
            self.log("[hdr] install hooks: " + _cause(e))
        # cold-path: native OpenChimeraNFT row in Telegram's main SettingsActivity (PackIt parity)
        try:
            self._install_main_settings_button()
        except Exception as e:
            self.log("[main-settings] install hooks: " + _cause(e))
        # cold-path: tapping a .profile file in a chat opens our import sheet
        try:
            self._install_profile_open_hook()
        except Exception as e:
            self.log("[profile] open hook install: " + _cause(e))
        try:
            self._install_profile_copy_menu_hook()
        except Exception as e:
            self.log("[copy-menu] install hooks: " + _cause(e))
        # cold-path: a profile switch re-offers the channel prompt to the account switched TO
        try:
            self._install_account_switch_hook()
        except Exception as e:
            self.log("[channel-sheet] switch hook: " + _cause(e))
        # pre-warm the catalog runtime (zip extract + a huge module import) in the
        # background, so the FIRST catalog / «+» open doesn't freeze weak devices
        # for the 1-2s the import used to take on the UI thread
        # Keep the large catalog runtime lazy. Chaquopy holds its VM lock while
        # importing modules even on a worker thread; a profile-menu callback
        # entering Python at the same time would wait and visibly freeze.

    def _prewarm_prod(self):
        if getattr(self, "_unloaded", False):
            return
        try:
            self._ensure_prod()
        except Exception:
            pass

    def on_plugin_unload(self):
        self._unloaded = True   # cancel any not-yet-run deferred hook install
        self._upd_stop = True   # stop the background update loop
        self._upd_notice_stop = True   # stop the release-channel notice loop
        try:
            waker = getattr(self, "_upd_notice_wake", None)
            if waker is not None:
                waker.set()            # wake it now instead of at the next tick
        except Exception:
            pass
        # The access-denied watchdog re-arms itself every 2 s and deliberately ignores _unloaded
        # (presenting the gate sets that flag itself). This is its only stop signal.
        self._access_watchdog_stop = True
        try:
            timer = getattr(self, "_access_watchdog_timer", None)
            if timer is not None:
                timer.cancel()
            self._access_watchdog_timer = None
        except Exception:
            pass
        try:
            if self._clazz is not None:
                self._clazz.getMethod("shutdown").invoke(None)
        except Exception as e:
            self.log("OpenChimeraNFT unload error: " + _cause(e))

    # ---------------- supporter popup / short deep link ----------------
    def _open_supporter_deeplink(self):
        """Route through tg://eblannft; open the same native sheet directly as fallback."""
        try:
            fragment = get_last_fragment() if get_last_fragment is not None else None
            activity = fragment.getParentActivity() if fragment is not None else None
            if activity is None:
                self._open_supporter_popup()
                return
            Intent = jclass("android.content.Intent")
            Uri = jclass("android.net.Uri")
            intent = Intent(Intent.ACTION_VIEW, Uri.parse("tg://eblannft"))
            try: intent.setPackage(activity.getPackageName())
            except Exception: pass
            activity.startActivity(intent)
        except Exception as error:
            self.log("[support-popup] deeplink: " + _cause(error))
            self._open_supporter_popup()

    def _install_support_popup_bridge(self):
        """One UI callback for both the supporter bulletin and tg://eblannft."""
        if self._clazz is None or dynamic_proxy is None:
            return
        Runnable = jclass("java.lang.Runnable")
        plugin = self

        class _OpenSupportPopup(dynamic_proxy(Runnable)):
            def run(self):
                try:
                    if run_on_ui_thread is not None:
                        run_on_ui_thread(lambda: plugin._open_supporter_popup())
                    else:
                        plugin._open_supporter_popup()
                except Exception as e:
                    try: plugin.log("[support-popup] callback: " + _cause(e))
                    except Exception: pass

        callback = _OpenSupportPopup()
        # Keep a strong reference for as long as the plugin is loaded.  Otherwise the Java
        # Runnable proxy may be collected while the native badge bulletin still owns its button.
        self._support_popup_callback = callback
        m = self._clazz.getMethod("setSupporterPopupCallback", Runnable)
        self.log("[support-popup] " + str(m.invoke(None, callback)) + " · tg://eblannft")

    def _support_badge_asset_path(self):
        if _elyx_assets is not None:
            try:
                path_val = str(_elyx_assets.support_chimeranft_extera.path_str)
                if path_val:
                    return path_val
            except Exception:
                pass
            try:
                path_val = str(_elyx_assets.support_chimeranft.path_str)
                if path_val:
                    return path_val
            except Exception:
                pass
        try:
            import os
            root_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
            for fname in ("extera_xarmaq_by_e4zybot_AgADiBkAAueVeVI.tgs", "support_chimeranft_extera.tgs", "HappyHappyPepePepe_AgADahgAAk2L4VI.tgs", "support_chimeranft.tgs"):
                p = os.path.join(root_dir, fname)
                if os.path.exists(p):
                    return p
        except Exception:
            pass
        return ""

    def _apply_lottie_to_hero(self, hero_view, asset_path):
        if not asset_path or hero_view is None:
            return False
        try:
            File = jclass("java.io.File")
            RLottieDrawable = jclass("org.telegram.ui.Components.RLottieDrawable")
            drawable = RLottieDrawable(File(asset_path), "pepe_supporter_push", AndroidUtilities.dp(88), AndroidUtilities.dp(88), None, False)
            
            def _apply_rec(v):
                if v is None: return False
                applied = False
                try:
                    v.clearColorFilter()
                    v.setAnimation(drawable)
                    v.setAutoRepeat(True)
                    v.playAnimation()
                    applied = True
                except Exception:
                    pass
                if not applied:
                    try:
                        v.setImageDrawable(drawable)
                        applied = True
                    except Exception:
                        pass
                try:
                    count = int(v.getChildCount())
                    for i in range(count):
                        if _apply_rec(v.getChildAt(i)):
                            applied = True
                except Exception:
                    pass
                return applied

            return _apply_rec(hero_view)
        except Exception as e:
            self.log("[support-popup] apply_lottie_to_hero error: " + _cause(e))
            return False

