    SUPPORT_BETA_TITLE = "Доступ к бета-обновлениям"
    SUPPORT_BETA_TEXT = "Ранние сборки приходят раньше публичного релиза."
    # Perk rows in reading order. Subtitles are deliberately one line each: four rows of three-line
    # text is what made the sheet look untidy next to exteraGram's own.
    SUPPORT_ROWS = (
        ("Поддержать проект", "Один раз 100 Telegram Stars в боте."),
        ("Уникальный бейдж", "Появляется рядом с именем сразу после оплаты."),
        (SUPPORT_BETA_TITLE, SUPPORT_BETA_TEXT),
        ("Исходный код", "GitHub — m4rker20-rgb/OpenChimeraNFT."),
    )
    # Per row, host drawables in preference order — forks rename and drop icons, so each row needs a
    # fallback rather than one guess.
    SUPPORT_ROW_ICONS = (
        ("menu_feature_paid", "menu_feature_premium"),
        ("menu_feature_status", "menu_feature_unique", "menu_feature_reactions"),
        ("menu_feature_hourglass", "menu_premium_clock", "menu_feature_intro", "msg_speed_fast"),
        ("menu_feature_reactions", "menu_feature_links", "menu_feature_wallpaper"),
    )
    SUPPORT_ROW_ACTIONS = (0, 3)   # rows that open the support bot
    # Hero above the title. exteraGram puts ITS logo there; ours is the OpenChimeraNFT supporter badge
    # emoji — the same custom emoji the badge itself uses, so the sheet and the badge match. The
    # live badge icon of the profile that was tapped wins over this constant when the core knows it.
    SUPPORT_HERO_EMOJI_ID = 5983592864481811706

    # PackIt-style custom emoji on the ban gate: <tg-emoji emoji-id="5211099269234183739">🚫</tg-emoji>
    ACCESS_DENIED_EMOJI_ID = 5211099269234183739

    def _custom_emoji_view(self, ctx, document_id):
        """One premium/custom emoji rendered by Telegram's OWN animated-emoji drawable — the same
        thing a <tg-emoji> entity in a message draws, so it animates and caches like the real one.
        `addView` is what makes the drawable invalidate our view every frame; without it the emoji
        would render a single static frame. Returns None on any fork that lacks the class."""
        try:
            if ImageView is None or jclass is None:
                return None
            AnimatedEmojiDrawable = jclass("org.telegram.ui.Components.AnimatedEmojiDrawable")
            if AnimatedEmojiDrawable is None:
                return None
            try:
                account = _selected_account()
            except Exception:
                account = 0
            # The cache type IS the render resolution: ALERT_PREVIEW_LARGE rasterizes at 34dp, so a
            # hero-sized emoji built from it is upscaled — small-looking and soft. ..._LARGE_140
            # rasterizes at 140dp, which is crisp at any hero size we use. Older forks may not have
            # the constant, hence the ordered fallback.
            cache_type = 4
            for name in ("CACHE_TYPE_ALERT_PREVIEW_LARGE_140", "CACHE_TYPE_ALERT_PREVIEW_LARGE"):
                try:
                    value = int(getattr(AnimatedEmojiDrawable, name))
                except Exception:
                    continue
                if value > 0:
                    cache_type = value
                    break
            drawable = AnimatedEmojiDrawable.make(account, cache_type, int(document_id))
            if drawable is None:
                return None
            view = ImageView(ctx)
            try: view.setScaleType(ImageView.ScaleType.FIT_CENTER)
            except Exception: pass
            view.setImageDrawable(drawable)
            try: drawable.addView(view)
            except Exception: pass
            # Keep the drawable alive while its view is on screen, but do not accumulate: an
            # AnimatedEmojiDrawable holds an ImageReceiver, and `addView` registered us as its
            # invalidate target. Detach everything but the few most recent heroes.
            live = getattr(self, "_custom_emoji_drawables", [])
            live.append((drawable, view))
            while len(live) > 4:
                old_drawable, old_view = live.pop(0)
                try: old_drawable.removeView(old_view)
                except Exception: pass
            self._custom_emoji_drawables = live
            return view
        except Exception as e:
            try: self.log("[emoji] custom emoji view: " + _cause(e))
            except Exception: pass
            return None

    def _support_hero_emoji_id(self):
        """The badge emoji to show above the title: the one the tapped profile actually wears when the
        core knows it, otherwise the OpenChimeraNFT supporter badge."""
        try:
            live = self._jvoid("getSupporterPopupIconId")
            if live is not None and int(live) > 0:
                return int(live)
        except Exception:
            pass
        return self.SUPPORT_HERO_EMOJI_ID

    def _apply_support_hero(self, root, ctx):
        """Swap exteraGram's logo at the top of the supporter sheet for our own hero.

        A custom emoji is tried first: it needs no packaged asset and no file path, which is what
        made the Lottie hero fail silently on some installs and leave the fork's red logo in place.
        The Pepe .tgs stays as the second choice, and if neither is available the fork's own hero is
        left alone rather than replaced by a hole."""
        try:
            current = root.getChildAt(0)
            ours = getattr(self, "_support_hero_view", None)
            if ours is not None and current == ours:
                return True
            hero = self._custom_emoji_view(ctx, self._support_hero_emoji_id())
            if hero is None:
                hero = self._lottie_hero_view(ctx)
            if hero is None:
                return False
            # Inherit exteraGram's OWN layout params for that slot (80x80, centered, 28dp above the
            # title). Inventing our own size and margins is what made the top of the sheet look out of
            # proportion: a bigger hero with less air around it than everything below expects.
            lp_hero = None
            try:
                lp_hero = current.getLayoutParams()
            except Exception:
                lp_hero = None
            if lp_hero is None:
                lp_hero = LinearLayout.LayoutParams(AndroidUtilities.dp(80), AndroidUtilities.dp(80))
                lp_hero.gravity = Gravity.CENTER_HORIZONTAL
                lp_hero.topMargin = AndroidUtilities.dp(28)
            root.removeViewAt(0)
            root.addView(hero, 0, lp_hero)
            self._support_hero_view = hero
            self._support_popup_hero = hero
            return True
        except Exception as hero_error:
            self.log("[support-popup] hero replacement: " + _cause(hero_error))
            return False

    def _lottie_hero_view(self, ctx):
        """Packaged Pepe sticker hero — the fallback when the custom emoji is unavailable."""
        try:
            asset_path = self._support_badge_asset_path()
            if not asset_path:
                return None
            File = jclass("java.io.File")
            RLottieDrawable = jclass("org.telegram.ui.Components.RLottieDrawable")
            RLottieImageView = jclass("org.telegram.ui.Components.RLottieImageView")
            hero = RLottieImageView(ctx)
            drawable = RLottieDrawable(File(asset_path), "pepe_supporter_push",
                                       AndroidUtilities.dp(80), AndroidUtilities.dp(80), None, False)
            hero.setAnimation(drawable)
            hero.setAutoRepeat(True)
            hero.playAnimation()
            return hero
        except Exception as lottie_error:
            self.log("[support-popup] lottie hero: " + _cause(lottie_error))
            return None

    def _clone_native_feature_cell(self, sample, sheet, ctx, icon_names, title, subtitle):
        """Build one more of exteraGram's OWN `SupporterBottomSheet.FeatureCell` rows, so an added
        perk is indistinguishable from the three the fork ships. The class is a package-private inner
        class, so it is instantiated from the SAMPLE cell's own class object — that needs no class
        name and survives renaming."""
        try:
            if jarray is None:
                return None
            rid = 0
            try:
                res = ctx.getResources()
                package_name = ctx.getPackageName()
                for name in icon_names:
                    rid = int(res.getIdentifier(name, "drawable", package_name))
                    if rid != 0:
                        break
            except Exception:
                rid = 0
            if rid == 0:
                return None
            ctor = None
            for candidate in sample.getClass().getDeclaredConstructors():
                # (outer SupporterBottomSheet, Context, int iconRes, CharSequence, CharSequence)
                if int(candidate.getParameterCount()) == 5:
                    ctor = candidate
                    break
            if ctor is None:
                return None
            ctor.setAccessible(True)
            JObject = jclass("java.lang.Object")
            args = jarray(JObject)([sheet, ctx, JInteger(rid), str(title), str(subtitle)])
            return ctor.newInstance(args)
        except Exception as e:
            try: self.log("[support-popup] feature cell clone: " + _cause(e))
            except Exception: pass
            return None

