    def _set_hide_official_gifts(self, enabled):
        # Hiding half the profile's gifts is a large visual change for one toggle, so it gets the
        # heavier «crunch» on the way in and a plain toggle on the way back out.
        self._jvoid("setHideOfficialGifts", ("int",), (1 if enabled else 0,))
        self._hap("crunch" if enabled else "toggle_off")

    def _pinned_channel_status(self, st=None):
        try:
            value = (st or self._settings()).get("pinned_channel") or {}
            if bool(value.get("enabled", False)) and str(value.get("username", "")).strip():
                return "@" + str(value.get("username", "")).strip().lstrip("@")
        except Exception:
            pass
        return "Не выбран"

    #: Hosts that serve a t.me link. `telesco.pe` is the old preview mirror; people still paste it.
    _CHANNEL_LINK_HOSTS = ("t.me/", "telegram.me/", "telegram.dog/", "telesco.pe/")

    #: First path segment of a t.me link that is a Telegram FEATURE, never a channel. Refusing these
    #: by name is what lets the generic message stay generic.
    _CHANNEL_LINK_SERVICE = frozenset((
        "addstickers", "addemoji", "addtheme", "addlist", "setlanguage", "share", "proxy", "socks",
        "login", "invoice", "bg", "confirmphone", "contact", "giftcode", "boost", "premium", "iv",
        "m", "nft", "call", "wallet",
    ))

    _LINK_PRIVATE = "Это приватная ссылка-приглашение. Закрепить можно только публичный канал"
    _LINK_SERVICE = "Это служебная ссылка Telegram, а не канал"
    _LINK_GENERIC = "Нужна ссылка вида t.me/канал или @канал"

    @staticmethod
    def _parse_channel_link(value):
        """``(username, reason)`` for anything a human can paste into the link field.

        * ``("", "")``    — the field was cleared, i.e. «убрать закрепление»;
        * ``(name, "")``  — a public @username to resolve;
        * ``(None, why)`` — refused, with the sentence the card should show.

        The parser this replaces understood exactly ONE shape, ``t.me/name``, and answered a flat
        «Нужна публичная ссылка» to everything else — before a single request went out. Every other
        way a channel actually gets shared was in that "everything else": a link to a POST
        (``t.me/name/1234``, which is what the share sheet and every forwarded message produce), the
        web preview (``t.me/s/name``), the ``telegram.me`` / ``telegram.dog`` mirrors, and
        ``tg://resolve?domain=name``. That is most of «некоторые каналы не закрепляются», and it
        looked like a broken button rather than a rejected link.
        """
        raw = str(value or "")
        for junk in ("​", "‌", "‍", "‎", "‏", "﻿"):
            raw = raw.replace(junk, "")
        # A pasted link arrives wrapped in whatever surrounded it: quotes, brackets, a sentence dot.
        raw = raw.strip().strip("<>()[]{}\"'«»").strip().rstrip(".,;!").strip()
        if not raw:
            return "", ""
        lower = raw.lower()

        if lower.startswith("tg://"):
            head, _, query = raw[5:].partition("?")
            head = head.strip("/").lower()
            if head in ("join", "privatepost"):
                return None, Plugin._LINK_PRIVATE
            if head not in ("resolve", "openmessage"):
                return None, Plugin._LINK_SERVICE
            for part in query.split("&"):
                key, _, val = part.partition("=")
                if key.strip().lower() == "domain":
                    return Plugin._channel_username(val.strip())
            return None, Plugin._LINK_GENERIC

        body = raw
        for scheme in ("https://", "http://", "//"):
            if body.lower().startswith(scheme):
                body = body[len(scheme):]
                break
        if body.lower().startswith("www."):
            body = body[4:]
        hosted = False
        for host in Plugin._CHANNEL_LINK_HOSTS:
            if body.lower().startswith(host):
                body = body[len(host):]
                hosted = True
                break
        # No known host and a path anyway — some other site, not a Telegram link.
        if not hosted and "/" in body and "." in body.split("/", 1)[0]:
            return None, Plugin._LINK_GENERIC

        body = body.split("?", 1)[0].split("#", 1)[0].strip().strip("/")
        if body.startswith("@"):
            body = body[1:]
        if not body:
            return None, Plugin._LINK_GENERIC

        first = body.split("/", 1)[0]
        low = first.lower()
        # `+hash` and `joinchat/hash` are invite links; `c/<id>/<post>` addresses a channel by its
        # INTERNAL id, which only members can use. None of the three carries a public username, and
        # a pin without one is a row no other plugin user could ever resolve.
        if first.startswith("+") or low in ("joinchat", "c"):
            return None, Plugin._LINK_PRIVATE
        if low in Plugin._CHANNEL_LINK_SERVICE:
            return None, Plugin._LINK_SERVICE
        if low == "s":                                    # t.me/s/name — the web preview
            parts = body.split("/")
            return Plugin._channel_username(parts[1] if len(parts) > 1 else "")
        # t.me/name/1234 (a post) and t.me/name/12/34 (a topic) both pin the CHANNEL itself.
        return Plugin._channel_username(first)

    @staticmethod
    def _channel_username(candidate):
        """Validate the bare @username. Deliberately lenient about everything Telegram may allow.

        The old bounds (4…64, `str.isalnum`) were wrong in both directions: `isalnum` is
        Unicode-aware, so `@канал` passed and then failed on the server as a mystery, while a real
        4-character Fragment username sat right on the edge. What matters locally is only "this
        cannot be a username at all"; anything arguable goes to the server, whose refusal the card
        now shows verbatim.
        """
        name = str(candidate or "").strip().lstrip("@").strip("/").strip()
        if not name or len(name) > 32:
            return None, Plugin._LINK_GENERIC
        letters = False
        for ch in name:
            if ("a" <= ch <= "z") or ("A" <= ch <= "Z"):
                letters = True
            elif not (("0" <= ch <= "9") or ch == "_"):
                return None, Plugin._LINK_GENERIC
        if not letters:
            return None, Plugin._LINK_GENERIC
        return name, ""

    @staticmethod
    def _normalize_public_channel_link(value):
        """The one-value form: `""` clears the pin, `None` refuses it, else the @username."""
        username, _reason = Plugin._parse_channel_link(value)
        return username

    def _open_pinned_channel_dialog(self):
        try:
            fragment = get_last_fragment()
            ctx = fragment.getParentActivity() if fragment is not None else None
            if ctx is None:
                self._toast(S("no_context"))
                return
            run_on_ui_thread(lambda: self._show_pinned_channel_sheet(ctx))
        except Exception as error:
            self.log("[pinned-channel] open: " + _cause(error))

    def _show_pinned_channel_sheet(self, ctx):
        """The pinned-channel editor: what is pinned now, drawn from the channel itself.

        The old dialog was a bare link field — it never showed WHICH channel was pinned, only
        its @username, and nothing about what the profile row would look like. The card here
        is built from the chat object the client already has (avatar, title, subscriber
        count), i.e. the same three facts the native row renders.
        """
        try:
            self._drop_pinned_sheet_refs()
            self._pinned_ctx = ctx
            accent = self._theme_color("key_featuredStickers_addButton", 0xFF3390EC)
            grey = self._theme_color("key_windowBackgroundWhiteGrayText", 0xFF9AA3AE)
            ink = self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)
            state = (self._settings().get("pinned_channel") or {})
            current = str(state.get("username", "") or "").lstrip("@")

            scroll = ScrollView(ctx)
            scroll.setVerticalScrollBarEnabled(False)
            col = LinearLayout(ctx)
            col.setOrientation(LinearLayout.VERTICAL)
            col.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(14),
                           AndroidUtilities.dp(16), AndroidUtilities.dp(18))

            header = LinearLayout(ctx)
            header.setOrientation(LinearLayout.HORIZONTAL)
            header.setGravity(Gravity.CENTER_VERTICAL)
            titles = LinearLayout(ctx)
            titles.setOrientation(LinearLayout.VERTICAL)
            title = TextView(ctx)
            title.setText("Закреплённый канал")
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            title.setTextColor(ink)
            try: title.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            titles.addView(title, LinearLayout.LayoutParams(-1, -2))
            subtitle = TextView(ctx)
            subtitle.setText(("@" + current) if current else "не выбран")
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            subtitle.setTextColor(accent if current else grey)
            titles.addView(subtitle, LinearLayout.LayoutParams(-1, -2))
            self._pinned_subtitle = subtitle
            header.addView(titles, LinearLayout.LayoutParams(0, -2, 1.0))
            header.addView(self._tg_icon_button(
                ctx, ("ic_close_white", "msg_close", "msg_clear"), grey, "Закрыть",
                lambda v: self._close_pinned_channel_sheet()),
                LinearLayout.LayoutParams(AndroidUtilities.dp(40), AndroidUtilities.dp(40)))
            hlp = LinearLayout.LayoutParams(-1, -2); hlp.bottomMargin = AndroidUtilities.dp(12)
            col.addView(header, hlp)

            card = LinearLayout(ctx)
            card.setOrientation(LinearLayout.HORIZONTAL)
            card.setGravity(Gravity.CENTER_VERTICAL)
            try:
                shape = GradientDrawable()
                shape.setCornerRadius(float(AndroidUtilities.dp(14)))
                shape.setColor(self._theme_color("key_windowBackgroundGray", 0xFF1B2732))
                card.setBackground(shape)
            except Exception:
                pass
            card.setPadding(AndroidUtilities.dp(12), AndroidUtilities.dp(12),
                            AndroidUtilities.dp(12), AndroidUtilities.dp(12))
            avatar_holder = FrameLayout(ctx)
            alp = LinearLayout.LayoutParams(AndroidUtilities.dp(48), AndroidUtilities.dp(48))
            alp.rightMargin = AndroidUtilities.dp(12)
            card.addView(avatar_holder, alp)
            card_texts = LinearLayout(ctx)
            card_texts.setOrientation(LinearLayout.VERTICAL)
            card_title = TextView(ctx)
            card_title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
            card_title.setTextColor(ink)
            try: card_title.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            card_texts.addView(card_title, LinearLayout.LayoutParams(-1, -2))
            card_sub = TextView(ctx)
            card_sub.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            card_sub.setTextColor(grey)
            card_texts.addView(card_sub, LinearLayout.LayoutParams(-1, -2))
            card.addView(card_texts, LinearLayout.LayoutParams(0, -2, 1.0))
            self._pinned_avatar_holder = avatar_holder
            self._pinned_card_title = card_title
            self._pinned_card_sub = card_sub
            col.addView(card, LinearLayout.LayoutParams(-1, -2))

            field_label = TextView(ctx)
            field_label.setText("Публичная ссылка")
            field_label.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
            field_label.setTextColor(grey)
            fllp = LinearLayout.LayoutParams(-1, -2); fllp.topMargin = AndroidUtilities.dp(14)
            col.addView(field_label, fllp)

            field = EditText(ctx)
            field.setSingleLine(True)
            field.setHint("t.me/канал или @канал")
            field.setText(("https://t.me/" + current) if current else "")
            try:
                field.setSelection(field.length())
                field.setTextColor(ink)
                field.setHintTextColor(grey)
            except Exception:
                pass
            col.addView(field, LinearLayout.LayoutParams(-1, -2))

            hint = TextView(ctx)
            hint.setText("Ссылка, @юзернейм или ссылка на пост — подойдёт любая.\n"
                         "Канал должен быть публичным. Пустое поле убирает закрепление.")
            hint.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
            hint.setTextColor(grey)
            hnlp = LinearLayout.LayoutParams(-1, -2); hnlp.topMargin = AndroidUtilities.dp(6)
            col.addView(hint, hnlp)

            pin_btn = jclass("org.telegram.ui.Stories.recorder.ButtonWithCounterView")(ctx, True, None)
            pin_btn.setRound()
            pin_btn.setText("Закрепить", False)
            pin_btn.setOnClickListener(self._click(
                lambda v: self._save_pinned_channel_link(str(field.getText()))))
            self._apply_channel_button_press_scale(pin_btn)
            pblp = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48))
            pblp.topMargin = AndroidUtilities.dp(14)
            col.addView(pin_btn, pblp)

            open_btn = jclass("org.telegram.ui.Stories.recorder.ButtonWithCounterView")(ctx, False, None)
            open_btn.setRound()
            open_btn.setNeutral()
            open_btn.setText("Открыть канал", False)
            open_btn.setOnClickListener(self._click(lambda v: self._open_pinned_channel_link()))
            self._apply_channel_button_press_scale(open_btn)
            oblp = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48))
            oblp.topMargin = AndroidUtilities.dp(8)
            col.addView(open_btn, oblp)
            self._pinned_open_btn = open_btn

            remove_btn = jclass("org.telegram.ui.Stories.recorder.ButtonWithCounterView")(ctx, False, None)
            remove_btn.setRound()
            remove_btn.setNeutral()
            remove_btn.setText("Убрать закрепление", False)
            remove_btn.setOnClickListener(self._click(
                lambda v: self._save_pinned_channel_link("")))
            self._apply_channel_button_press_scale(remove_btn)
            rblp = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48))
            rblp.topMargin = AndroidUtilities.dp(8)
            col.addView(remove_btn, rblp)
            self._pinned_remove_btn = remove_btn

            self._update_pinned_channel_card()

            scroll.addView(col)
            screen_h = 0
            try:
                screen_h = int(AndroidUtilities.displaySize.y)
            except Exception:
                screen_h = 0
            max_h = int(screen_h * 0.82) if screen_h > 0 else AndroidUtilities.dp(600)
            estimate = AndroidUtilities.dp(470)
            holder = FrameLayout(ctx)
            holder.addView(scroll, FrameLayout.LayoutParams(
                -1, max_h if estimate > max_h else -2))
            sheet = BottomSheet.Builder(ctx).setCustomView(holder).create()
            self._pinned_sheet = sheet
            try: sheet.setCanDismissWithSwipe(False)
            except Exception: pass
            # Without this the sheet's window keeps FLAG_ALT_FOCUSABLE_IM and the link field
            # can never open the keyboard.
            try: sheet.setFocusable(True)
            except Exception as error: self.log("[pinned-channel] focusable: " + _cause(error))
            plugin = self
            this_sheet = sheet

            class _PinnedDismissed(dynamic_proxy(jclass("android.content.DialogInterface$OnDismissListener"))):
                def onDismiss(self2, _dialog):
                    cur = getattr(plugin, "_pinned_sheet", None)
                    if cur is not None and not cur.equals(this_sheet):
                        return
                    plugin._drop_pinned_sheet_refs()

            listener = _PinnedDismissed()
            self._pinned_dismiss = listener
            try: sheet.setOnDismissListener(listener)
            except Exception: pass
            self._show_sheet_animated(sheet, holder)
        except Exception as error:
            self.log("[pinned-channel] sheet: " + _cause(error))
            self._toast("Не удалось открыть настройку канала")

    def _update_pinned_channel_card(self):
        """Fill the card from the stored state plus the chat the client already has cached."""
        ctx = getattr(self, "_pinned_ctx", None)
        if ctx is None:
            return
        try:
            state = (self._settings().get("pinned_channel") or {})
            username = str(state.get("username", "") or "").lstrip("@")
            enabled = bool(state.get("enabled", False)) and bool(username)
            title = str(state.get("title", "") or "")
            participants = int(state.get("participants_count", 0) or 0)
            chat = None
            try:
                cid = int(state.get("id", 0) or 0)
                if cid > 0:
                    chat = jclass("org.telegram.messenger.MessagesController") \
                        .getInstance(_selected_account()).getChat(JLong(cid))
            except Exception:
                chat = None
            if not title and chat is not None:
                title = str(getattr(chat, "title", "") or "")

            subtitle = getattr(self, "_pinned_subtitle", None)
            if subtitle is not None:
                subtitle.setText(("@" + username) if enabled else "не выбран")
            card_title = getattr(self, "_pinned_card_title", None)
            if card_title is not None:
                card_title.setText(title or (("@" + username) if username else "Канал не выбран"))
            card_sub = getattr(self, "_pinned_card_sub", None)
            if card_sub is not None:
                if enabled:
                    parts = ["@" + username]
                    if participants > 0:
                        parts.append(_format_subscribers(participants))
                    card_sub.setText(" · ".join(parts))
                else:
                    card_sub.setText("Вставь ссылку и нажми «Закрепить»")
            holder = getattr(self, "_pinned_avatar_holder", None)
            if holder is not None:
                holder.removeAllViews()
                avatar = self._chat_avatar_view(ctx, chat, title or username, 48)
                if avatar is not None:
                    holder.addView(avatar, FrameLayout.LayoutParams(
                        AndroidUtilities.dp(48), AndroidUtilities.dp(48), Gravity.CENTER))
            for name in ("_pinned_open_btn", "_pinned_remove_btn"):
                button = getattr(self, name, None)
                if button is not None:
                    button.setAlpha(1.0 if enabled else 0.42)
                    button.setEnabled(enabled)
        except Exception as error:
            self.log("[pinned-channel] card: " + _cause(error))

    def _chat_avatar_view(self, ctx, chat, fallback_title, size_dp):
        """The channel's real avatar, with Telegram's own initials placeholder until it loads."""
        if BackupImageView is None:
            return None
        try:
            view = BackupImageView(ctx)
            try: view.setRoundRadius(AndroidUtilities.dp(size_dp) // 2)
            except Exception: pass
            drawable = None
            if AvatarDrawable is not None:
                try:
                    drawable = AvatarDrawable(chat) if chat is not None else AvatarDrawable()
                except Exception:
                    try: drawable = AvatarDrawable()
                    except Exception: drawable = None
                if drawable is not None and chat is None:
                    try: drawable.setInfo(0, str(fallback_title or "?"), "")
                    except Exception: pass
            if chat is not None:
                try: view.setForUserOrChat(chat, drawable)
                except Exception:
                    try: view.setForUserOrChat(chat)
                    except Exception: pass
            elif drawable is not None:
                try: view.setImageDrawable(drawable)
                except Exception: pass
            return view
        except Exception as error:
            self.log("[pinned-channel] avatar: " + _cause(error))
            return None

    def _open_pinned_channel_link(self):
        state = (self._settings().get("pinned_channel") or {})
        username = str(state.get("username", "") or "").lstrip("@")
        if not username:
            self._toast("Канал не выбран")
            return
        try:
            Browser = jclass("org.telegram.messenger.browser.Browser")
            Browser.openUrl(getattr(self, "_pinned_ctx", None)
                            or ApplicationLoader.applicationContext,
                            "https://t.me/" + username)
        except Exception as error:
            self.log("[pinned-channel] open link: " + _cause(error))
            self._toast("Не удалось открыть канал")

    def _refresh_pinned_channel_sheet(self):
        """Redraw the card in place after a pin or an unpin. The resolve runs asynchronously,
        so this is called from its callback rather than right after the button tap."""
        if getattr(self, "_pinned_sheet", None) is None:
            return
        try:
            run_on_ui_thread(self._update_pinned_channel_card)
        except Exception:
            self._update_pinned_channel_card()

    def _close_pinned_channel_sheet(self):
        sheet = getattr(self, "_pinned_sheet", None)
        if sheet is not None:
            try: sheet.dismiss()
            except Exception: pass

    def _drop_pinned_sheet_refs(self):
        self._pinned_sheet = None
        self._pinned_ctx = None
        self._pinned_subtitle = None
        self._pinned_card_title = None
        self._pinned_card_sub = None
        self._pinned_avatar_holder = None
        self._pinned_open_btn = None
        self._pinned_remove_btn = None
        self._pinned_dismiss = None

    def _set_pinned_channel(self, enabled, channel_id, username, title, participants,
                            message_id, access_hash):
        """Call the bridge, tolerating a core that predates the access_hash argument.

        `_jvoid` resolves the method by its EXACT signature, so the day the 7-argument form was
        introduced any client still running the previous engine.dex got `None` back — and the caller
        read that as success and stored nothing. A host can genuinely have the older core loaded
        (two builds installed side by side, an update that replaced only part of the package), so the
        call falls back to the 6-argument form and simply loses the hash, which
        PinnedChannel then re-learns by resolving the public @username.
        """
        answer = self._jvoid(
            "setPinnedChannel", ("int", "long", "str", "str", "int", "int", "long"),
            (int(enabled), int(channel_id), str(username), str(title), int(participants),
             int(message_id), int(access_hash or 0)))
        if answer is not None:
            return answer
        legacy = self._jvoid(
            "setPinnedChannel", ("int", "long", "str", "str", "int", "int"),
            (int(enabled), int(channel_id), str(username), str(title), int(participants),
             int(message_id)))
        if legacy is not None:
            self.log("[pinned-channel] core has no access_hash argument; pinned without it")
        return legacy

    def _pinned_status(self, text, error=False):
        """Say it INSIDE the sheet.

        A bulletin belongs to the fragment, and this sheet is a dialog window on top of it — so
        every message this flow produced («Канал не найден», «Не удалось закрепить канал», even
        «Канал закреплён») was drawn behind the sheet and its scrim, i.e. nowhere. With nothing
        visible and nothing changing, «Закрепить» read as a dead button. The card's own subtitle is
        the one line the user is already looking at; `_update_pinned_channel_card` rewrites it on the
        next refresh, so a failure message stays up exactly as long as the failure does.
        """
        self._toast(text)
        view = getattr(self, "_pinned_card_sub", None)
        if view is None:
            return
        try:
            colors = (self._theme_color("key_text_RedRegular", 0xFFEC5F5F) if error
                      else self._theme_color("key_windowBackgroundWhiteGrayText", 0xFF9AA3AE))
            def _paint():
                try:
                    view.setText(str(text))
                    view.setTextColor(colors)
                except Exception:
                    pass
            if run_on_ui_thread is not None:
                run_on_ui_thread(_paint)
            else:
                _paint()
        except Exception:
            pass

    _PIN_POLL_MS = 400
    _PIN_POLL_LIMIT = 40          # 400 ms × 40 = 16 s, one second past the core's own patience

    def _pin_channel_through_core(self, username):
        """Ask the core to resolve + pin, then poll it. False when this core cannot (older build)."""
        started = self._jvoid("pinChannelByUsername", ("str",), (str(username),))
        if started is None:
            return False
        self._pin_pending_text = ""
        self._pinned_status("Проверяю @" + username + "…")

        def poll(left=self._PIN_POLL_LIMIT):
            raw = self._jvoid("pollPinChannel")
            state = str(raw or "")
            head, _, rest = state.partition("|")
            if head == "ok":
                title, _, count = rest.partition("|")
                self._hap_result(True)
                self._pinned_status("Канал закреплён: " + (title.strip() or ("@" + username)))
                self._refresh_pinned_channel_sheet()
                return
            if head == "fail":
                self._hap("error")
                self._pinned_status("Не удалось закрепить: " + (rest.strip() or "неизвестная ошибка"),
                                    error=True)
                return
            if left <= 0:
                self._hap("error")
                self._pinned_status("Telegram не ответил на проверку ссылки. Попробуй ещё раз",
                                    error=True)
                return
            # Only when the core's own wording changes — a repaint per poll would strobe the card.
            pending = rest.strip()
            if pending and pending != getattr(self, "_pin_pending_text", ""):
                self._pin_pending_text = pending
                self._pinned_status(pending + "…")
            if run_on_ui_thread is not None:
                run_on_ui_thread(lambda: poll(left - 1), self._PIN_POLL_MS)

        poll()
        return True

    def _save_pinned_channel_link(self, raw_link):
        username, reason = self._parse_channel_link(raw_link)
        if username == "":
            ok, result = self._bridge_ok(
                self._set_pinned_channel(0, 0, "", "", 0, 0, 0))
            self._hap("dismiss" if ok else "error")
            self._pinned_status("Закреплённый канал убран" if ok
                                else ("Не удалось убрать канал: " + (result or "ядро не ответило")),
                                error=not ok)
            self._refresh_pinned_channel_sheet()
            return
        if username is None:
            # Name WHICH kind of link was refused. «Нужна публичная ссылка» in answer to an invite
            # link reads as "the plugin is broken", not as "that link cannot work".
            self._hap("error")
            self._pinned_status(reason or self._LINK_GENERIC, error=True)
            return
        # Preferred path: the CORE resolves and pins. A Chaquopy dynamic_proxy(RequestDelegate) is
        # not reliable on every host — on the device that reported «не нажимается кнопка» the
        # resolve callback never arrived at all — while the core's own java.lang.Proxy delegates are
        # what every working gift RPC already uses. Python only starts it and polls.
        if self._pin_channel_through_core(username):
            return
        if dynamic_proxy is None or jclass is None:
            self._hap("error")
            self._pinned_status("Этот клиент не даёт проверить ссылку", error=True)
            return
        # Guarded here for the same reason _fetch_pinned_channel_message guards them: on a client
        # without the network API the resolve cannot even start, and the generic handler below would
        # blame the link instead of saying so.
        if RequestDelegate is None or get_connections_manager is None:
            self._hap("error")
            self._pinned_status("Этот клиент не даёт отправить запрос", error=True)
            return
        self._pinned_status("Проверяю @" + username + "…")
        # This host's RequestDelegate sometimes NEVER fires — no response and no error (the same
        # defect that used to hang the gift constructor on «загружаю атрибуты…», see
        # _fetch_upgrade_attrs). Without a deadline the pin flow simply stopped there: no message,
        # no change, i.e. a button that "does not press". One-shot + timeout, same remedy.
        answered = {"done": False}

        def _pinned_resolve_timeout():
            if answered["done"]:
                return
            answered["done"] = True
            self._pinned_channel_callback = None
            self._hap("error")
            self._pinned_status("Telegram не ответил на проверку ссылки. Попробуй ещё раз",
                                error=True)

        try:
            request = jclass("org.telegram.tgnet.TLRPC$TL_contacts_resolveUsername")()
            request.username = username
            try:
                request.flags = 0
            except Exception:
                pass
            plugin = self

            class _ResolvedChannel(dynamic_proxy(RequestDelegate)):
                def run(self, result, error):
                    def finish():
                        if answered["done"]:
                            return
                        answered["done"] = True
                        try:
                            if error is not None or result is None:
                                plugin._hap("error")
                                reason = ""
                                try:
                                    reason = str(getattr(error, "text", "") or "")
                                except Exception:
                                    reason = ""
                                plugin._pinned_status(
                                    "Канал не найден или недоступен" + (": " + reason if reason else ""),
                                    error=True)
                                return
                            chats = getattr(result, "chats", None)
                            if chats is None or int(chats.size()) <= 0:
                                plugin._hap("error")
                                plugin._pinned_status("Канал не найден", error=True)
                                return
                            chat = None
                            for index in range(int(chats.size())):
                                candidate = chats.get(index)
                                if bool(getattr(candidate, "broadcast", False)):
                                    chat = candidate
                                    break
                            if chat is None:
                                plugin._hap("error")
                                plugin._pinned_status("Ссылка должна вести на канал", error=True)
                                return
                            channel_id = int(getattr(chat, "id", 0) or 0)
                            title = str(getattr(chat, "title", "") or "")
                            resolved_username = str(getattr(chat, "username", "") or username).lstrip("@")
                            participants = int(getattr(chat, "participants_count", 0) or 0)
                            access_hash = int(getattr(chat, "access_hash", 0) or 0)
                            try:
                                MessagesController = jclass("org.telegram.messenger.MessagesController")
                                controller = MessagesController.getInstance(_selected_account())
                                controller.putChats(chats, False)
                            except Exception:
                                pass
                            plugin._fetch_pinned_channel_full(
                                channel_id, access_hash, resolved_username, title, participants)
                        except Exception as callback_error:
                            plugin.log("[pinned-channel] callback: " + _cause(callback_error))
                            plugin._hap("error")
                            plugin._pinned_status("Не удалось проверить канал: "
                                                  + _cause(callback_error)[:80], error=True)
                        finally:
                            plugin._pinned_channel_callback = None
                    run_on_ui_thread(finish)

            callback = _ResolvedChannel()
            self._pinned_channel_callback = callback
            get_connections_manager().sendRequest(request, callback)
            if run_on_ui_thread is not None:
                run_on_ui_thread(_pinned_resolve_timeout, 12000)
        except Exception as e:
            answered["done"] = True
            self._pinned_channel_callback = None
            self.log("[pinned-channel] resolve: " + _cause(e))
            self._pinned_status("Не удалось отправить запрос: " + _cause(e)[:80], error=True)

    def _fetch_pinned_channel_full(self, channel_id, access_hash, username, title, participants):
        """Ask for the subscriber count before pinning.

        contacts.resolveUsername does NOT fill participants_count — it is only published on the
        full channel — so pinning straight from the resolve stored a zero, and both our card and
        Telegram's own ProfileChannelCell (which reads chat.participants_count) drew no subscriber
        line for anyone, including other plugin users who get the count through sync.
        """
        # Same one-shot + deadline as the resolve: the subscriber count is a NICE-TO-HAVE, and a
        # callback that never fires must not cost the user the pin itself.
        moved = {"done": False}

        def then(count=participants):
            if moved["done"]:
                return
            moved["done"] = True
            self._fetch_pinned_channel_message(
                channel_id, access_hash, username, title, max(int(count or 0), int(participants or 0)))

        if (RequestDelegate is None or get_connections_manager is None or jclass is None
                or dynamic_proxy is None or not access_hash):
            then()
            return
        try:
            req = jclass("org.telegram.tgnet.TLRPC$TL_channels_getFullChannel")()
            peer = jclass("org.telegram.tgnet.TLRPC$TL_inputChannel")()
            peer.channel_id = int(channel_id)
            peer.access_hash = int(access_hash)
            req.channel = peer
            plugin = self

            class _FullChannel(dynamic_proxy(RequestDelegate)):
                def run(self, response, error):
                    count = 0
                    try:
                        full = getattr(response, "full_chat", None) if response is not None else None
                        count = int(getattr(full, "participants_count", 0) or 0)
                        chats = getattr(response, "chats", None) if response is not None else None
                        if chats is not None:
                            MessagesController = jclass("org.telegram.messenger.MessagesController")
                            MessagesController.getInstance(_selected_account()).putChats(chats, False)
                    except Exception:
                        count = 0
                    run_on_ui_thread(lambda: then(count))
                    plugin._pinned_channel_full_callback = None

            callback = _FullChannel()
            self._pinned_channel_full_callback = callback
            get_connections_manager().sendRequest(req, callback)
            if run_on_ui_thread is not None:
                run_on_ui_thread(lambda: then(), 6000)
        except Exception as e:
            self._pinned_channel_full_callback = None
            self.log("[pinned-channel] full channel: " + _cause(e))
            then()

    def _fetch_pinned_channel_message(self, channel_id, access_hash, username, title, participants):
        """Resolve the latest post id required by Telegram's native ProfileChannelCell."""
        committed = {"done": False}

        def commit(message_id=0):
            # The LAST step, so it is the one that must not be skippable: whichever of the callback,
            # the deadline or the error path gets here first performs the write, and the others
            # return. The message id is only the row's post preview — the pin does not depend on it.
            if committed["done"]:
                return
            committed["done"] = True
            # access_hash travels with the pin: PinnedChannel needs it to seed Telegram's chat cache
            # on a cold start, or the row's own RPCs answer CHANNEL_INVALID.
            written, value = self._bridge_ok(self._set_pinned_channel(
                1, int(channel_id), str(username), str(title), int(participants),
                max(0, int(message_id or 0)), int(access_hash or 0)))
            ok = written and int(channel_id) > 0
            self._hap_result(ok)
            if ok:
                self._pinned_status("Канал закреплён в профиле")
            else:
                # Name what the core said. A silent «не удалось» here is indistinguishable from a
                # button that never fired, and that is exactly how this was reported.
                self._pinned_status("Не удалось закрепить канал: "
                                    + (value or "ядро не ответило"), error=True)
            self._refresh_pinned_channel_sheet()

        if RequestDelegate is None or get_connections_manager is None or jclass is None:
            commit(0)
            return
        try:
            req = jclass("org.telegram.tgnet.TLRPC$TL_messages_getHistory")()
            peer = jclass("org.telegram.tgnet.TLRPC$TL_inputPeerChannel")()
            peer.channel_id = int(channel_id)
            peer.access_hash = int(access_hash)
            req.peer = peer
            req.offset_id = 0
            req.offset_date = 0
            req.add_offset = 0
            req.limit = 1
            req.max_id = 0
            req.min_id = 0
            req.hash = 0
            plugin = self

            class _LatestPost(dynamic_proxy(RequestDelegate)):
                def run(self, response, error):
                    message_id = 0
                    try:
                        messages = getattr(response, "messages", None) if response is not None else None
                        if messages is not None and int(messages.size()) > 0:
                            message_id = int(getattr(messages.get(0), "id", 0) or 0)
                        chats = getattr(response, "chats", None) if response is not None else None
                        if chats is not None:
                            MessagesController = jclass("org.telegram.messenger.MessagesController")
                            MessagesController.getInstance(_selected_account()).putChats(chats, False)
                    except Exception:
                        message_id = 0
                    run_on_ui_thread(lambda: commit(message_id))
                    plugin._pinned_channel_history_callback = None

            callback = _LatestPost()
            self._pinned_channel_history_callback = callback
            get_connections_manager().sendRequest(req, callback)
            if run_on_ui_thread is not None:
                run_on_ui_thread(lambda: commit(0), 6000)
        except Exception as e:
            self._pinned_channel_history_callback = None
            self.log("[pinned-channel] latest post: " + _cause(e))
            commit(0)

    def _sub_username(self, parent_view=None):
        st = self._sync_settings_switches()
        toks = st.get("username_tokens") or []
        items = [
            self._menu_header(S("username_header")),
            Switch(key="chimeranft_username_enabled", text=S("show_toggle"),
                   subtext=(self._uname_status(st) if st.get("username_enabled") else S("status_disabled")),
                   default=bool(st.get("username_enabled", False)), icon="msg_edit",
                   on_change=self._toggled(lambda v: self._set_username(v, toks))),
            Text(text=S("add"), subtext=S("username_add_sub"), icon="msg_edit",
                 on_click=self._tapped("select",
                                       lambda: self._input(S("username_input_title"), "", self._add_username))),
            Text(text=S("saved"), subtext=(", ".join("@" + t for t in toks) or S("saved_empty")),
                 icon="msg_emoji_gem"),
        ]
        if toks:
            # Destructive and unconfirmed: «хруст» is the one texture nobody mistakes for a tap.
            items.append(Text(text=S("clear_all"), subtext=S("username_clear_sub"),
                              icon="msg_delete", red=True,
                              on_click=self._tapped("crunch", lambda: self._set_username(False, []))))
        return items

    def _sub_number(self, parent_view=None):
        st = self._sync_settings_switches()
        toks = st.get("number_tokens") or []
        items = [
            self._menu_header(S("number_header")),
            Switch(key="chimeranft_number_enabled", text=S("show_toggle"),
                   subtext=(self._num_status(st) if st.get("number_enabled") else S("status_disabled")),
                   default=bool(st.get("number_enabled", False)), icon="msg_link",
                   on_change=self._toggled(lambda v: self._set_number(v, toks))),
            Text(text=S("add"), subtext=S("number_add_sub"), icon="msg_link",
                 on_click=self._tapped(
                     "select",
                     lambda: self._input(S("number_input_title"), "", self._add_number))),
            Text(text=S("saved"), subtext=(", ".join("+" + t for t in toks) or S("saved_empty")),
                 icon="msg_emoji_gem"),
        ]
        if toks:
            items.append(Text(text=S("clear_all"), subtext=S("number_clear_sub"),
                              icon="msg_delete", red=True,
                              on_click=self._tapped("crunch", lambda: self._set_number(False, []))))
        return items

    # ---- Данные (экспорт/импорт .profile, совместимо с обычным OpenChimeraNFT) ----
    _PROFILE_EXT = ".profile"
    _PROFILE_SECTIONS = ("nft_gifts", "nft_usernames", "nft_number", "local_rating")

    def _sub_rating(self, parent_view=None):
        st = self._sync_settings_switches()
        lvl = max(1, min(100, int(st.get("rating_level", 1) or 1)))
        floor, goal = self._rating_level_bounds(lvl)
        raw = int(st.get("rating_value", 0) or 0)
        val = max(floor, min(raw if raw > 0 else floor, goal - 1))
        enabled = bool(st.get("rating_enabled", False) and raw > 0)
        return [
            self._menu_header(S("rating_header")),
            Switch(
                key="chimeranft_rating_enabled",
                text=S("show_toggle"),
                subtext=(self._rating_label(st) if enabled else S("status_disabled")),
                default=enabled,
                icon="msg_stats_solar",
                on_change=self._toggled(lambda v: self._set_rating(v, val, lvl, goal)),
                link_alias="enabled",
            ),
            Text(
                text=S("rating_configure"),
                subtext=S("rating_configure_sub",
                          lvl,
                          self._format_rating_points(val),
                          self._format_rating_points(floor),
                          self._format_rating_points(goal - 1)),
                icon="msg_stats_solar",
                on_click=self._tapped("select", self._open_rating_slider_dialog),
                link_alias="level_and_points",
            ),
        ]

    # ─────────────────────────────────────────────────────────────────────────────
    # .profile backups
    #
    # A backup is the only way back from a wrong wear, a cleared library or a
    # restored-onto account, so this screen answers three questions the old two
    # rows did not: what is inside a file, when was it written, and what exactly
    # will change if it is applied. Everything below the model helpers is UI; the
    # model helpers are pure so the suite can hold them still.
    # ─────────────────────────────────────────────────────────────────────────────

    #: Highest payload version this build knows how to read.
    _PROFILE_FORMAT = 1

    @staticmethod
    def _fmt_size(size):
        """Bytes → a short human size. Pure: the suite pins the rounding."""
        try:
            value = float(size or 0)
        except Exception:
            return S("size_b", 0)
        if value < 1024:
            return S("size_b", int(value))
        if value < 1024 * 1024:
            return S("size_kb", ("%.1f" % (value / 1024.0)).replace(".0", ""))
        return S("size_mb", "%.1f" % (value / (1024.0 * 1024.0)))

    @staticmethod
    def _fmt_when(ts, now=None):
        """A timestamp as «сегодня 14:22» / «вчера 14:22» / «12.07 14:22».

        Relative wording only for the two days a person can still remember; older
        files get a date, because "5 дней назад" is not something you can match
        against what you were doing."""
        import datetime
        try:
            stamp = int(ts or 0)
        except Exception:
            return ""
        # No timestamp is not 1 January 1970: an unreadable file must show nothing here
        # rather than a date that looks real.
        if stamp <= 0:
            return ""
        try:
            when = datetime.datetime.fromtimestamp(stamp)
        except Exception:
            return ""
        today = (datetime.datetime.fromtimestamp(int(now)) if now else datetime.datetime.now()).date()
        clock = when.strftime("%H:%M")
        delta = (today - when.date()).days
        if delta <= 0:
            return S("when_today", clock)
        if delta == 1:
            return S("when_yesterday", clock)
        if when.year == today.year:
            return when.strftime("%d.%m") + " " + clock
        return when.strftime("%d.%m.%Y") + " " + clock

    @staticmethod
    def _unique_backup_name(name, existing):
        """«profile» next to an existing «profile» becomes «profile (2)».

        Silently overwriting the file a user is about to restore from is the one
        unrecoverable mistake this screen can make."""
        taken = set(str(n or "").lower() for n in (existing or ()))
        base = str(name or "").strip()
        if base.lower() not in taken:
            return base
        index = 2
        while ("%s (%d)" % (base, index)).lower() in taken and index < 999:
            index += 1
        return "%s (%d)" % (base, index)

    def _section_title(self, key):
        return S({"nft_gifts": "section_gifts", "nft_usernames": "section_usernames",
                  "nft_number": "section_number", "local_rating": "section_rating"}.get(str(key), str(key)))

    def _section_hint(self, key):
        return S({"nft_gifts": "section_gifts_sub", "nft_usernames": "section_usernames_sub",
                  "nft_number": "section_number_sub", "local_rating": "section_rating_sub"}.get(str(key), ""))

    def _section_summary(self, key, sections):
        """One line describing what a section actually holds — «12 подарков», «@xarmaq»,
        «ур. 42 · 1 200». This is what turns a file name into a decision."""
        try:
            body = (sections or {}).get(str(key)) or {}
            if not isinstance(body, dict):
                return S("summary_empty")
            if key == "nft_gifts":
                library = body.get("gift_library") or []
                count = len(library) if isinstance(library, (list, tuple)) else 0
                if not count:
                    return S("summary_empty")
                parts = [S("count_gifts", count)]
                if body.get("wear_active"):
                    parts.append(S("summary_wear"))
                if body.get("local_premium_enabled"):
                    parts.append("Premium")
                return " · ".join(parts)
            if key in ("nft_usernames", "nft_number"):
                tokens = body.get("tokens") or []
                tokens = [str(t) for t in tokens if str(t or "").strip()]
                if not tokens:
                    return S("summary_empty")
                mark = "@" if key == "nft_usernames" else "+"
                head = mark + tokens[0]
                if len(tokens) > 1:
                    head += " " + S("summary_more", len(tokens) - 1)
                if not body.get("enabled", False):
                    head += " · " + S("status_off_short")
                return head
            if key == "local_rating":
                value = int(body.get("value", 0) or 0)
                if value <= 0:
                    return S("summary_empty")
                return S("rating_status", int(body.get("level", 1) or 1), value)
        except Exception:
            pass
        return S("summary_empty")

    def _present_sections(self, sections):
        """The supported sections a payload actually carries, in menu order."""
        if not isinstance(sections, dict):
            return []
        return [key for key in self._PROFILE_SECTIONS if isinstance(sections.get(key), dict)]

    def _parse_profile(self, raw):
        """(payload, error_key). Every failure gets its OWN reason: «не наш файл» and
        «файл побился» call for different actions from the user."""
        text = str(raw or "").strip()
        if not text:
            return None, "profile_err_empty"
        lines = [ln for ln in text.split("\n") if ln.strip() and not ln.lstrip().startswith("#")]
        if not lines:
            return None, "profile_err_no_payload"
        try:
            decoded = base64.b64decode("".join(ln.strip() for ln in lines)).decode("utf-8")
        except Exception:
            return None, "profile_err_bad_payload"
        try:
            data = json.loads(decoded)
        except Exception:
            return None, "profile_err_bad_payload"
        if not isinstance(data, dict):
            return None, "profile_err_bad_payload"
        if str(data.get("plugin_id", _HOST_PLUGIN_ID)) not in _KNOWN_PLUGIN_IDS:
            return None, "profile_err_not_ours"
        try:
            version = int(data.get("version", 1) or 1)
        except Exception:
            version = 1
        if version > self._PROFILE_FORMAT:
            return None, "profile_err_too_new"
        if not self._present_sections(data.get("sections")):
            return None, "profile_err_no_sections"
        return data, None

    def _current_sections(self):
        """The core's own view of the profile. Marshals the whole gift library across JNI,
        so callers must be off the UI thread."""
        try:
            raw = self._jvoid("exportProfile")
            return json.loads(str(raw)) if raw else {}
        except Exception:
            return {}

    def _restore_changes(self, incoming, keys, current=None):
        """[(section title, current summary, incoming summary)] for the sections that would
        actually change. Restoring replaces rather than merges, so this is the honest
        preview: what you have now on the left, what you would have on the right."""
        if current is None:
            current = self._current_sections()
        rows = []
        for key in keys:
            before = self._section_summary(key, current)
            after = self._section_summary(key, incoming)
            if before != after:
                rows.append((self._section_title(key), before, after))
        return rows

    # ---- the folder and its index ----

    def _profile_dir(self):
        """Downloads/<_PROFILE_DIR_NAME>, the folder new .profile files are WRITTEN to;
        cache dir fallback. Use _profile_dirs() to read — backups made before the rename
        live in the old folder.

        Cached: this also CREATES the folder, and the settings list asks for the path while
        it builds rows — a mkdir per row build is filesystem work on the UI thread."""
        cached = getattr(self, "_profile_dir_cached", None)
        if cached:
            return cached
        resolved = self._resolve_profile_dir()
        if resolved:
            self._profile_dir_cached = resolved
        return resolved

    def _profile_dirs(self):
        """Every folder a .profile may be READ from: the current one first, then the
        pre-rename names. A backup taken before the OpenChimeraNFT rename sits in
        Downloads/eblanNFT, and that folder is shared with the legacy standalone plugin —
        so it is scanned, and its files stay restorable and deletable, but nothing new is
        ever written into it."""
        import os
        dirs = []
        primary = self._profile_dir()
        if primary:
            dirs.append(primary)
        try:
            Environment = jclass("android.os.Environment")
            downloads = Environment.getExternalStoragePublicDirectory(
                Environment.DIRECTORY_DOWNLOADS).getAbsolutePath()
            for legacy in _LEGACY_PROFILE_DIR_NAMES:
                candidate = os.path.join(downloads, legacy)
                if candidate not in dirs and os.path.isdir(candidate):
                    dirs.append(candidate)
        except Exception:
            pass
        return dirs

    def _resolve_profile_dir(self):
        try:
            import os
            Environment = jclass("android.os.Environment")
            downloads = Environment.getExternalStoragePublicDirectory(
                Environment.DIRECTORY_DOWNLOADS).getAbsolutePath()
            target = os.path.join(downloads, _PROFILE_DIR_NAME)
            if ensure_dir_exists is not None:
                ensure_dir_exists(target)
            else:
                os.makedirs(target, exist_ok=True)
            return target
        except Exception as e:
            try:
                import os
                target = os.path.join(_resolve_data_dir() or get_plugins_dir(), "profiles")
                os.makedirs(target, exist_ok=True)
                return target
            except Exception:
                self.log("[profile] dir: " + _cause(e))
                return None

    def _sanitize_profile_name(self, raw):
        import re, time as _t
        name = str(raw or "").strip()
        if name.lower().endswith(self._PROFILE_EXT):
            name = name[:-len(self._PROFILE_EXT)]
        name = re.sub(r'[\\/:*?"<>|]+', "_", name)
        name = re.sub(r"\s+", " ", name).strip(" .")
        if not name:
            name = "profile_" + str(int(_t.time()))
        return name[:64]

    def _scan_backups(self):
        """Read the folder and every file's header. Off the UI thread only: this is
        N file reads plus N base64+JSON decodes."""
        import os
        entries = []
        if read_file is None:
            self.log("[backup] scan: file_utils unavailable")
            return entries
        # Folders in priority order, so a file that exists in both the current and the
        # pre-rename folder is listed once, from the current one.
        found = []
        claimed = set()
        for folder in self._profile_dirs():
            if not folder or not os.path.isdir(folder):
                continue
            try:
                names = [n for n in os.listdir(folder)
                         if str(n).lower().endswith(self._PROFILE_EXT)]
            except Exception as e:
                self.log("[backup] scan: " + _cause(e))
                continue
            for name in names:
                key = str(name).lower()
                if key in claimed:
                    continue
                claimed.add(key)
                found.append((name, os.path.join(folder, name)))
        for name, path in found:
            entry = {"name": name, "path": path, "size": 0, "mtime": 0,
                     "data": None, "error": None, "sections": {}, "present": []}
            try:
                entry["size"] = int(os.path.getsize(path))
                entry["mtime"] = int(os.path.getmtime(path))
            except Exception:
                pass
            try:
                raw = read_file(path) if read_file is not None else None
            except Exception:
                raw = None
            data, error = self._parse_profile(raw)
            entry["data"] = data
            entry["error"] = error
            if data:
                entry["sections"] = data.get("sections") or {}
                entry["present"] = self._present_sections(entry["sections"])
                try:
                    entry["mtime"] = int(data.get("timestamp", entry["mtime"]) or entry["mtime"])
                except Exception:
                    pass
                entry["built_by"] = str(data.get("plugin_version", "") or "")
            entries.append(entry)
        # newest first: the file you want is almost always the last one written
        entries.sort(key=lambda e: (int(e.get("mtime", 0) or 0), str(e.get("name", ""))), reverse=True)
        return entries

    def _backup_index(self, refresh=False):
        """Cached index for the settings rows. Never blocks the list build: a cold cache
        returns None and the scan finishes on a worker, then asks the host to rebuild."""
        import time as _t
        cached = getattr(self, "_backup_index_cache", None)
        if cached is not None and not refresh and _t.time() - cached[0] < 12.0:
            return cached[1]
        if getattr(self, "_backup_index_scanning", False):
            return cached[1] if cached else None
        self._backup_index_scanning = True

        def _work():
            try:
                entries = self._scan_backups()
                self._backup_index_cache = (_t.time(), entries)
            except Exception as e:
                self.log("[backup] index: " + _cause(e))
                self._backup_index_cache = (_t.time(), [])
            finally:
                self._backup_index_scanning = False
            try:
                self._schedule_settings_refresh()
            except Exception:
                pass

        try:
            import threading
            threading.Thread(target=_work, daemon=True).start()
        except Exception:
            _work()
        return cached[1] if cached else None

    def _backups_subtext(self):
        entries = self._backup_index()
        if entries is None:
            return S("backups_reading")
        if not entries:
            return S("backups_empty")
        broken = len([e for e in entries if e.get("error")])
        label = S("backups_count", len(entries))
        newest = entries[0]
        when = self._fmt_when(newest.get("mtime", 0))
        if when:
            label += " · " + when
        if broken:
            label += " · " + S("backups_broken", broken)
        return label

    def _create_backup_subtext(self, st=None):
        """What a copy made right now would contain — the reason to make one.

        Built from the mirrored settings snapshot the list already has, NOT from
        exportProfile: that bridge call marshals the whole gift library across JNI and this
        runs while the row is being built."""
        s = st or self._settings()
        parts = []
        try:
            gifts = int(s.get("gift_count", 0) or 0)
            if gifts:
                parts.append(S("count_gifts", gifts))
            tokens = s.get("username_tokens") or []
            if tokens:
                parts.append("@" + str(tokens[0]))
            numbers = s.get("number_tokens") or []
            if numbers:
                parts.append("+" + str(numbers[0]))
            value = int(s.get("rating_value", 0) or 0)
            if value > 0:
                parts.append(S("rating_status", int(s.get("rating_level", 1) or 1), value))
        except Exception:
            pass
        return " · ".join(parts) if parts else S("data_create_empty")

    # ---- settings rows ----

    def _sub_data(self, parent_view=None):
        st = self._sync_settings_switches()
        rows = [
            self._menu_header(S("data_header")),
            Text(text=S("data_create"), subtext=self._create_backup_subtext(st),
                 icon="msg_share", on_click=self._tapped("select", self._open_profile_export),
                 link_alias="save"),
            Text(text=S("data_manage"), subtext=self._backups_subtext(),
                 icon="msg_download", on_click=self._tapped("open", self._open_backup_manager),
                 link_alias="restore"),
            # No "?" row here. A row whose entire label is a question mark states nothing about
            # what it does, and the two rows above already say what they hold in their subtext —
            # which is the rule for this screen: normal rows show live values, not explanations.
            self._menu_header(S("data_auto_header")),
            Text(text=S("data_auto"), subtext=self._auto_backup_state(st),
                 icon="msg_retry", on_click=self._tapped("select", self._show_auto_backup_info),
                 link_alias="auto"),
            # Last, and under its own header: «начать заново». It sits on this screen because a
            # copy is the only way back from it, and the two rows that make one are right above.
            self._menu_header(S("data_reset_header")),
            Text(text=S("data_reset"), subtext=self._reset_subtext(st),
                 icon="msg_delete", on_click=self._tapped("select", self._confirm_reset_local_profile),
                 link_alias="reset"),
        ]
        folder = self._profile_dir()
        if folder:
            rows.append(Divider(text=S("data_folder_hint", str(folder))))
        return rows

    def _auto_backup_state(self, st=None):
        s = st or self._settings()
        try:
            count = int(s.get("auto_backup_count", 0) or 0)
            ts = int(s.get("auto_backup_time", 0) or 0)
        except Exception:
            count, ts = 0, 0
        if count <= 0:
            return S("data_auto_none")
        when = self._fmt_when(ts) if ts > 0 else ""
        return S("data_auto_count", count) + ((" · " + when) if when else "")

    def _show_auto_backup_info(self):
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._toast(S("data_auto_body"))
                return
            builder = AlertDialogBuilder(ctx)
            builder.set_title(S("data_auto"))
            builder.set_message(S("data_auto_body") + "\n\n" + self._auto_backup_state())
            builder.set_positive_button(S("got_it"), None)
            run_on_ui_thread(builder.show)
        except Exception:
            self._toast(S("data_auto_body"))

    # ---- full reset ----

    def _reset_subtext(self, st=None):
        """What the reset would take away.

        Deliberately the same reading as «Создать копию»: the two rows are each other's undo,
        and a reset with nothing to lose should say that instead of promising an action."""
        summary = self._create_backup_subtext(st)
        return S("data_reset_empty") if summary == S("data_create_empty") else summary

    def _confirm_reset_local_profile(self):
        """Two taps, and the message names every section that goes — including the server copy,
        which is the part nobody expects a local button to touch."""
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._toast(S("no_context"))
                return
            builder = AlertDialogBuilder(ctx)
            builder.set_title(S("data_reset_confirm_title"))
            builder.set_message(S("data_reset_confirm"))
            builder.set_positive_button(S("data_reset_action"),
                                        lambda d, w: self._reset_local_profile())
            builder.set_negative_button(S("cancel"), None)
            run_on_ui_thread(builder.show)
        except Exception as e:
            self.log("[reset] confirm: " + _cause(e))
            self._toast(S("data_reset_failed"))

    def _reset_local_profile(self):
        """Hand the whole wipe to the core — it owns the cache file, the recovery generations
        and the server record (§6.1/§6.2), so a Python-side delete would be undone by the next
        write and by the next cold start's recovery vote.

        The runtime's in-memory copy is cleared too. It still holds the wear/template/config
        slice it is allowed to persist, and the single-writer guard merges that slice back on
        its next save — which would quietly restore part of what was just deleted."""
        raw = self._jvoid("resetLocalProfile")
        ok, text = self._bridge_ok(raw)
        if not ok:
            self.log("[reset] core: " + str(text))
            self._toast(S("data_reset_failed"))
            return
        self._reset_runtime_state()
        self._gifts_cache = None
        self._upg_match_cache = {}
        self._backup_index_cache = None
        self._hap("crunch", essential=True)
        self._toast(S("data_reset_done"))
        self._schedule_settings_refresh()

    # Fields of the UI runtime that hold a copy of the profile. Only the ones the
    # single-writer guard is allowed to persist (_PROD_OWNED_KEYS) can resurrect data, but the
    # rest still feed its own screens, so the whole in-memory profile goes at once.
    _RUNTIME_RESET_FIELDS = (
        ("build_config", None), ("identity_config", None), ("value_config", None),
        ("gift_stars_config", None), ("stolen_gift_inner", None), ("stolen_gift", None),
        ("wear_active", False), ("wear_collectible_id", 0), ("wear_status_data", None),
        ("inject_active", False), ("gift_library", []), ("regular_gifts", []),
        ("_regular_gifts_seq", 0), ("cached_gift_id", 0),
        ("nft_collectible_template_b64", ""), ("nft_number_collectible_template_b64", ""),
        ("nft_username_enabled", False), ("nft_username", ""), ("nft_usernames", []),
        ("nft_number_enabled", False), ("nft_number", ""), ("nft_numbers", []),
        ("local_rating_enabled", False), ("local_stars_balance_enabled", False),
        ("hide_official_gifts_local", False),
    )

    def _reset_runtime_state(self):
        prod = getattr(self, "_prod", None)
        if prod is None:
            return
        for name, value in self._RUNTIME_RESET_FIELDS:
            try:
                if not hasattr(prod, name):
                    continue
                setattr(prod, name, [] if isinstance(value, list) else value)
            except Exception:
                pass
        # A queued snapshot is the same stale copy by another route.
        for name in ("_cache_pending", "_cache_save_future"):
            try:
                if hasattr(prod, name):
                    setattr(prod, name, None)
            except Exception:
                pass
        try:
            prod._library_dirty = False
        except Exception:
            pass

    # ---- shared section picker (create + restore) ----

    def _profile_section_picker(self, title, subtitle, action_label, available, sections, on_apply,
                                extra_builder=None):
        """Multi-toggle sheet over the sections of a payload. Every row states what it
        holds, so «Импортировать» stops being a blind action. on_apply(selected_keys)."""
        avail = [k for k in available]
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or BottomSheet is None:
                on_apply(avail)
                return
            TextCheckCell = jclass("org.telegram.ui.Cells.TextCheckCell")
            sheet = BottomSheet(ctx, False)

            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(18),
                            AndroidUtilities.dp(20), AndroidUtilities.dp(14))
            root.addView(self._sheet_title(ctx, title), LinearLayout.LayoutParams(-1, -2))
            if subtitle:
                lp_sub = LinearLayout.LayoutParams(-1, -2)
                lp_sub.topMargin = AndroidUtilities.dp(6)
                root.addView(self._sheet_subtitle(ctx, subtitle), lp_sub)

            body = LinearLayout(ctx)
            body.setOrientation(LinearLayout.VERTICAL)
            if extra_builder is not None:
                try:
                    extra = extra_builder(ctx)
                    if extra is not None:
                        lp_extra = LinearLayout.LayoutParams(-1, -2)
                        lp_extra.topMargin = AndroidUtilities.dp(14)
                        body.addView(extra, lp_extra)
                except Exception as e:
                    self.log("[backup] picker extra: " + _cause(e))

            selected = {k: True for k in avail}
            cells = LinearLayout(ctx)
            cells.setOrientation(LinearLayout.VERTICAL)
            for index, key in enumerate(avail):
                cell = TextCheckCell(ctx, 21, True)
                summary = self._section_summary(key, sections)
                value = summary if summary != S("summary_empty") else self._section_hint(key)
                cell.setTextAndValueAndCheck(self._section_title(key), value, True,
                                             True, index != len(avail) - 1)

                def _toggle(_v, _cell=cell, _key=key):
                    state = not bool(selected.get(_key, False))
                    selected[_key] = state
                    self._hap_toggle(state)
                    try: _cell.setChecked(state)
                    except Exception: pass
                cell.setOnClickListener(self._click(_toggle, hap=None))
                cells.addView(cell)
            lp_cells = LinearLayout.LayoutParams(-1, -2)
            lp_cells.topMargin = AndroidUtilities.dp(10)
            body.addView(cells, lp_cells)

            scroll = ScrollView(ctx)
            scroll.addView(body, FrameLayout.LayoutParams(-1, -2))
            lp_scroll = LinearLayout.LayoutParams(-1, -2)
            lp_scroll.topMargin = AndroidUtilities.dp(6)
            root.addView(scroll, lp_scroll)

            def _go(_v):
                keys = [k for k in avail if bool(selected.get(k, False))]
                if not keys:
                    self._hap("error")
                    self._toast(S("restore_pick_one"))
                    return
                self._hap("impact")
                try: sheet.dismiss()
                except Exception: pass
                on_apply(keys)

            lp_buttons = LinearLayout.LayoutParams(-1, -2)
            lp_buttons.topMargin = AndroidUtilities.dp(16)
            root.addView(self._sheet_buttons(ctx, sheet, action_label, _go), lp_buttons)

            self._backup_picker_sheet = sheet
            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)
        except Exception as e:
            self.log("[backup] picker: " + _cause(e))
            on_apply(avail)

    # ---- small sheet building blocks (one look for every backup surface) ----

    def _sheet_title(self, ctx, text):
        view = TextView(ctx)
        view.setText(str(text))
        view.setTextColor(int(self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)))
        view.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
        try: view.setTypeface(AndroidUtilities.bold())
        except Exception: pass
        return view

    def _sheet_subtitle(self, ctx, text):
        view = TextView(ctx)
        view.setText(str(text))
        view.setTextColor(int(self._theme_color("key_windowBackgroundWhiteGrayText2", 0xFF9AA3AE)))
        view.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        return view

    def _sheet_buttons(self, ctx, sheet, action_label, on_action, action_red=False):
        """«Отмена» + one filled action, the pair every sheet on this screen ends with."""
        accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))
        if action_red:
            accent = int(self._theme_color("key_text_RedBold", 0xFFE04B4B))
        row = LinearLayout(ctx)
        row.setOrientation(LinearLayout.HORIZONTAL)

        cancel = TextView(ctx)
        cancel.setText(S("cancel"))
        cancel.setGravity(Gravity.CENTER)
        cancel.setTextColor(int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC)))
        try: cancel.setTypeface(AndroidUtilities.bold())
        except Exception: pass
        cancel.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14),
                          AndroidUtilities.dp(8), AndroidUtilities.dp(14))
        cancel.setOnClickListener(self._click(lambda _v: sheet.dismiss(), hap="dismiss"))

        action = TextView(ctx)
        action.setText(str(action_label))
        action.setGravity(Gravity.CENTER)
        action.setTextColor(self._ink_on(accent))
        try: action.setTypeface(AndroidUtilities.bold())
        except Exception: pass
        try:
            action.setBackground(self._ripple_bg(self._create_round_rect(accent, 12), accent))
            action.setElevation(float(AndroidUtilities.dp(2)))
        except Exception:
            pass
        action.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14),
                          AndroidUtilities.dp(8), AndroidUtilities.dp(14))
        action.setOnClickListener(self._click(on_action, hap=None))

        row.addView(cancel, LinearLayout.LayoutParams(0, -2, 1.0))
        lp_action = LinearLayout.LayoutParams(0, -2, 1.0)
        lp_action.leftMargin = AndroidUtilities.dp(10)
        row.addView(action, lp_action)
        return row

    # ---- create ----

    def _open_profile_export(self):
        try:
            raw = self._jvoid("exportProfile")
            sections = json.loads(str(raw)) if raw else {}
        except Exception as e:
            self.log("[backup] export read: " + _cause(e))
            sections = {}
        present = self._present_sections(sections) or list(self._PROFILE_SECTIONS)
        self._profile_section_picker(S("create_title"), S("create_subtitle"), S("create_action"),
                                     present, sections, self._export_after_pick)

    def _export_after_pick(self, keys):
        import time as _t
        default = _t.strftime("profile_%Y%m%d_%H%M%S")
        self._input(S("create_name_title"), default,
                    lambda name: self._do_profile_export(name, keys))

    def _do_profile_export(self, raw_name, keys=None):
        import os, time as _t
        if write_file is None:
            self._hap("error")
            self._toast(S("create_no_file_utils"))
            return
        safe = self._sanitize_profile_name(raw_name)
        try:
            sec_raw = self._jvoid("exportProfile")
            sections = json.loads(str(sec_raw)) if sec_raw else {}
            if not isinstance(sections, dict) or not sections:
                self._hap("error")
                self._toast(S("create_nothing"))
                return
            if keys:  # keep only the sections the user selected in the toggle sheet
                want = set(str(k) for k in keys)
                sections = {k: v for k, v in sections.items() if k in want}
                if not sections:
                    self._hap("error")
                    self._toast(S("create_nothing"))
                    return
            cfg_dir = self._profile_dir()
            if not cfg_dir:
                self._hap("error")
                self._toast(S("create_no_dir"))
                return
            # Names taken across EVERY folder we read from, not just the one we write to:
            # a new file sharing its name with one in the pre-rename folder would hide
            # that one from the list (the scan keeps the current folder's copy).
            existing = []
            for folder in self._profile_dirs():
                try:
                    existing.extend(str(n)[:-len(self._PROFILE_EXT)] for n in os.listdir(folder)
                                    if str(n).lower().endswith(self._PROFILE_EXT))
                except Exception:
                    pass
            final = self._unique_backup_name(safe, existing)
            payload = {
                "version": self._PROFILE_FORMAT,
                # Deliberately the PRE-RENAME id. A new plugin id means the host can
                # have both builds installed at once, and an older one only restores a
                # .profile whose plugin_id is "eblannft"/"eblannft_dex". Our own reader
                # accepts every id in _KNOWN_PLUGIN_IDS, so writing the old one costs
                # nothing here and keeps backups restorable on both.
                "plugin_id": "eblannft",
                "plugin_version": __version__,
                "timestamp": int(_t.time()),
                "profile_name": final,
                "sections": sections,
            }
            raw_json = json.dumps(payload, indent=2, ensure_ascii=False)
            raw_b64 = base64.b64encode(raw_json.encode("utf-8")).decode("ascii")
            content = ("# OpenChimeraNFT profile\n"
                       "# " + _t.strftime("%Y-%m-%d %H:%M:%S") + "\n"
                       "# sections: " + ", ".join(sorted(sections.keys())) + "\n\n"
                       + raw_b64)
            filename = final + self._PROFILE_EXT
            filepath = os.path.join(cfg_dir, filename)
            write_file(filepath, content)
            # export = "publish" → push the current state to the VPS now (replaces the
            # old server record), so others immediately see the exported config.
            try:
                self._jvoid("pushSyncNow")
            except Exception:
                pass
            self._backup_index_cache = None
            self._hap("success", essential=True)
            if final != safe:
                self._toast(S("create_conflict_renamed", filename))
            self._show_export_done(filepath, filename, sections)
        except Exception as e:
            self._hap("error")
            self._toast(S("create_failed", repr(e)[:120]))
            try: self.log("[profile] export: " + _cause(e))
            except Exception: pass

    def _show_export_done(self, filepath, filename, sections=None):
        try:
            if AlertDialogBuilder is None or get_last_fragment is None:
                self._toast(S("create_saved", filename))
                return
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None:
                self._toast(S("create_saved", filename))
                return
            lines = [filename]
            if sections:
                for key in self._present_sections(sections):
                    lines.append(self._section_title(key) + ": " + self._section_summary(key, sections))
            lines.append("")
            lines.append(str(filepath))
            builder = AlertDialogBuilder(ctx)
            builder.set_title(S("create_done_title"))
            builder.set_message("\n".join(lines))
            builder.set_positive_button(S("backup_share"),
                                        lambda d, w: self._share_profile_file(filepath, ctx))
            builder.set_negative_button(S("close"), None)
            run_on_ui_thread(builder.show)
        except Exception:
            self._toast(S("create_saved", filename))

    def _share_profile_file(self, filepath, activity):
        try:
            Intent = jclass("android.content.Intent")
            File = jclass("java.io.File")
            FileProvider = jclass("androidx.core.content.FileProvider")
            file_obj = File(filepath)
            uri = FileProvider.getUriForFile(
                activity, ApplicationLoader.getApplicationId() + ".provider", file_obj)
            intent = Intent(Intent.ACTION_SEND)
            intent.setType("application/octet-stream")
            intent.putExtra(Intent.EXTRA_STREAM, uri)
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            activity.startActivity(Intent.createChooser(intent, S("backup_share")))
        except Exception as e:
            self._hap("error")
            self._toast(S("share_failed", repr(e)[:100]))
            try: self.log("[profile] share: " + _cause(e))
            except Exception: pass

    # ---- manager ----

    def _open_backup_manager(self):
        """One screen for every copy on disk: what it holds, and what you can do with it."""
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or BottomSheet is None:
                self._toast(S("not_here"))
                return
            sheet = BottomSheet(ctx, False)
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(18),
                            AndroidUtilities.dp(20), AndroidUtilities.dp(14))
            root.addView(self._sheet_title(ctx, S("backups_title")),
                         LinearLayout.LayoutParams(-1, -2))
            folder = self._profile_dir() or ""
            lp_sub = LinearLayout.LayoutParams(-1, -2)
            lp_sub.topMargin = AndroidUtilities.dp(6)
            root.addView(self._sheet_subtitle(ctx, S("backups_subtitle", folder)), lp_sub)

            body = LinearLayout(ctx)
            body.setOrientation(LinearLayout.VERTICAL)
            scroll = ScrollView(ctx)
            scroll.addView(body, FrameLayout.LayoutParams(-1, -2))
            lp_scroll = LinearLayout.LayoutParams(-1, -2)
            lp_scroll.topMargin = AndroidUtilities.dp(12)
            root.addView(scroll, lp_scroll)

            placeholder = self._sheet_subtitle(ctx, S("backups_reading"))
            body.addView(placeholder, LinearLayout.LayoutParams(-1, -2))

            create = TextView(ctx)
            create.setText(S("backups_create"))
            create.setGravity(Gravity.CENTER)
            accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))
            create.setTextColor(self._ink_on(accent))
            try:
                create.setTypeface(AndroidUtilities.bold())
                create.setBackground(self._ripple_bg(self._create_round_rect(accent, 12), accent))
            except Exception:
                pass
            create.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14),
                              AndroidUtilities.dp(8), AndroidUtilities.dp(14))

            def _create(_v):
                try: sheet.dismiss()
                except Exception: pass
                self._open_profile_export()
            create.setOnClickListener(self._click(_create, hap="select"))
            lp_create = LinearLayout.LayoutParams(-1, -2)
            lp_create.topMargin = AndroidUtilities.dp(16)
            root.addView(create, lp_create)

            self._backup_manager_sheet = sheet
            self._backup_manager_body = body
            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)

            def _load():
                entries = self._scan_backups()
                try:
                    import time as _t
                    self._backup_index_cache = (_t.time(), entries)
                except Exception:
                    pass
                run_on_ui_thread(lambda: self._fill_backup_manager(ctx, sheet, body, entries))

            try:
                import threading
                threading.Thread(target=_load, daemon=True).start()
            except Exception:
                _load()
        except Exception as e:
            self.log("[backup] manager: " + _cause(e))
            self._toast(S("backups_failed"))

    def _fill_backup_manager(self, ctx, sheet, body, entries):
        try:
            body.removeAllViews()
            if not entries:
                body.addView(self._sheet_subtitle(ctx, S("backups_empty_hint")),
                             LinearLayout.LayoutParams(-1, -2))
                return
            for index, entry in enumerate(entries):
                row = self._backup_row(ctx, sheet, entry)
                lp = LinearLayout.LayoutParams(-1, -2)
                if index:
                    lp.topMargin = AndroidUtilities.dp(8)
                body.addView(row, lp)
            if self._smooth_mode_enabled():
                self._stagger_children(body, 10, 26, 6)
        except Exception as e:
            self.log("[backup] fill: " + _cause(e))

    def _backup_row(self, ctx, sheet, entry):
        """A card per file: name, when + size, and either what it holds or why it cannot
        be read. Tap opens the actions, long press goes straight to delete."""
        broken = bool(entry.get("error"))
        card = LinearLayout(ctx)
        card.setOrientation(LinearLayout.VERTICAL)
        card.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(12),
                        AndroidUtilities.dp(14), AndroidUtilities.dp(12))
        surface = int(self._theme_color("key_windowBackgroundGray", 0xFF1C1C1E))
        try:
            card.setBackground(self._ripple_bg(self._create_round_rect(surface, 14), surface))
        except Exception:
            pass

        title = TextView(ctx)
        name = str(entry.get("name", ""))
        if name.lower().endswith(self._PROFILE_EXT):
            name = name[:-len(self._PROFILE_EXT)]
        title.setText(name)
        title.setTextColor(int(self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)))
        title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
        try: title.setTypeface(AndroidUtilities.bold())
        except Exception: pass
        card.addView(title, LinearLayout.LayoutParams(-1, -2))

        meta = TextView(ctx)
        bits = [b for b in (self._fmt_when(entry.get("mtime", 0)),
                            self._fmt_size(entry.get("size", 0))) if b]
        built = str(entry.get("built_by", "") or "")
        if built and built != __version__:
            bits.append(S("backup_built_by", built))
        meta.setText(" · ".join(bits))
        meta.setTextColor(int(self._theme_color("key_windowBackgroundWhiteGrayText2", 0xFF9AA3AE)))
        meta.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
        lp_meta = LinearLayout.LayoutParams(-1, -2)
        lp_meta.topMargin = AndroidUtilities.dp(2)
        card.addView(meta, lp_meta)

        detail = TextView(ctx)
        if broken:
            detail.setText(S(str(entry.get("error"))))
            detail.setTextColor(int(self._theme_color("key_text_RedBold", 0xFFE04B4B)))
        else:
            parts = []
            for key in entry.get("present", []):
                summary = self._section_summary(key, entry.get("sections"))
                if summary != S("summary_empty"):
                    parts.append(summary)
                else:
                    parts.append(self._section_title(key))
            detail.setText(" · ".join(parts))
            detail.setTextColor(int(self._theme_color("key_windowBackgroundWhiteGrayText", 0xFFB0B7BF)))
        detail.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        lp_detail = LinearLayout.LayoutParams(-1, -2)
        lp_detail.topMargin = AndroidUtilities.dp(8)
        card.addView(detail, lp_detail)

        card.setOnClickListener(self._click(
            lambda _v: self._open_backup_actions(sheet, entry), hap="select"))
        self._attach_long_press(card, lambda: self._confirm_delete_backup(sheet, entry))
        return card

    def _attach_long_press(self, view, on_long):
        """Long press without swallowing the tap: OnLongClickListener returns True so the
        click listener does not also fire."""
        if view is None or dynamic_proxy is None:
            return
        try:
            plugin = self

            class _Long(dynamic_proxy(View.OnLongClickListener)):
                def onLongClick(self2, _v):
                    try:
                        plugin._hap("long_press", _v)
                        on_long()
                    except Exception as error:
                        plugin.log("[backup] long press: " + _cause(error))
                    return True

            listener = _Long()
            view.setOnLongClickListener(listener)
            refs = getattr(self, "_backup_long_refs", None)
            if refs is None:
                refs = []
                self._backup_long_refs = refs
            refs.append(listener)
        except Exception as e:
            self.log("[backup] long press attach: " + _cause(e))

    def _open_backup_actions(self, manager_sheet, entry):
        """Restore / share / rename / delete for one file."""
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._restore_backup(manager_sheet, entry)
                return
            broken = bool(entry.get("error"))
            actions = []
            if not broken:
                actions.append(("restore", S("backup_restore")))
            actions.append(("share", S("backup_share")))
            actions.append(("rename", S("backup_rename")))
            actions.append(("delete", S("backup_delete")))

            def _pick(dialog, index):
                try: dialog.dismiss()
                except Exception: pass
                if index < 0 or index >= len(actions):
                    self._hap("dismiss")
                    return
                action = actions[index][0]
                if action == "restore":
                    self._restore_backup(manager_sheet, entry)
                elif action == "share":
                    self._share_profile_file(entry.get("path"), ctx)
                elif action == "rename":
                    self._rename_backup(manager_sheet, entry)
                elif action == "delete":
                    self._confirm_delete_backup(manager_sheet, entry)

            builder = AlertDialogBuilder(ctx)
            builder.set_title(str(entry.get("name", "")))
            builder.set_items([label for _key, label in actions], _pick)
            builder.set_negative_button(S("close"), None)
            run_on_ui_thread(builder.show)
        except Exception as e:
            self.log("[backup] actions: " + _cause(e))

    def _rename_backup(self, manager_sheet, entry):
        import os
        current = str(entry.get("name", ""))
        if current.lower().endswith(self._PROFILE_EXT):
            current = current[:-len(self._PROFILE_EXT)]

        def _apply(raw):
            safe = self._sanitize_profile_name(raw)
            folder = os.path.dirname(str(entry.get("path", "")))
            try:
                existing = [str(n)[:-len(self._PROFILE_EXT)] for n in os.listdir(folder)
                            if str(n).lower().endswith(self._PROFILE_EXT)
                            and str(n) != str(entry.get("name", ""))]
            except Exception:
                existing = []
            final = self._unique_backup_name(safe, existing)
            target = os.path.join(folder, final + self._PROFILE_EXT)
            try:
                os.rename(str(entry.get("path", "")), target)
            except Exception as e:
                self._hap("error")
                self._toast(S("backup_rename_failed", repr(e)[:100]))
                return
            self._hap("impact")
            self._toast(S("backup_renamed", final))
            self._refresh_backup_manager(manager_sheet)

        self._input(S("backup_rename_title"), current, _apply)

    def _confirm_delete_backup(self, manager_sheet, entry):
        import os
        name = str(entry.get("name", ""))

        def _delete():
            try:
                os.remove(str(entry.get("path", "")))
            except Exception as e:
                self._hap("error")
                self._toast(S("backup_delete_failed", repr(e)[:100]))
                return
            # Deleting the only way back deserves the one texture nobody mistakes for a tap.
            self._hap("crunch", essential=True)
            self._toast(S("backup_deleted", name))
            self._refresh_backup_manager(manager_sheet)

        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                _delete()
                return
            builder = AlertDialogBuilder(ctx)
            builder.set_title(S("backup_delete_confirm_title"))
            builder.set_message(S("backup_delete_confirm", name))
            builder.set_positive_button(S("backup_delete"), lambda d, w: _delete())
            builder.set_negative_button(S("cancel"), None)
            run_on_ui_thread(builder.show)
        except Exception as e:
            self.log("[backup] delete confirm: " + _cause(e))

    def _refresh_backup_manager(self, manager_sheet):
        """Re-scan and re-fill the open manager in place — no dismiss/reopen flash."""
        self._backup_index_cache = None
        body = getattr(self, "_backup_manager_body", None)
        if manager_sheet is None or body is None:
            self._backup_index()
            return

        def _work():
            entries = self._scan_backups()
            try:
                import time as _t
                self._backup_index_cache = (_t.time(), entries)
            except Exception:
                pass
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None:
                return
            run_on_ui_thread(lambda: self._fill_backup_manager(ctx, manager_sheet, body, entries))

        try:
            import threading
            threading.Thread(target=_work, daemon=True).start()
        except Exception:
            _work()

    # ---- restore ----

    def _restore_backup(self, manager_sheet, entry):
        sections = entry.get("sections") or {}
        present = entry.get("present") or self._present_sections(sections)
        if not present:
            self._hap("error")
            self._toast(S("profile_err_no_sections"))
            return
        try:
            if manager_sheet is not None:
                manager_sheet.dismiss()
        except Exception:
            pass
        name = str(entry.get("name", ""))

        def _show(rows):
            self._profile_section_picker(
                S("restore_title"), S("restore_subtitle", name),
                S("restore_action"), present, sections,
                lambda keys: self._apply_profile_import(sections, keys),
                extra_builder=lambda ctx: self._restore_preview_view(ctx, rows))

        def _work():
            # The diff needs the core's current sections — a JNI call carrying the whole gift
            # library. Compute it here, hand the finished rows to the UI thread.
            rows = []
            try:
                rows = self._restore_changes(sections, present, self._current_sections())
            except Exception as error:
                self.log("[backup] diff: " + _cause(error))
            try:
                run_on_ui_thread(lambda: _show(rows))
            except Exception:
                _show(rows)

        try:
            import threading
            threading.Thread(target=_work, daemon=True).start()
        except Exception:
            _work()

    def _restore_preview_view(self, ctx, rows):
        """«Что изменится»: current value → the value the file would install. Rows arrive
        precomputed, and the block is skipped entirely when nothing would change."""
        try:
            if not rows:
                return self._sheet_subtitle(ctx, S("restore_no_changes"))
            box = LinearLayout(ctx)
            box.setOrientation(LinearLayout.VERTICAL)
            box.setPadding(AndroidUtilities.dp(12), AndroidUtilities.dp(10),
                           AndroidUtilities.dp(12), AndroidUtilities.dp(10))
            surface = int(self._theme_color("key_windowBackgroundGray", 0xFF1C1C1E))
            try:
                box.setBackground(self._create_round_rect(surface, 12))
            except Exception:
                pass
            header = TextView(ctx)
            header.setText(S("restore_changes_header"))
            header.setTextColor(int(self._theme_color("key_windowBackgroundWhiteGrayText2", 0xFF9AA3AE)))
            header.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
            box.addView(header, LinearLayout.LayoutParams(-1, -2))
            for title, before, after in rows:
                line = TextView(ctx)
                line.setText(S("restore_change_line", title, before, after))
                line.setTextColor(int(self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)))
                line.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                lp = LinearLayout.LayoutParams(-1, -2)
                lp.topMargin = AndroidUtilities.dp(6)
                box.addView(line, lp)
            return box
        except Exception as e:
            self.log("[backup] preview: " + _cause(e))
            return None

    def _load_profile_file(self, filepath):
        """Kept for the chat-tap route: parsed payload or None."""
        try:
            raw = read_file(filepath) if read_file is not None else None
        except Exception as e:
            self.log("[profile] load: " + _cause(e))
            return None
        data, _error = self._parse_profile(raw)
        return data

    def _do_profile_import(self, filepath, filename):
        """Entry point for a .profile tapped in a chat: same preview and picker as the
        manager, so a file from a friend is never applied sight unseen."""
        import os
        try:
            raw = read_file(filepath) if read_file is not None else None
        except Exception as e:
            self.log("[profile] read: " + _cause(e))
            raw = None
        data, error = self._parse_profile(raw)
        if error or not data:
            self._hap("error")
            self._toast(S(str(error or "profile_err_bad_payload")))
            return
        sections = data.get("sections") or {}
        size = 0
        mtime = 0
        try:
            size = int(os.path.getsize(filepath))
            mtime = int(data.get("timestamp", 0) or os.path.getmtime(filepath))
        except Exception:
            pass
        entry = {"name": str(filename), "path": str(filepath), "size": size, "mtime": mtime,
                 "data": data, "error": None, "sections": sections,
                 "present": self._present_sections(sections),
                 "built_by": str(data.get("plugin_version", "") or "")}
        self._restore_backup(None, entry)

    def _apply_profile_import(self, sections, keys):
        try:
            res = self._jvoid("importProfile", ("str", "str"),
                              (json.dumps(sections), ",".join(keys)))
            self.log("[profile] import -> " + str(res))
            # `"FAIL" in str(None)` is False, so a bridge that never ran used to report a restore
            # that never happened.
            written, text = self._bridge_ok(res)
            if not written or "nothing to import" in text:
                self._hap("error")
                self._toast(S("restore_failed", (text or "no answer")[:100]))
                return
            labels = ", ".join(self._section_title(k) for k in keys)
            # A restore rewrites gifts, identity and rating at once — the heaviest thing this
            # screen can do, and the one place the full ramp is earned.
            self._hap("reveal", essential=True)
            self._toast(S("restore_done", labels))
            try:
                self._schedule_settings_refresh()
            except Exception:
                pass
        except Exception as e:
            self._hap("error")
            self._toast(S("restore_failed", repr(e)[:120]))
            try: self.log("[profile] apply: " + _cause(e))
            except Exception: pass

    # ---- tap a .profile file in a chat → open our import sheet ----
    def _install_profile_open_hook(self):
        if getattr(self, "_profile_open_hooked", False):
            return
        if MethodHook is None or _ProfileOpenHook is None or getattr(self, "hook_method", None) is None:
            return
        try:
            AU = JavaClass.forName("org.telegram.messenger.AndroidUtilities")
        except Exception as e:
            self.log("[profile] open hook: no AU " + _cause(e)); return
        refs = []
        try:
            for m in AU.getDeclaredMethods():
                try:
                    nm = str(m.getName() or "")
                    ps = list(m.getParameterTypes() or [])
                except Exception:
                    continue
                if not ps or nm not in ("openDocument", "openForView"):
                    continue
                first = str(ps[0].getName() or "")
                supported = (
                    "MessageObject" in first or
                    first == "java.io.File" or
                    "TLRPC$Document" in first or
                    first.endswith(".TLObject")
                )
                if not supported:
                    continue
                try: m.setAccessible(True)
                except Exception: pass
                try: refs.append(self.hook_method(m, _ProfileOpenHook(self)))
                except Exception as e: self.log("[profile] open hook " + nm + "(" + first + "): " + _cause(e))
        except Exception as e:
            self.log("[profile] open hook scan: " + _cause(e)); return
        self._profile_open_refs = refs
        self._profile_open_hooked = bool(refs)
        self.log("[profile] open hooks installed: " + str(len(refs)))

    def _profile_open_names(self, args):
        names = []
        for obj in list(args or []):
            if obj is None:
                continue
            if isinstance(obj, str):
                names.append(str(obj))
            for getter in ("getFileName", "getDocumentName", "getName", "getAbsolutePath"):
                try:
                    value = getattr(obj, getter)()
                    if value:
                        names.append(str(value))
                except Exception:
                    pass
            try:
                path = str(obj.messageOwner.attachPath or "")
                if path:
                    names.append(path)
            except Exception:
                pass
            try:
                attrs = getattr(obj, "attributes", None)
                count = int(attrs.size()) if attrs is not None else 0
                for i in range(count):
                    value = str(getattr(attrs.get(i), "file_name", "") or "")
                    if value:
                        names.append(value)
            except Exception:
                pass
        return names

    def _profile_name_matches(self, value):
        try:
            clean = str(value or "").split("?", 1)[0].split("#", 1)[0].strip().lower()
            return clean.endswith(".profile")
        except Exception:
            return False

    def _handle_profile_open_args(self, args):
        """Resolve MessageObject, File and Document open routes."""
        names = self._profile_open_names(args)
        matching = [n for n in names if self._profile_name_matches(n)]
        if not matching:
            return False
        display_name = os.path.basename(matching[0]) or "config.profile"
        first = args[0] if args else None
        path = ""

        # java.io.File overload: Telegram already resolved the download.
        try: path = str(first.getAbsolutePath() or "")
        except Exception: path = ""

        # MessageObject overload: prefer attachPath, then FileLoader cache.
        if (not path or not os.path.exists(path)) and first is not None:
            try: path = str(first.messageOwner.attachPath or "")
            except Exception: path = ""
            if not path or not os.path.exists(path):
                try:
                    FileLoader = jclass("org.telegram.messenger.FileLoader")
                    loader = FileLoader.getInstance(int(first.currentAccount))
                    resolved = loader.getPathToMessage(first.messageOwner)
                    path = str(resolved.getAbsolutePath() or "") if resolved is not None else ""
                except Exception:
                    path = ""

        # Direct TLRPC.Document/TLObject route used by some AyuGram builds.
        if (not path or not os.path.exists(path)) and first is not None:
            try:
                FileLoader = jclass("org.telegram.messenger.FileLoader")
                loader = FileLoader.getInstance(_selected_account())
                resolved = loader.getPathToAttach(first, True)
                path = str(resolved.getAbsolutePath() or "") if resolved is not None else ""
            except Exception:
                path = ""

        if not path or not os.path.exists(path):
            self._toast("Файл ещё не загружен — дождись загрузки и нажми ещё раз")
            return True

        # Protect custom clients that call both overloads from opening two sheets.
        now = __import__("time").monotonic()
        if (str(path) == getattr(self, "_profile_open_last_path", "") and
                now - float(getattr(self, "_profile_open_last_at", 0.0) or 0.0) < 0.8):
            return True
        self._profile_open_last_path = str(path)
        self._profile_open_last_at = now
        run_on_ui_thread(lambda p=str(path), n=display_name: self._do_profile_import(p, n))
        return True

    def _handle_profile_file_open(self, msg):
        return self._handle_profile_open_args([msg])

    # ---- first-level ProfileActivity menu: copy another user's gifts ----
    def _install_profile_copy_menu_hook(self):
        if getattr(self, "_profile_copy_menu_hooked", False):
            return
        if MethodHook is None or _ProfileCopyMenuHook is None or getattr(self, "hook_method", None) is None:
            self.log("[copy-menu] MethodHook unavailable")
            return
        try:
            pa = JavaClass.forName("org.telegram.ui.ProfileActivity")
        except Exception as e:
            self.log("[copy-menu] no ProfileActivity: " + _cause(e))
            return
        refs = []
        try:
            for method in pa.getDeclaredMethods():
                try:
                    if str(method.getName() or "") != "createActionBarMenu":
                        continue
                    params = list(method.getParameterTypes() or [])
                    if len(params) != 1 or str(params[0].getName() or "") != "boolean":
                        continue
                    method.setAccessible(True)
                    refs.append(self.hook_method(method, _ProfileCopyMenuHook(self)))
                except Exception as e:
                    self.log("[copy-menu] method: " + _cause(e))
        except Exception as e:
            self.log("[copy-menu] scan: " + _cause(e))
            return
        self._profile_copy_menu_refs = refs
        self._profile_copy_menu_hooked = bool(refs)
        try:
            drawable = jclass("org.telegram.messenger.R$drawable")
            self._profile_copy_icon = int(
                getattr(drawable, "msg_copy", 0) or getattr(drawable, "msg_add", 0) or 0
            )
        except Exception:
            self._profile_copy_icon = 0
        try:
            self._profile_copy_my_uid = int(_real_uid() or 0)
        except Exception:
            self._profile_copy_my_uid = 0
        self.log("[copy-menu] hooks installed: " + str(len(refs)))

    def _inject_profile_copy_menu_item(self, activity):
        if activity is None:
            return False
        try:
            uid = int(_gv(activity, "userId", 0) or _gv(activity, "user_id", 0) or 0)
        except Exception:
            uid = 0
        if uid <= 0:
            try:
                dialog_id = int(activity.getDialogId() or 0)
                uid = dialog_id if dialog_id > 0 else 0
            except Exception:
                uid = 0
        if uid <= 0:
            return False
        # OWN profile is the reported micro-freeze, and for it this whole hook is a guaranteed no-op:
        # the copy action only exists on someone else's profile. createActionBarMenu runs on every
        # profile open, so answering "that's me" from the uid cached at install time keeps the self
        # case free of reflection entirely. Only a uid we do NOT recognise re-reads the live one,
        # which is what keeps an account switch correct.
        cached_my_uid = int(getattr(self, "_profile_copy_my_uid", 0) or 0)
        if cached_my_uid > 0 and uid == cached_my_uid:
            return False
        try:
            my_uid = int(_real_uid() or cached_my_uid or 0)
        except Exception:
            my_uid = cached_my_uid
        if my_uid > 0:
            if my_uid != cached_my_uid:
                self._profile_copy_my_uid = my_uid    # account switched → re-point the fast path
            if uid == my_uid:
                return False
        try:
            other = _gv(activity, "otherItem", None)
            if other is None:
                self.log("[copy-menu] otherItem missing uid=" + str(uid))
                return False
            icon = int(getattr(self, "_profile_copy_icon", 0) or 0)
            item = None
            try:
                popup = other.getPopupLayout()
                if popup is not None:
                    for index in range(int(popup.getChildCount() or 0)):
                        child = popup.getChildAt(index)
                        try:
                            if int(child.getTag() or 0) == 60183:
                                item = child
                                break
                        except Exception:
                            pass
            except Exception:
                item = None
            if item is None:
                item = other.addSubItem(60183, icon, "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u043e\u0434\u0430\u0440\u043a\u0438")

            listeners = getattr(self, "_profile_copy_listeners", None)
            if listeners is None:
                listeners = self._profile_copy_listeners = {}
            listener = listeners.get(uid)
            if listener is None and _ProfileCopyClickListener is not None:
                listener = _ProfileCopyClickListener(self, uid, activity, other)
                listeners[uid] = listener
                if len(listeners) > 32:
                    try: del listeners[next(iter(listeners))]
                    except Exception: pass
            elif listener is not None:
                listener.bind(uid, activity, other)
            else:
                # Compatibility fallback for builds without java.dynamic_proxy.
                def _tap(_view=None):
                    try: other.toggleSubMenu()
                    except Exception: pass
                    self._open_profile_copy_picker(uid, activity)
                listener = self._click(_tap)
            item.setOnClickListener(listener)
            return True
        except Exception as e:
            self.log("[copy-menu] add uid=" + str(uid) + ": " + _cause(e))
            return False

    def _open_profile_copy_picker(self, uid, activity):
        def _show(prod):
            if prod is None:
                self._toast("\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043f\u043e\u0434\u0430\u0440\u043a\u0438")
                return
            try:
                prod._open_remote_gift_copy_picker({"user_id": int(uid), "fragment": activity})
            except Exception as e:
                self.log("[copy-menu] picker: " + _cause(e))
                self._toast("\u041e\u0448\u0438\u0431\u043a\u0430 \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u044f \u0432\u044b\u0431\u043e\u0440\u0430")

        prod = getattr(self, "_prod", None)
        if prod is None:
            self._toast("\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u044e \u043f\u043e\u0434\u0430\u0440\u043a\u0438\u2026")
        try:
            import threading
            def _load():
                loaded = prod or self._ensure_prod()
                # This runtime is normally loaded without its profile hooks. Start only
                # the sync client required by the picker, and do it away from the UI
                # thread so opening an already-heavy foreign profile stays responsive.
                try:
                    if loaded is not None and getattr(loaded, "_chimeranft_sync_client", None) is None:
                        loaded._sync_bootstrap()
                except Exception as sync_error:
                    self.log("[copy-menu] sync bootstrap: " + _cause(sync_error))
                run_on_ui_thread(lambda: _show(loaded))
            thread = threading.Thread(target=_load, name="chimera-copy-picker")
            thread.daemon = True
            thread.start()
        except Exception:
            loaded = prod or self._ensure_prod()
            try:
                if loaded is not None and getattr(loaded, "_chimeranft_sync_client", None) is None:
                    loaded._sync_bootstrap()
            except Exception as sync_error:
                self.log("[copy-menu] sync bootstrap fallback: " + _cause(sync_error))
            _show(loaded)

    # ---- lazy production runtime, ONLY for the catalog / gift-constructor UI ----
    def _ensure_prod(self):
        """Thread-safe + double-checked: the background pre-warm builds the prod runtime
        while a user tap may race it from the UI thread — only one build ever runs."""
        prod = getattr(self, "_prod", None)
        if prod is not None:
            return prod
        lk = getattr(self, "_prod_lock", None)
        if lk is None:
            import threading
            lk = self._prod_lock = threading.Lock()
        with lk:
            return self._ensure_prod_inner()

    def _ensure_prod_inner(self):
        prod = getattr(self, "_prod", None)
        if prod is not None:
            return prod
        try:
            candidates = _runtime_dir_candidates()
            root = next((d for d in candidates if os.path.isdir(d)), candidates[0])
            os.makedirs(root, exist_ok=True)
            _extract_runtime(root)
            cls, mod = _import_runtime(root)
            self._prod_mod = mod
            # the header/cards/about reuse prod builders, which read the prod module's
            # __version__ — surface OUR version instead (cosmetic, prod runtime here is
            # used for UI only, never for sync/update where its version matters).
            try:
                mod.__version__ = __version__
            except Exception:
                pass
            prod = cls()
            # bind the framework methods from THIS (framework-loaded) plugin so the
            # production instance can log / hook / read settings.
            for nm in ("log", "hook_method", "unhook_method", "add_menu_item",
                       "remove_menu_item", "get_setting", "set_setting"):
                fn = getattr(self, nm, None)
                if fn is not None:
                    try:
                        setattr(prod, nm, fn)
                    except Exception:
                        pass
            try:
                prod._CHIMERANFT_SINGLE_FILE_BUILD = True
            except Exception:
                pass
            # Mutations from the UI-only runtime go directly to Elyx Core's
            # authoritative Store. This avoids a Python-cache/write/reload race.
            try:
                def _elyx_add_gifts(entries):
                    if self._clazz is None:
                        raise RuntimeError("core not loaded")
                    payload = json.dumps(list(entries or []), ensure_ascii=False)
                    result = self._jvoid("addGifts", ("str",), (payload,))
                    if result is None:
                        raise RuntimeError("core bridge returned no result")
                    try:
                        self._jvoid("pushSyncNow")
                    except Exception:
                        pass
                    return "" if result is None else str(result)
                prod._elyx_add_gifts_bridge = _elyx_add_gifts
            except Exception as bridge_error:
                self.log("[copy-menu] add bridge: " + _cause(bridge_error))
            # SINGLE WRITER. This runtime is loaded for cold UI only, but it still carried the
            # legacy whole-file cache writer: _collect_cache_snapshot() rebuilds the root from a
            # fixed ~35-key whitelist, so every save deleted every key Elyx Core owns (balances,
            # transaction history, gift/transaction tombstones, collections, pinned channel, local
            # Premium, sync flags, applied transfers, verification mode) and reverted gift_library
            # to whatever this runtime had loaded when it started. on_plugin_unload() flushed that
            # stale snapshot on every plugin disable / app unload, and Java's auto-backup writer
            # then copied the stripped root into the recovery set — so the loss survived the
            # restart. That is «данные сбрасываются после перезахода».
            #
            # Redirect its writes into Java's authoritative Store, which merges only the keys this
            # runtime genuinely owns and keeps everything else untouched.
            #
            # Installed FIRST, before _load_cache and before any hook exists, so there is no window
            # in which the legacy writer is still reachable.
            try:
                self._install_single_writer_guard(prod)
            except Exception as writer_error:
                self.log("[cat] single-writer guard: " + _cause(writer_error))
            # load state from cache — NO on_plugin_load, so NO hot-path hooks
            try:
                prod._load_cache()
            except Exception as e:
                self.log("[cat] _load_cache: " + repr(e))
            try:
                _diag("[prod] prod ready, gift_library=%d" % len(getattr(prod, "gift_library", []) or []))
            except Exception:
                pass
            # install ONLY the cold catalog UI hooks (fire only when catalog open)
            try:
                prod._hook_native_catalog_ui()
            except Exception as e:
                self.log("[cat] catalog hook: " + repr(e))
            self._prod = prod
            self.log("[cat] production runtime ready (catalog UI only)")
            return prod
        except Exception as e:
            self.log("[cat] ensure_prod: " + _cause(e))
            return None

    # Keys the UI runtime is allowed to persist. Must stay a subset of
    # Store.EXTERNAL_MERGE_KEYS — anything else it produces is Java-owned and is dropped.
    _PROD_OWNED_KEYS = (
        "build_config", "identity_config", "value_config", "gift_stars_config",
        "wear_status_data", "wear_active", "wear_collectible_id", "inject_active",
        "nft_collectible_template_b64", "nft_number_collectible_template_b64",
        "cached_gift_id", "gift_id", "title", "slug", "num",
        "regular_gifts", "_regular_gifts_seq",
    )

    def _install_single_writer_guard(self, prod):
        """Make the UI runtime physically unable to touch the cache file.

        Every disk-write entry point it owns is replaced: the debounced save, the synchronous
        flush used by on_plugin_unload / app-pause, the executor drain and the raw atomic writer.
        They all funnel into the Java Store's allowlisted merge instead, so Elyx Core stays the
        only process that ever rewrites stolen_cache_*.json."""
        # [nosave-fix] probe the bridge BEFORE taking ownership of the writes. If the core
        # failed to load (dex rejected, init failed), _jvoid("mergeState") would silently
        # swallow every save. In that case keep the runtime's own writers — they are the
        # only persistence path left.
        _probe = self._jvoid("mergeState", ("str",), ("{}",))
        _probe_s = "" if _probe is None else str(_probe)
        try:
            _diag("[store] single-writer probe -> " + _probe_s[:120])
        except Exception:
            pass
        if self._clazz is None or _probe is None or "(not initialized)" in _probe_s or _probe_s.startswith("FAIL"):
            self.log("[store] bridge unavailable (probe: " + _probe_s + ") — runtime keeps its cache writers")
            return

        def _push_owned_state():
            try:
                _uid, data = prod._collect_cache_snapshot()
            except Exception as snapshot_error:
                self.log("[store] snapshot: " + _cause(snapshot_error))
                return None
            slice_ = {}
            for key in self._PROD_OWNED_KEYS:
                if key in data:
                    slice_[key] = data[key]
            if not slice_:
                return None
            try:
                return self._jvoid("mergeState", ("str",), (json.dumps(slice_, ensure_ascii=False),))
            except Exception as merge_error:
                self.log("[store] mergeState: " + _cause(merge_error))
                return None

        def _save_cache(*_a, **_k):
            # Drop any snapshot the runtime had queued for its own writer, then hand the
            # owned slice to Java. Java persists synchronously, so there is nothing left to
            # flush later and nothing a force-stop can lose.
            try:
                prod._cache_pending = None
                prod._cache_save_future = None
                prod._library_dirty = False
            except Exception:
                pass
            return _push_owned_state()

        def _flush_cache_now(reason=""):
            return _save_cache()

        def _blocked_write(*_a, **_k):
            # Reached only if a future runtime revision adds a new write site. Fail loudly in
            # the log rather than silently corrupting the authoritative cache.
            self.log("[store] blocked a direct cache write from the UI runtime")
            return None

        prod._save_cache = _save_cache
        prod._flush_cache_now = _flush_cache_now
        prod._drain_cache_writes = _blocked_write
        prod._cache_atomic_write_json = _blocked_write
        # Rebinding the four writers above is not sufficient on its own: `_load_cache` has its own
        # `write_file(_cache_path(uid), …)` calls — the legacy import and the ".bak self-heal"
        # re-stamp — and they are reached from `prod._load_cache()`, which runs five lines after
        # this guard is installed. Those are plain non-atomic writes to the exact file Store.java
        # owns (§6.1), so they can leave a torn live file as the only copy, or put a generation
        # back that Store's own cold-start recovery had already superseded. The runtime keeps the
        # code because it is still the legitimate single writer when loaded standalone; under Elyx
        # it must observe this flag instead.
        prod._CHIMERANFT_READ_ONLY_CACHE = True

    # ---- settings header (frog card + Обновления/Кэш cards) — production look ----
    # All views are built natively in the bootstrap (NO production runtime dependency).
    def _theme_color(self, attr_name, fallback=0xFF222222):
        try:
            key = getattr(Theme, attr_name, None)
            if key is not None:
                return int(Theme.getColor(key))
        except Exception:
            pass
        return self._col(fallback)

    def _create_round_rect(self, color, radius_dp=18, stroke_color=0, stroke_dp=0):
        bg = GradientDrawable()
        try: bg.setCornerRadius(float(AndroidUtilities.dp(radius_dp)))
        except Exception: pass
        try: bg.setColor(int(color))
        except Exception: pass
        try:
            if int(stroke_dp or 0) > 0:
                bg.setStroke(AndroidUtilities.dp(int(stroke_dp)), int(stroke_color or 0))
        except Exception: pass
        return bg

    def _load_welcome_sticker(self, imageView, size="108_108", idx=31):
        """Load the frog welcome sticker (HappyHappyPepe idx 31) into a BackupImageView."""
        if MediaDataController is None or ImageLocation is None or imageView is None:
            return False
        try:
            mc = MediaDataController.getInstance(_selected_account())
        except Exception:
            mc = None
        if mc is None:
            return False
        ss = None
        try:
            ss = mc.getStickerSetByName(CHIMERANFT_WELCOME_STICKER_SET)
        except Exception:
            ss = None
        if ss is None:
            try: ss = mc.getStickerSetByEmojiOrName(CHIMERANFT_WELCOME_STICKER_SET)
            except Exception: ss = None
        try:
            docs = getattr(ss, "documents", None) if ss is not None else None
            if docs is not None and docs.size() > 0:
                doc = docs.get(min(idx, docs.size() - 1))
                loc = ImageLocation.getForDocument(doc)
                if loc is not None:
                    imageView.setImage(loc, size, None, None, 0, 1)
                    try:
                        rc = imageView.getImageReceiver()
                        if rc is not None:
                            rc.setAllowStartAnimation(True)
                            rc.startAnimation()
                    except Exception:
                        pass
                    return True
        except Exception:
            pass
        try:
            mc.loadStickersByEmojiOrName(CHIMERANFT_WELCOME_STICKER_SET, False, False)
        except Exception:
            pass
        return False

    def _frame(self, view, w, h, gravity, l, t, r, b):
        if LayoutHelper is not None:
            try:
                return LayoutHelper.createFrame(w, h, gravity, l, t, r, b)
            except Exception:
                pass
        lp = FrameLayout.LayoutParams(
            AndroidUtilities.dp(w) if w > 0 else w,
            AndroidUtilities.dp(h) if h > 0 else h, gravity)
        lp.leftMargin = AndroidUtilities.dp(l); lp.topMargin = AndroidUtilities.dp(t)
        lp.rightMargin = AndroidUtilities.dp(r); lp.bottomMargin = AndroidUtilities.dp(b)
        return lp

    def _build_header_view(self, ctx, animate=True):
        """PackIt settings hero, adapted to OpenChimeraNFT branding.

        `animate` is False for every rebuild of a screen that is already open — see
        _hero_intro_wanted. The entrance belongs to the screen appearing, not to the list
        re-diffing itself."""
        try:
            container = FrameLayout(ctx)
            main_layout = LinearLayout(ctx)
            main_layout.setOrientation(LinearLayout.VERTICAL)
            main_layout.setGravity(Gravity.CENTER)
            main_layout.setPadding(
                AndroidUtilities.dp(20), AndroidUtilities.dp(20),
                AndroidUtilities.dp(20), AndroidUtilities.dp(20)
            )
            iv = BackupImageView(ctx)
            try: iv.setRoundRadius(AndroidUtilities.dp(45))
            except Exception: pass
            if not self._load_welcome_sticker(iv):
                try: run_on_ui_thread(lambda: self._load_welcome_sticker(iv), 1500)
                except Exception: pass
            if LayoutHelper is not None:
                main_layout.addView(
                    iv, LayoutHelper.createLinear(
                        130, 130, Gravity.CENTER, 0, 0, 0, 16
                    )
                )
            else:
                ilp = LinearLayout.LayoutParams(
                    AndroidUtilities.dp(130), AndroidUtilities.dp(130)
                )
                ilp.gravity = Gravity.CENTER_HORIZONTAL
                ilp.bottomMargin = AndroidUtilities.dp(16)
                main_layout.addView(iv, ilp)

            text_container = LinearLayout(ctx)
            text_container.setOrientation(LinearLayout.VERTICAL)
            text_container.setGravity(Gravity.CENTER)
            title = TextView(ctx)
            try: title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception: pass
            try:
                title.setTypeface(AndroidUtilities.getTypeface(
                    AndroidUtilities.TYPEFACE_ROBOTO_MEDIUM
                ))
            except Exception: pass
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 22)
            title.setText("OpenChimeraNFT v" + __version__)
            title.setSingleLine(True)
            title.setGravity(Gravity.CENTER)
            if LayoutHelper is not None:
                text_container.addView(
                    title, LayoutHelper.createLinear(-1, -2, 0, 0, 4, 0)
                )
            else:
                tlp = LinearLayout.LayoutParams(-1, -2)
                tlp.bottomMargin = AndroidUtilities.dp(4)
                text_container.addView(title, tlp)

            subtitle = TextView(ctx)
            try: subtitle.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception: pass
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            subtitle.setText(S("description"))
            subtitle.setGravity(Gravity.CENTER)
            text_container.addView(subtitle, LinearLayout.LayoutParams(-1, -2))
            main_layout.addView(text_container, LinearLayout.LayoutParams(-1, -2))
            container.addView(
                main_layout, FrameLayout.LayoutParams(-1, -2, Gravity.CENTER)
            )
            try:
                iv.setOnClickListener(self._click(lambda v: self._load_welcome_sticker(iv)))
            except Exception:
                pass
            # Staggered hero entrance once UniversalRecyclerView attaches this custom item.
            # Delayed start avoids animating while still detached.
            #
            # ONLY on a genuine screen appearance. `fillItems` re-fires for every reason the list
            # has to re-diff — a switch toggled, a subtext refreshed, a sub-page returned from,
            # sync landing a new value — and the header view is rebuilt FRESH each time (see
            # _inject_settings_header). Starting the entrance from here therefore replayed the
            # fade on the frog, the title and the description over and over while the user simply
            # sat on the screen, which is the reported "постоянно воспроизводится fade". The
            # decision is made once per open in _hero_intro_wanted; a rebuild renders the hero at
            # its final alpha/scale instead of animating to it.
            if animate:
                try:
                    run_on_ui_thread(lambda: self._animate_in(iv, 0, 14, 320, 0.82), 70)
                    run_on_ui_thread(lambda: self._animate_in(title, 0, 10, 280, 0.96), 125)
                    run_on_ui_thread(lambda: self._animate_in(subtitle, 0, 8, 260, 0.98), 175)
                except Exception:
                    pass
            return container
        except Exception as e:
            self.log("[hdr] build header: " + _cause(e))
            return None

    def _build_settings_footer_view(self, ctx):
        """PackIt-style host label and ElyxCore attribution."""
        try:
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setGravity(Gravity.CENTER_HORIZONTAL)
            root.setPadding(
                AndroidUtilities.dp(12), AndroidUtilities.dp(8),
                AndroidUtilities.dp(12), AndroidUtilities.dp(16)
            )

            label = TextView(ctx)
            label.setText("Universal")
            label.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            label.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            label.setGravity(Gravity.CENTER)
            root.addView(label)

            chip = TextView(ctx)
            chip.setText("Powered by ElyxCore")
            chip.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 10)
            chip.setPadding(
                AndroidUtilities.dp(8), AndroidUtilities.dp(2),
                AndroidUtilities.dp(8), AndroidUtilities.dp(2)
            )
            chip.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            chip.setGravity(Gravity.CENTER)

            bg = GradientDrawable()
            bg.setCornerRadius(float(AndroidUtilities.dp(12)))
            gray = int(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            stroke = (gray & 0x40FFFFFF) if Theme.isCurrentThemeDark() else 0x20000000
            bg.setStroke(AndroidUtilities.dp(1), int(stroke))
            chip.setBackground(bg)

            lp = LinearLayout.LayoutParams(-2, -2)
            lp.topMargin = AndroidUtilities.dp(8)
            root.addView(chip, lp)
            return root
        except Exception as e:
            self.log("[hdr] build footer: " + _cause(e))
            return None

    def _build_cards_view(self, ctx):
        try:
            st = self._settings()
            ss = self._sync_status()
            outer = LinearLayout(ctx)
            outer.setOrientation(LinearLayout.HORIZONTAL)
            try: outer.setPadding(AndroidUtilities.dp(24), 0, AndroidUtilities.dp(24), AndroidUtilities.dp(10))
            except Exception: pass
            bg = self._theme_color("key_dialogBackground", 0xFF1A1A1A)
            text = self._theme_color("key_windowBackgroundWhiteBlackText", 0xFFFFFFFF)
            muted = self._theme_color("key_windowBackgroundWhiteGrayText", 0xFF9A9A9A)
            accent = self._theme_color("key_featuredStickers_addButton", 0xFF4E62FF)
            danger = self._theme_color("key_text_RedBold", 0xFFE57373)

            def _card(t, sub, tint, cb):
                card = LinearLayout(ctx)
                card.setOrientation(LinearLayout.VERTICAL)
                try:
                    card.setClickable(True); card.setFocusable(True)
                    card.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(9), AndroidUtilities.dp(14), AndroidUtilities.dp(8))
                    card.setBackground(self._ripple_bg(self._create_round_rect(bg, radius_dp=16), accent))
                    card.setElevation(float(AndroidUtilities.dp(1)))
                except Exception: pass
                tv = TextView(ctx)
                tv.setText(t); tv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15.0); tv.setTextColor(int(text))
                try: tv.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                except Exception: pass
                card.addView(tv, LinearLayout.LayoutParams(-1, -2))
                sv = TextView(ctx)
                sv.setText(sub); sv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12.0); sv.setTextColor(int(muted))
                sv.setMaxLines(2)
                lps = LinearLayout.LayoutParams(-1, -2); lps.topMargin = AndroidUtilities.dp(2)
                card.addView(sv, lps)
                line = View(ctx)
                try: line.setBackgroundColor(int(tint))
                except Exception: pass
                lpl = LinearLayout.LayoutParams(AndroidUtilities.dp(30), AndroidUtilities.dp(3)); lpl.topMargin = AndroidUtilities.dp(8)
                card.addView(line, lpl)
                try: card.setOnClickListener(self._click(lambda v: cb()))
                except Exception: pass
                return card

            gift_count = int(st.get("gift_count", 0) or 0)
            sync_tint = accent if bool(ss.get("enabled", False)) and str(ss.get("state", "ready")) != "error" else danger
            uc = _card("Коллекция", str(gift_count) + " NFT", accent, self._open_my_gifts)
            sync_ok = bool(ss.get("enabled", False)) and str(ss.get("state", "ready")) != "error"
            cc = _card("Обновить профиль", "Всё сохранено" if sync_ok else "Нужно повторить", sync_tint, self._sync_now)
            lp1 = LinearLayout.LayoutParams(0, AndroidUtilities.dp(72), 1.0)
            lp2 = LinearLayout.LayoutParams(0, AndroidUtilities.dp(72), 1.0); lp2.leftMargin = AndroidUtilities.dp(10)
            outer.addView(uc, lp1); outer.addView(cc, lp2)
            try:
                run_on_ui_thread(lambda: self._animate_in(uc, 0, 12, 260, 0.94), 110)
                run_on_ui_thread(lambda: self._animate_in(cc, 0, 12, 260, 0.94), 165)
            except Exception:
                pass
            return outer
        except Exception as e:
            self.log("[hdr] build cards: " + _cause(e))
            return None

    def _open_update_check(self):
        """«Обновления» card → check now and self-update. Resets the popup/install
        latches so it ALWAYS works even after the auto-popup was dismissed/minimized:
        - _upd_popup_active / _upd_dismissed_until: cleared so the forced sheet shows;
        - _plug_installed: cleared so «Обновить» can re-trigger the install (the guard
          otherwise no-ops a second attempt → «не отдаёт нормально»)."""
        self._toast("Проверяю обновления…")
        self._upd_popup_active = False
        self._upd_dismissed_until = 0
        self._plug_installed = False
        try:
            self._check_for_update(True)
        except Exception as e:
            self.log("[upd] manual: " + _cause(e))
            self._toast("Ошибка проверки обновлений")

    def _open_cache_cleanup(self):
        """Multi-toggle cache-cleanup sheet (ported from the regular OpenChimeraNFT plugin):
        Каталог/Временные/Ассеты ON by default; Экспорты/Локальный профиль/Удалить-всё OFF.
        «Удалить плагин и все файлы» auto-enables every other toggle."""
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or BottomSheet is None:
                self._clear_plugin_cache(); return
            TextCheckCell = jclass("org.telegram.ui.Cells.TextCheckCell")
            sheet = BottomSheet(ctx, False)
            accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))

            root = LinearLayout(ctx); root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(18), AndroidUtilities.dp(20), AndroidUtilities.dp(14))

            title = TextView(ctx); title.setText("Очистка кэша")
            title.setTextColor(int(self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)))
            try: title.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            root.addView(title, LinearLayout.LayoutParams(-1, -2))

            subtitle = TextView(ctx)
            subtitle.setText("Выбери, что удалить. Опасные данные профиля по умолчанию выключены.")
            subtitle.setTextColor(int(self._theme_color("key_windowBackgroundWhiteGrayText2", 0xFF9AA3AE)))
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            lp_sub = LinearLayout.LayoutParams(-1, -2); lp_sub.topMargin = AndroidUtilities.dp(6)
            root.addView(subtitle, lp_sub)

            selected = {"catalog": True, "temp": True, "assets": True,
                        "profiles": False, "local_profile": False, "purge_plugin": False}
            defs = list(self._cache_cleanup_option_defs()) + [
                ("purge_plugin", "Удалить плагин и все файлы",
                 "Рантайм, кэш, .profile, настройки и локальные данные")]
            cells = LinearLayout(ctx); cells.setOrientation(LinearLayout.VERTICAL)
            lp_cells = LinearLayout.LayoutParams(-1, -2); lp_cells.topMargin = AndroidUtilities.dp(16)
            cells_by_key = {}

            for idx, (key, title_text, desc_text) in enumerate(defs):
                cell = TextCheckCell(ctx, 21, True)
                cell.setTextAndValueAndCheck(str(title_text), str(desc_text), bool(selected.get(key, False)), True, idx != len(defs) - 1)
                cells_by_key[key] = cell

                def _toggle(v, _cell=cell, _key=key):
                    nv = not bool(selected.get(_key, False))
                    selected[_key] = nv
                    # Arming «удалить плагин и все файлы» ticks every other row on at once, so it
                    # gets a warning rather than the ordinary toggle click.
                    if _key == "purge_plugin" and nv:
                        self._hap("warning")
                    else:
                        self._hap_toggle(nv)
                    try: _cell.setChecked(nv)
                    except Exception: pass
                    if _key == "purge_plugin" and nv:
                        for k2, c2 in list(cells_by_key.items()):
                            selected[k2] = True
                            try: c2.setChecked(True)
                            except Exception: pass

                cell.setOnClickListener(self._click(_toggle, hap=None))
                if key == "purge_plugin":
                    lpc = LinearLayout.LayoutParams(-1, -2); lpc.topMargin = AndroidUtilities.dp(10)
                    cells.addView(cell, lpc)
                else:
                    cells.addView(cell)
            root.addView(cells, lp_cells)

            buttons = LinearLayout(ctx); buttons.setOrientation(LinearLayout.HORIZONTAL)
            lp_buttons = LinearLayout.LayoutParams(-1, -2); lp_buttons.topMargin = AndroidUtilities.dp(16)

            cancel = TextView(ctx); cancel.setText("Отмена"); cancel.setGravity(Gravity.CENTER)
            try: cancel.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            cancel.setTextColor(accent)
            cancel.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14), AndroidUtilities.dp(8), AndroidUtilities.dp(14))
            cancel.setOnClickListener(self._click(lambda v: sheet.dismiss(), hap="dismiss"))

            apply = TextView(ctx); apply.setText("Очистить"); apply.setGravity(Gravity.CENTER)
            try: apply.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            apply.setTextColor(-1)
            try:
                bg = GradientDrawable(); bg.setCornerRadius(float(AndroidUtilities.dp(12))); bg.setColor(accent); apply.setBackground(self._ripple_bg(bg, accent))
                apply.setElevation(float(AndroidUtilities.dp(2)))
            except Exception: pass
            apply.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14), AndroidUtilities.dp(8), AndroidUtilities.dp(14))

            def _apply(v):
                keys = [k for k, _t, _d in defs if bool(selected.get(k, False))]
                if not keys:
                    self._hap("error")
                    self._toast("Выбери хотя бы один пункт"); return
                try: sheet.dismiss()
                except Exception: pass
                if "purge_plugin" in keys:
                    self._confirm_purge_plugin(ctx)
                else:
                    # The crunch lands in _clear_selected_cache, once it knows what really went.
                    self._clear_selected_cache(keys)
            apply.setOnClickListener(self._click(_apply, hap=None))

            buttons.addView(cancel, LinearLayout.LayoutParams(0, -2, 1.0))
            lp_apply = LinearLayout.LayoutParams(0, -2, 1.0); lp_apply.leftMargin = AndroidUtilities.dp(10)
            buttons.addView(apply, lp_apply)
            root.addView(buttons, lp_buttons)

            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)
        except Exception as e:
            self.log("[cache] " + _cause(e))
            self._clear_plugin_cache()

    def _cache_cleanup_option_defs(self):
        return [
            ("catalog", "Каталог и цены", "Списки подарков, фильтры, floor-цены"),
            ("temp", "Временные файлы", ".tmp, .bak, .recover и служебные sidecar-файлы"),
            ("assets", "Ассеты и аватары", "Кэш картинок и about/support ассетов"),
            ("profiles", "Экспорты .profile", "Сохранённые конфиги из Downloads/OpenChimeraNFT"),
            ("local_profile", "Локальный профиль", "Подарки, username, number, rating и настройки профиля"),
        ]

    def _remove_path_quiet(self, path):
        import os, shutil
        try:
            if not path or not os.path.exists(path):
                return 0
            if os.path.isdir(path):
                shutil.rmtree(path, ignore_errors=True)
            else:
                os.remove(path)
            return 1
        except Exception:
            return 0

    def _clear_selected_cache(self, keys):
        import os
        keys = set(str(k) for k in (keys or []))
        ddir = _resolve_data_dir() or ""
        removed = 0
        if "catalog" in keys:
            try: self._cat_ctrl = None
            except Exception: pass
            for attr in ("_market_floor_cache", "_catalog_items_cache", "_catalog_base_list", "_catalog_load_requested"):
                try: setattr(self, attr, None)
                except Exception: pass
        if "temp" in keys and ddir and os.path.isdir(ddir):
            # NEVER delete stolen_cache*.bak / .recover: those are the recovery generations
            # Elyx Core's Store votes on at every cold start. Wiping them under a «Кэш» button
            # left a torn or stripped live file as the only copy — one bad write then looked
            # like a permanent data reset. Only genuinely disposable staging files go.
            try:
                for n in os.listdir(ddir):
                    low = n.lower()
                    if low.startswith("stolen_cache") and not low.endswith(".tmp"):
                        continue
                    if n.endswith((".tmp", ".bak", ".recover")):
                        removed += self._remove_path_quiet(os.path.join(ddir, n))
            except Exception: pass
        if "assets" in keys and ddir and os.path.isdir(ddir):
            try:
                for n in os.listdir(ddir):
                    low = n.lower()
                    if low.endswith((".svg", ".png", ".webp", ".jpg")) or "asset" in low or "avatar" in low:
                        removed += self._remove_path_quiet(os.path.join(ddir, n))
            except Exception: pass
        if "profiles" in keys:
            try:
                for pdir in self._profile_dirs():
                    if not os.path.isdir(pdir):
                        continue
                    for n in os.listdir(pdir):
                        if n.lower().endswith(".profile"):
                            removed += self._remove_path_quiet(os.path.join(pdir, n))
            except Exception: pass
        if "local_profile" in keys and ddir and os.path.isdir(ddir):
            # DANGER: wipes gifts/username/number/rating/settings (the Java cache file(s)).
            try:
                for n in os.listdir(ddir):
                    low = n.lower()
                    if low.startswith("stolen_cache") or low.endswith(".json"):
                        removed += self._remove_path_quiet(os.path.join(ddir, n))
            except Exception: pass
            self._hap("crunch", essential=True)
            self._toast("Локальный профиль очищен — перезапусти Telegram")
            return
        # «хруст» only when something was actually broken up; an empty cache is just a tick.
        if removed:
            self._hap("crunch", essential=True)
        self._toast("Кэш очищен ✓" if removed else "Кэш уже пуст")

    def _confirm_purge_plugin(self, ctx):
        try:
            if AlertDialogBuilder is None:
                self._purge_all_plugin_files(); return
            b = AlertDialogBuilder(ctx)
            b.set_title("Удалить плагин и все файлы?")
            b.set_message("Будут удалены рантайм, кэш, .profile, настройки и локальные данные, а также сам плагин. Действие необратимо.")
            b.set_positive_button("Удалить", lambda d, w: self._purge_all_plugin_files())
            b.set_negative_button("Отмена", lambda d, w: self._hap("dismiss"))
            run_on_ui_thread(b.show)
        except Exception as e:
            self.log("[cache] purge confirm: " + _cause(e))

    def _purge_all_plugin_files(self, silent=False):
        import os
        removed = 0
        targets = [_resolve_data_dir()]
        try:
            if get_plugins_dir is not None:
                targets.extend(_runtime_dir_candidates())
        except Exception:
            pass
        for p in targets:
            removed += self._remove_path_quiet(p)
        try:
            for pdir in self._profile_dirs():
                if not os.path.isdir(pdir):
                    continue
                for n in os.listdir(pdir):
                    if n.lower().endswith(".profile"):
                        removed += self._remove_path_quiet(os.path.join(pdir, n))
        except Exception: pass
        # the installed .plugin file itself. Resolved through the helper, not
        # getPluginPath(__id__): the host files us under meta.yml's id, which is not
        # __id__, and an install older than the rename is filed under an older id again.
        try:
            pp = self._access_host_plugin_path()
            if pp: removed += self._remove_path_quiet(str(pp))
        except Exception as e:
            self.log("[cache] purge path: " + _cause(e))
        if not silent:
            self._hap("crunch", essential=True)
            self._toast("Плагин и все файлы удалены — перезапусти Telegram")

    def _clear_plugin_cache(self):
        import os, shutil
        removed = 0
        try:
            for root in _runtime_dir_candidates():
                if os.path.isdir(root):
                    shutil.rmtree(root, ignore_errors=True); removed += 1
        except Exception:
            pass
        self._prod = None
        if removed:
            self._hap("crunch", essential=True)
        self._toast("Кэш очищен ✓" if removed else "Кэш уже пуст")

    def _about_avatar_drawable(self, user):
        if AvatarDrawable is None:
            return None
        try:
            if user is not None:
                return AvatarDrawable(user)
        except Exception:
            pass
        try:
            d = AvatarDrawable()
            try: d.setInfo(0, CHIMERANFT_ABOUT_USERNAME, "")
            except Exception: pass
            return d
        except Exception:
            return None

    def _bind_about_avatar(self, av, user):
        """Show the support user's profile photo (placeholder initials until loaded)."""
        if av is None:
            return
        drawable = self._about_avatar_drawable(user)
        try:
            if drawable is not None:
                av.setImageDrawable(drawable)
        except Exception:
            pass
        if user is not None:
            try:
                av.setForUserOrChat(user, drawable)
            except Exception:
                try: av.setForUserOrChat(user)
                except Exception: pass

    def _current_user(self):
        """The logged-in account's User object (its avatar is cached locally → loads instantly)."""
        acc = _selected_account()
        try:
            mc = jclass("org.telegram.messenger.MessagesController").getInstance(acc)
            uc = UserConfig.getInstance(acc)
            u = None
            try: u = mc.getUser(uc.getClientUserId())
            except Exception: u = None
            if u is None:
                try: u = uc.getCurrentUser()
                except Exception: u = None
            return u
        except Exception:
            return None

    def _show_about_sheet(self, ctx=None, expand_changelog=False):
        """«О плагине» — one sheet in two sections: what the plugin is (avatar,
        description, Поддержка) and, below a separator, the changelog folded into a
        plate that opens in place. `expand_changelog` starts it open, which is how the
        once-per-version auto-open and the row's own tap both arrive here."""
        try:
            if ctx is None:
                frag = get_last_fragment()
                ctx = frag.getParentActivity() if frag else None
            if ctx is None:
                try: ctx = ApplicationLoader.applicationContext
                except Exception: ctx = None
            if ctx is None or BottomSheet is None:
                self._toast("OpenChimeraNFT " + __version__)
                return
            sheet = BottomSheet(ctx, True)
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(16), AndroidUtilities.dp(16), AndroidUtilities.dp(16))

            row = LinearLayout(ctx)
            row.setOrientation(LinearLayout.HORIZONTAL)
            row.setGravity(Gravity.CENTER_VERTICAL)
            av = BackupImageView(ctx)
            try: av.setRoundRadius(AndroidUtilities.dp(14))
            except Exception: pass
            # the user's OWN profile photo (cached locally → loads immediately)
            self._bind_about_avatar(av, self._current_user())
            # The only way back into the hook diagnostics now that «Плавность» is out of the menu.
            # Deliberately here and not on a menu row: rows already own long press (it yields the
            # deep link to that setting), and nobody long-presses their own avatar inside an About
            # sheet by accident. pollHooks() is the one instrument that answers «какой хук стоит
            # кадра» on a real device, and §11.16 is the record of what happens without it.
            self._attach_long_press(av, self._show_hook_diagnostics)
            row.addView(av, LinearLayout.LayoutParams(AndroidUtilities.dp(64), AndroidUtilities.dp(64)))
            desc = TextView(ctx)
            desc.setText(S("about_description", __version__))
            desc.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            try: desc.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception: pass
            lpd = LinearLayout.LayoutParams(0, -2, 1.0); lpd.leftMargin = AndroidUtilities.dp(12)
            row.addView(desc, lpd)
            root.addView(row, LinearLayout.LayoutParams(-1, -2))

            btn = TextView(ctx)
            btn.setText(S("about_support"))
            btn.setGravity(Gravity.CENTER)
            btn.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
            try:
                btn.setTextColor(Theme.getColor(Theme.key_featuredStickers_buttonText))
                bbg = GradientDrawable(); bbg.setCornerRadius(float(AndroidUtilities.dp(12)))
                bbg.setColor(Theme.getColor(Theme.key_featuredStickers_addButton))
                btn.setBackground(self._ripple_bg(bbg, Theme.getColor(Theme.key_featuredStickers_addButton)))
                btn.setElevation(float(AndroidUtilities.dp(2)))
            except Exception:
                pass
            btn.setPadding(AndroidUtilities.dp(12), AndroidUtilities.dp(12), AndroidUtilities.dp(12), AndroidUtilities.dp(12))

            def _support(v):
                try:
                    if Browser is not None:
                        Browser.openUrl(v.getContext(), CHIMERANFT_SUPPORT_URL)
                except Exception:
                    pass
                try: sheet.dismiss()
                except Exception: pass
            btn.setOnClickListener(self._click(_support))
            lpb = LinearLayout.LayoutParams(-1, -2); lpb.topMargin = AndroidUtilities.dp(14)
            root.addView(btn, lpb)

            # Between «Поддержка» and the changelog: the one switch that controls the only sheet
            # this plugin still opens on its own.
            self._add_channel_reminder_row(ctx, root)

            # Second section. Skipped entirely when no version has text — an empty plate
            # that opens onto nothing is worse than no plate.
            if self._changelog_entries():
                self._add_changelog_section(ctx, root, expand=bool(expand_changelog))

            self._changelog_sheet = sheet
            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)
        except Exception as e:
            self.log("[about] sheet: " + _cause(e))
            self._toast("OpenChimeraNFT " + __version__)

    def _add_channel_reminder_row(self, ctx, root):
        """«Напоминать о канале разработчика» — the switch that owns the subscribe prompt.

        ON (the default) means a non-subscriber sees the prompt once after every install or
        update. OFF means it never appears again, on any future update, until it is switched back
        on here — or until the plugin is removed, which takes its settings with it."""
        try:
            TextCheckCell = jclass("org.telegram.ui.Cells.TextCheckCell")
            cell = TextCheckCell(ctx, 21, True)
            cell.setTextAndValueAndCheck(
                S("channel_reminder_toggle"), S("channel_reminder_toggle_sub"),
                bool(self._developer_channel_reminder_enabled()), True, False)

            def _toggle(_v, _cell=cell):
                nv = not bool(_cell.isChecked())
                _cell.setChecked(nv)
                self._hap_toggle(nv)
                self._set_developer_channel_reminder(nv)

            cell.setOnClickListener(self._click(_toggle))
            lp = LinearLayout.LayoutParams(-1, -2)
            lp.topMargin = AndroidUtilities.dp(8)
            lp.leftMargin = lp.rightMargin = -AndroidUtilities.dp(16)   # the cell has its own padding
            root.addView(cell, lp)
        except Exception as error:
            self.log("[about] channel reminder row: " + _cause(error))

    def _add_changelog_section(self, ctx, root, expand=False):
        """Separator + a tappable «Что нового» plate whose body expands in place."""
        title_color = int(self._theme_color("key_windowBackgroundWhiteBlackText", 0xFFFFFFFF))
        sub_color = int(self._theme_color("key_windowBackgroundWhiteGrayText", 0xFF9AA3AE))
        accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))

        separator = View(ctx)
        try: separator.setBackgroundColor(int(self._theme_color("key_divider", sub_color)))
        except Exception: pass
        lp_sep = LinearLayout.LayoutParams(-1, max(1, AndroidUtilities.dp(1) // 2))
        lp_sep.topMargin = AndroidUtilities.dp(18)
        root.addView(separator, lp_sep)

        plate = LinearLayout(ctx)
        plate.setOrientation(LinearLayout.VERTICAL)
        lp_plate = LinearLayout.LayoutParams(-1, -2)
        lp_plate.topMargin = AndroidUtilities.dp(14)
        root.addView(plate, lp_plate)

        head = LinearLayout(ctx)
        head.setOrientation(LinearLayout.HORIZONTAL)
        head.setGravity(Gravity.CENTER_VERTICAL)
        head.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(12),
                        AndroidUtilities.dp(14), AndroidUtilities.dp(12))
        try:
            plate_bg = self._create_round_rect(
                self._theme_color("key_dialogBackground", 0xFF1A1A1A), radius_dp=14)
            head.setBackground(self._ripple_bg(plate_bg, accent))
        except Exception:
            pass

        labels = LinearLayout(ctx)
        labels.setOrientation(LinearLayout.VERTICAL)
        head_title = TextView(ctx)
        head_title.setText(S("changelog_title"))
        head_title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
        head_title.setTextColor(title_color)
        try: head_title.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
        except Exception: pass
        labels.addView(head_title, LinearLayout.LayoutParams(-1, -2))
        head_sub = TextView(ctx)
        head_sub.setText(S("changelog_subtitle", self._changelog_entries()[0][0]))
        head_sub.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        head_sub.setTextColor(sub_color)
        lp_head_sub = LinearLayout.LayoutParams(-1, -2)
        lp_head_sub.topMargin = AndroidUtilities.dp(1)
        labels.addView(head_sub, lp_head_sub)
        head.addView(labels, LinearLayout.LayoutParams(0, -2, 1.0))

        # A caret, not an icon name: this has to read the same on every fork's theme.
        caret = TextView(ctx)
        caret.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        caret.setTextColor(accent)
        head.addView(caret, LinearLayout.LayoutParams(-2, -2))
        plate.addView(head, LinearLayout.LayoutParams(-1, -2))

        body = self._changelog_body_view(ctx, title_color, accent)
        lp_body = LinearLayout.LayoutParams(-1, -2)
        lp_body.topMargin = AndroidUtilities.dp(4)
        plate.addView(body, lp_body)

        state = {"open": bool(expand)}

        def _render():
            opened = bool(state["open"])
            caret.setText("▲" if opened else "▼")
            body.setVisibility(View.VISIBLE if opened else View.GONE)

        def _toggle(_view=None):
            state["open"] = not state["open"]
            _render()
            self._hap("reveal" if state["open"] else "select")

        head.setOnClickListener(self._click(_toggle, hap=None))
        _render()

    def _changelog_body_view(self, ctx, title_color, accent):
        """The bulleted history, newest version first, in its own scroller so a long
        history cannot push the rest of the sheet off screen."""
        body = LinearLayout(ctx)
        body.setOrientation(LinearLayout.VERTICAL)
        body.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(4),
                        AndroidUtilities.dp(14), AndroidUtilities.dp(4))
        for index, (version, lines) in enumerate(self._changelog_entries()):
            if index > 0:
                header = TextView(ctx)
                header.setText(S("changelog_version", version))
                header.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
                header.setTextColor(accent)
                try: header.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                except Exception: pass
                lp_header = LinearLayout.LayoutParams(-1, -2)
                lp_header.topMargin = AndroidUtilities.dp(16)
                body.addView(header, lp_header)
            for line in lines:
                row = LinearLayout(ctx)
                row.setOrientation(LinearLayout.HORIZONTAL)
                bullet = TextView(ctx)
                bullet.setText("•")
                bullet.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                bullet.setTextColor(accent)
                row.addView(bullet, LinearLayout.LayoutParams(AndroidUtilities.dp(16), -2))
                text = TextView(ctx)
                text.setText(str(line))
                text.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                text.setTextColor(title_color)
                row.addView(text, LinearLayout.LayoutParams(0, -2, 1.0))
                lp_row = LinearLayout.LayoutParams(-1, -2)
                lp_row.topMargin = AndroidUtilities.dp(10)
                body.addView(row, lp_row)

        scroll = ScrollView(ctx)
        scroll.addView(body, FrameLayout.LayoutParams(-1, -2))

        # Adapt to the text — only a long history scrolls, and only up to the cap.
        def _cap():
            try:
                limit = AndroidUtilities.dp(280)
                if scroll.getHeight() > limit:
                    lp = scroll.getLayoutParams(); lp.height = limit
                    scroll.setLayoutParams(lp)
            except Exception:
                pass
        try: run_on_ui_thread(_cap, 60)
        except Exception: pass
        return scroll

    def _open_help_carousel_legacy(self, ctx=None):
        """Four swipeable fallback help pages."""
        try:
            if ctx is None:
                fragment = get_last_fragment()
                ctx = fragment.getParentActivity() if fragment else None
            if ctx is None or BottomSheet is None:
                self._toast("\u041f\u043e\u043c\u043e\u0449\u044c OpenChimeraNFT")
                return

            pages = [
                ("\U0001F381", "\u041f\u043e\u0434\u0430\u0440\u043a\u0438 \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u0435",
                 "\u0414\u043e\u0431\u0430\u0432\u043b\u044f\u0439 NFT, \u043c\u0435\u043d\u044f\u0439 \u0438\u0445 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0438 \u0441\u043a\u0440\u044b\u0432\u0430\u0439 \u043e\u0442 \u0434\u0440\u0443\u0433\u0438\u0445 \u043b\u044e\u0434\u0435\u0439."),
                ("\U0001F464", "Username",
                 "\u0412\u043a\u043b\u044e\u0447\u0430\u0439 \u0438 \u043c\u0435\u043d\u044f\u0439 \u043a\u043e\u043b\u043b\u0435\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0435 username \u0432 \u043a\u043e\u043c\u043f\u0430\u043a\u0442\u043d\u043e\u043c \u043e\u043a\u043d\u0435."),
                ("\U0001F517", "Collectible Number",
                 "\u0414\u043e\u0431\u0430\u0432\u044c \u043d\u043e\u043c\u0435\u0440, \u0441\u043e\u0445\u0440\u0430\u043d\u0438 \u0435\u0433\u043e \u0438 \u0441\u0440\u0430\u0437\u0443 \u0443\u0432\u0438\u0434\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u0435."),
                ("\u2b50", "\u0420\u0435\u0439\u0442\u0438\u043d\u0433 \u043f\u0440\u043e\u0444\u0438\u043b\u044f",
                 "\u0412\u044b\u0431\u0435\u0440\u0438 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0438 \u043e\u0447\u043a\u0438 \u0432 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 Telegram."),
            ]
            colors = [self._col(c) for c in (0xFF7556B7, 0xFF519C8C, 0xFF4D7FAD, 0xFFB07B45)]
            state = {"page": 0, "down_x": 0.0, "animating": False}
            sheet = BottomSheet(ctx, True)
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(8), AndroidUtilities.dp(16), AndroidUtilities.dp(18))
            try: root.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundWhite))
            except Exception: pass

            top = LinearLayout(ctx)
            top.setOrientation(LinearLayout.HORIZONTAL)
            top.setGravity(Gravity.CENTER_VERTICAL)
            top_title = TextView(ctx)
            top_title.setText("\u041a\u0430\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 OpenChimeraNFT")
            top_title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 17)
            close = TextView(ctx)
            close.setText("\u00d7")
            close.setGravity(Gravity.CENTER)
            close.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 30)
            try:
                top_title.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                top_title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
                close.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception: pass
            top.addView(top_title, LinearLayout.LayoutParams(0, AndroidUtilities.dp(48), 1.0))
            top.addView(close, LinearLayout.LayoutParams(AndroidUtilities.dp(48), AndroidUtilities.dp(48)))
            root.addView(top, LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48)))

            hero = FrameLayout(ctx)
            hero_icon = TextView(ctx)
            hero_icon.setGravity(Gravity.CENTER)
            hero_icon.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 82)
            gif_label = TextView(ctx)
            gif_label.setGravity(Gravity.CENTER)
            gif_label.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
            try: gif_label.setTextColor(self._col(0xCCFFFFFF))
            except Exception: pass
            hero.addView(hero_icon, self._frame(hero_icon, -1, -1, Gravity.CENTER, 0, 0, 0, 0))
            hero.addView(gif_label, self._frame(gif_label, -1, 34, Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL, 0, 0, 0, 10))
            lp_hero = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(300)); lp_hero.topMargin = AndroidUtilities.dp(4)
            root.addView(hero, lp_hero)

            title = TextView(ctx)
            title.setGravity(Gravity.CENTER)
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 24)
            try:
                title.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception: pass
            lp_title = LinearLayout.LayoutParams(-1, -2); lp_title.topMargin = AndroidUtilities.dp(18)
            root.addView(title, lp_title)

            description = TextView(ctx)
            description.setGravity(Gravity.CENTER)
            description.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
            description.setMaxLines(3)
            try: description.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception: pass
            lp_desc = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(66)); lp_desc.topMargin = AndroidUtilities.dp(7)
            root.addView(description, lp_desc)

            dots = TextView(ctx)
            dots.setGravity(Gravity.CENTER)
            dots.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 17)
            root.addView(dots, LinearLayout.LayoutParams(-1, AndroidUtilities.dp(36)))

            action = TextView(ctx)
            action.setGravity(Gravity.CENTER)
            action.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 17)
            try:
                action.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                action.setTextColor(Theme.getColor(Theme.key_featuredStickers_buttonText))
            except Exception: pass
            lp_action = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(54)); lp_action.topMargin = AndroidUtilities.dp(6)
            root.addView(action, lp_action)

            def _rounded(color, radius=20):
                return self._create_round_rect(color, radius)

            def _bind(index):
                state["page"] = index
                icon, heading, body = pages[index]
                hero_icon.setText(icon)
                gif_label.setText("GIF \u2022 %d/5" % (index + 1))
                hero.setBackground(_rounded(colors[index], 24))
                title.setText(heading)
                description.setText(body)
                dots.setText("  ".join("\u25cf" if i == index else "\u2022" for i in range(5)))
                dots.setTextColor(colors[index])
                action.setText("\u0413\u043e\u0442\u043e\u0432\u043e" if index == 4 else "\u0414\u0430\u043b\u0435\u0435")
                action.setBackground(self._ripple_bg(_rounded(colors[index], 16), colors[index]))

            def _show_page(index, direction):
                index = max(0, min(4, int(index)))
                if index == state["page"] or state.get("animating"):
                    return
                # Fires only on a page that actually changes, so holding «Далее» at the last page
                # stays silent instead of ticking against a wall.
                self._hap("swipe")
                if not self._smooth_mode_enabled():
                    _bind(index); return
                state["animating"] = True
                distance = float(AndroidUtilities.dp(34) * direction)
                views = (hero, title, description, dots)
                for view in views:
                    view.animate().cancel()
                    view.animate().alpha(0.0).translationX(-distance).setDuration(110).start()
                def _enter():
                    try:
                        _bind(index)
                        for view in views:
                            view.setTranslationX(distance)
                            view.animate().alpha(1.0).translationX(0.0).setDuration(210).start()
                    finally:
                        state["animating"] = False
                run_on_ui_thread(_enter, 115)

            def _next(_view=None):
                current = int(state["page"])
                if current == 4:
                    self._hap("success")     # reached the end of the tour, not just closed it
                    sheet.dismiss()
                else:
                    _show_page(current + 1, 1)

            close.setOnClickListener(self._click(lambda _v: sheet.dismiss(), hap="dismiss"))
            action.setOnClickListener(self._click(_next, hap=None))

            MotionEvent = jclass("android.view.MotionEvent")
            down, up = int(MotionEvent.ACTION_DOWN), int(MotionEvent.ACTION_UP)
            class _Swipe(dynamic_proxy(View.OnTouchListener)):
                def onTouch(self2, view, event):
                    try:
                        event_action = int(event.getActionMasked())
                        if event_action == down:
                            state["down_x"] = float(event.getX()); return True
                        if event_action == up:
                            delta = float(event.getX()) - float(state["down_x"])
                            current = int(state["page"])
                            if delta < -AndroidUtilities.dp(42) and current < 4:
                                _show_page(current + 1, 1)
                            elif delta > AndroidUtilities.dp(42) and current > 0:
                                _show_page(current - 1, -1)
                            return True
                    except Exception:
                        pass
                    return True

            swipe = _Swipe()
            hero.setOnTouchListener(swipe)
            self._help_carousel_refs = [swipe]
            self._help_sheet = sheet
            _bind(0)
            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)

            pulse = {"up": False}
            def _pulse():
                try:
                    if getattr(self, "_help_sheet", None) is not sheet or not sheet.isShowing():
                        return
                    pulse["up"] = not pulse["up"]
                    scale = 1.055 if pulse["up"] else 0.96
                    hero_icon.animate().scaleX(scale).scaleY(scale).setDuration(700).start()
                    run_on_ui_thread(_pulse, 740)
                except Exception:
                    pass
            run_on_ui_thread(_pulse, 320)
        except Exception as e:
            self.log("[help-carousel] " + _cause(e))
            self._toast("\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043f\u043e\u043c\u043e\u0449\u044c")

    def _install_native_help_carousel_hook(self):
        """Replace Premium's source list only while our native help sheet is constructed."""
        if getattr(self, "_native_help_hook_done", False):
            return True
        if MethodHook is None or getattr(self, "hook_method", None) is None:
            return False
        try:
            preview_class = JavaClass.forName("org.telegram.ui.PremiumPreviewFragment")
            fill_method = None
            for method in preview_class.getDeclaredMethods():
                if method.getName() == "fillPremiumFeaturesList" and method.getParameterCount() == 3:
                    fill_method = method
                    break
            if fill_method is None:
                return False
            fill_method.setAccessible(True)
            plugin = self

            class _NativeHelpFillHook(MethodHook):
                def after_hooked_method(self2, param):
                    if not bool(getattr(plugin, "_native_help_building", False)):
                        return
                    try:
                        target = param.args[0]
                        target.clear()
                        PremiumData = jclass("org.telegram.ui.PremiumPreviewFragment$PremiumFeatureData")
                        RDrawable = jclass("org.telegram.messenger.R$drawable")
                        rows = [
                            (97, "msg_premium_avatar", "\u041f\u043e\u0434\u0430\u0440\u043a\u0438 \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u0435",
                             "\u0414\u043e\u0431\u0430\u0432\u043b\u044f\u0439 NFT, \u043c\u0435\u043d\u044f\u0439 \u0438\u0445 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0438 \u0441\u043a\u0440\u044b\u0432\u0430\u0439 \u043e\u0442 \u0434\u0440\u0443\u0433\u0438\u0445 \u043b\u044e\u0434\u0435\u0439."),
                            (98, "msg_premium_badge", "Username",
                             "\u0412\u043a\u043b\u044e\u0447\u0430\u0439 \u0438 \u043c\u0435\u043d\u044f\u0439 \u043a\u043e\u043b\u043b\u0435\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0435 username \u0432 \u043e\u0434\u043d\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043a\u0442\u043d\u043e\u043c \u043e\u043a\u043d\u0435."),
                            (99, "msg_link", "Collectible Number",
                             "\u0414\u043e\u0431\u0430\u0432\u044c \u043d\u043e\u043c\u0435\u0440, \u0441\u043e\u0445\u0440\u0430\u043d\u0438 \u0435\u0433\u043e \u0438 \u0441\u0440\u0430\u0437\u0443 \u0443\u0432\u0438\u0434\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u0435."),
                            (100, "premium_colors", "\u0420\u0435\u0439\u0442\u0438\u043d\u0433 \u043f\u0440\u043e\u0444\u0438\u043b\u044f",
                             "\u0412\u044b\u0431\u0435\u0440\u0438 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0438 \u043e\u0447\u043a\u0438 \u0432 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 Telegram."),
                        ]
                        for feature_type, icon_name, title, description in rows:
                            try: icon = int(getattr(RDrawable, icon_name))
                            except Exception: icon = 0
                            target.add(PremiumData(feature_type, icon, title, description))
                    except Exception as e:
                        plugin.log("[native-help] fill: " + _cause(e))

            ref = self.hook_method(fill_method, _NativeHelpFillHook())
            self._native_help_hook_ref = ref
            self._native_help_hook_done = True
            return True
        except Exception as e:
            self.log("[native-help] hook: " + _cause(e))
            return False

    def _ensure_help_nft_video(self):
        """Extract the bundled first tutorial to a stable local file for ExoPlayer."""
        cached = getattr(self, "_help_nft_video_path", None)
        if cached and os.path.isfile(cached):
            return cached
        try:
            raw = _elyx_assets.help_nft_gifts.content_bytes() if _elyx_assets is not None else None
            if not raw:
                return None
            expected = "903f52550a492069726557a41e04b2f323c7963b62f13ed97c854e3533a971a4"
            if _hashlib.sha256(raw).hexdigest() != expected:
                raise RuntimeError("help video hash mismatch")
            folder = os.path.join(_resolve_data_dir(), "help_media")
            os.makedirs(folder, exist_ok=True)
            path = os.path.join(folder, "nft_gifts_v1.mp4")
            valid = False
            try:
                if os.path.isfile(path) and os.path.getsize(path) == len(raw):
                    with open(path, "rb") as existing:
                        valid = _hashlib.sha256(existing.read()).hexdigest() == expected
            except Exception:
                valid = False
            if not valid:
                temporary = path + ".tmp"
                with open(temporary, "wb") as output:
                    output.write(raw)
                    output.flush()
                os.replace(temporary, path)
            self._help_nft_video_path = path
            return path
        except Exception as e:
            self.log("[native-help] extract video: " + _cause(e))
            return None

